(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["pt"] = {"ui":{"lead":"Como os jogos foram encontrados, esquecidos, decifrados e transformados? Leia {n} histórias e acerte todas as perguntas do quiz final para ganhar um carimbo.","card":"Cartão de carimbos","cardN":"{n} de {of} conquistados","cardAll":"Todos conquistados!","no":"História {n}","mins":"{n} min","stamped":"Carimbado","back":"Todas as histórias","quiz":"Quiz rápido","links":"Ver e jogar","game":"Jogo","exhibit":"Acervo","art":"Obra","room":"Sala","room_chance":"Acaso","qn":"Pergunta {n} de {of}","right":"Certo!","wrong":"Quase… a resposta certa está marcada.","got":"Carimbado!","again":"Tudo certo!","gotSub":"Já está no seu cartão de carimbos.","missed":"{n} erro(s)","retrySub":"Acerte todas as perguntas para ganhar o carimbo. Releia a história e tente de novo.","retry":"Tentar de novo","room_paint":"Na arte","room_map":"Mapa","kfH":"Pontos principais","tlH":"Linha do tempo","refH":"Fontes e leituras","picLink":"abre a página do museu"},"ex":{"ur":"Tabuleiro do Jogo Real de Ur","liubo":"Tabuleiro e peças de liubo","pyrgus":"Torre de dados romana","sugoroku":"Tabuleiro de sugoroku do Shōsōin","nishapur":"Xadrez de Nishapur","lewis":"Peças de xadrez de Lewis","senet":"Caixa de senet de Tutancâmon","ballinderry":"Tabuleiro de Ballinderry","goose":"Tabuleiro de xadrez e do jogo do ganso","kofukuji":"Peças de shogi de Kōfuku-ji","shosoin":"Tabuleiro de go do Shōsōin"},"paint":{"liubo":"Duas figuras jogando liubo","sugoroku":"Duas moças jogando sugoroku","shahnama":"Buzurgmihr decifra o xadrez","nefertari":"A rainha Nefertari jogando senet","chaupar":"Shiva e Parvati jogando chaupar","shogi":"Jovem casal jogando shogi","hydria":"Aquiles e Ájax a jogar um jogo de tabuleiro (hídria)","eakins":"Os jogadores de xadrez","weiqi":"Prato com imortais jogando weiqi","webb":"Os jogadores de gamão (armário)","liberale":"Os jogadores de xadrez","mirror":"Estojo de espelho com um casal jogando xadrez","morris":"Um tabuleiro de jogo (trilha)","leifeng":"Jogo de tabuleiro do pagode Leifeng","teniers":"Partida de gamão","imari":"Prato com dois homens jogando go","shoei":"As quatro artes","tutinama":"O macaco morde o príncipe, seu parceiro de xadrez (mogol, c. 1560)","ingram":"O jogo do xadrez chinês","umaya":"Biombo das cavalariças (go e shogi na varanda)","kiyohiro":"Jogadoras de sugoroku","vuillard":"A partida de damas (de Paisagens e interiores)","kangra":"Casal a jogar chaupar num terraço","posada":"Jogo da Glória (Jogo do Ganso)","jintile":"Placa com mulheres a jogar um jogo de tabuleiro","pvl":"Homens a jogar aos dados"},"ur":{"title":"Como um jogo de 4.500 anos recuperou suas regras","lead":"O tabuleiro dos túmulos reais de Ur veio sem instruções. A pista estava numa tábua escrita dois mil anos depois.","s":["Na década de 1920, Leonard Woolley escavou os túmulos reais de Ur, no sul do Iraque, e encontrou um tabuleiro de vinte casas incrustado de concha e lápis-lazúli, de cerca de 2600–2400 a.C. Tabuleiros parecidos surgiram por todo o Oriente Médio: o jogo foi muito jogado, e por muito tempo.","Mas nada que explicasse como jogar apareceu com eles. Tabuleiro, peças e dados — e nenhuma regra: um problema comum nos jogos antigos.","A pista estava nos depósitos do Museu Britânico: uma tábua cuneiforme copiada em 177/176 a.C. pelo escriba babilônio Itti-Marduk-balāṭu a partir de uma tábua de um certo Iddin-Bēl. Foi escrita mais de dois mil anos depois do tabuleiro.","No início dos anos 1980, Irving Finkel, do Museu Britânico, percebeu que a tábua descrevia o mesmo jogo de vinte casas. O verso mostra o tabuleiro, com presságios para cada casa onde se para. A partir da tábua e do próprio tabuleiro, Finkel reconstruiu um jogo de corrida para dois.","Sua reconstrução é jogada hoje no mundo todo. Ninguém pode garantir que em Ur se jogava exatamente assim. Mesmo assim, em Kochi, no sul da Índia, um jogo parecido ainda era jogado até os anos 1950 — sinal da longa vida desse jogo."],"quiz":[["Quando foi escrita a tábua que trouxe as regras?","No século II a.C., mais de 2.000 anos depois do tabuleiro","Por volta de 2600 a.C., como o tabuleiro","Na Idade Média (século XII)","No século XIX"],["Quem decifrou a tábua e reconstruiu as regras?","Irving Finkel","Howard Carter","Jean-François Champollion","Arthur Evans"],["O que a tábua diz sobre parar nas casas?","Presságios de boa ou má sorte","Nomes de reis","Valores de impostos","Só nomes de estrelas"]],"kf":["Os tabuleiros são de cerca de 2600–2400 a.C., dos túmulos reais de Ur, no sul do Iraque","As regras foram reconstruídas a partir de uma tábua escrita mais de 2.000 anos depois","20 casas, sete peças por lado, dados de quatro faces"],"more":[{"h":"Túmulos reais e um “jogo real”","p":["Woolley encontrou no Cemitério Real de Ur não um, mas vários tabuleiros de vinte casas. O mais conhecido, hoje no Museu Britânico, é de madeira com incrustações de concha, calcário vermelho e lápis-lazúli, e deu ao jogo o nome de “Jogo Real de Ur”.","Mas não era um jogo só de reis. Tabuleiros iguais aparecem da Mesopotâmia ao Egito e ao Mediterrâneo oriental, e num palácio assírio um tabuleiro chegou a ser riscado na base de um grande touro alado de cabeça humana que guardava uma porta — ao que parece, pelos guardas."],"cap":["O Jogo Real de Ur do Museu Britânico — gire-o em 3D na sala Acervo"]},{"h":"Como funciona o tabuleiro","p":["As vinte casas formam um bloco de doze (3×4) e outro de seis (3×2), ligados por uma estreita “ponte” de duas. Cinco casas têm uma roseta; nas regras reconstruídas, parar nelas dá outro lance e é uma casa onde não se pode ser capturado.","Os dados são tetraedros com duas das quatro pontas marcadas. Lançam-se quatro e anda-se conforme o número de pontas marcadas viradas para cima: de 0 a 4. O 2 é o mais comum (6 em 16); 0 e 4 saem só 1 em 16. Dá para lançá-los na sala “Acaso” do museu."],"cap":["As vinte casas e as cinco rosetas. Os números verdes são o caminho de um jogador, casa a casa (regras reconstruídas)","Como caem quatro dados tetraédricos (em 16 casos igualmente prováveis)"]},{"h":"O que diz a tábua","p":["A frente explica o jogo; o verso desenha o tabuleiro com signos do zodíaco nas casas. As frases de cada casa soam como presságios — “encontrarás um amigo”, “beberás boa cerveja” —, então o jogo estava ligado à sorte.","Mas parte da tábua está quebrada e nem todas as regras podem ser lidas. A reconstrução de Finkel monta o jogo mais coerente a partir das linhas legíveis e da forma do tabuleiro; outros estudiosos propuseram outras versões."]},{"h":"Os últimos jogadores, na Índia","p":["Finkel soube depois que a comunidade judaica de Kochi (Cochim), no sul da Índia, jogava até muito recentemente um jogo de vinte casas, num tabuleiro de forma bem parecida.","Ele passou de geração em geração nas casas até a mudança para Israel nos anos 1950. Talvez o jogo tenha chegado à Índia por antigas rotas de comércio e sobrevivido por mais de quatro mil anos."]}],"tl":[["c. 2600–2400 a.C.","Tabuleiros de vinte casas são postos nos túmulos reais de Ur"],["Século VIII a.C.","Um tabuleiro é riscado na base de um guardião de porta num palácio assírio"],["177/176 a.C.","Um escriba babilônio copia a tábua das regras"],["1922–1934","Woolley escava Ur e encontra os tabuleiros"],["Início dos anos 1980","Finkel lê a tábua e reconstrói as regras"],["Até os anos 1950","Um jogo muito parecido é jogado em Kochi, no sul da Índia"]]},"liubo":{"title":"Por que o liubo desapareceu?","lead":"Sob os Han, do imperador ao povo, todos jogavam. Em poucos séculos, até as regras foram esquecidas.","s":["O liubo foi a grande febre da China Han (206 a.C. – 220 d.C.). Aparece em figuras funerárias, relevos em pedra e até na decoração de espelhos, e imortais são muitas vezes mostrados jogando.","Depois da queda dos Han, o liubo declinou depressa e, ao que parece, na dinastia Tang suas regras já estavam perdidas. Não se sabe bem por quê; uma hipótese é que os jogadores passaram a outros jogos, como o weiqi (go).","Sobraram os tabuleiros e os utensílios. Os tabuleiros trazem um desenho característico em forma de T, L e V, e as jogadas provavelmente eram decididas lançando varetas finas. O mesmo desenho decora os chamados espelhos TLV.","Pistas escritas também vêm se juntando. Em 1993, um túmulo Han em Yinwan (Jiangsu) revelou um texto divinatório que usa o diagrama do tabuleiro. O túmulo de Liu He, marquês de Haihun, escavado na década de 2010, trouxe mais de mil tiras de bambu sobre o liubo, ainda em estudo.","O liubo do Atlas é uma reconstrução baseada nessas pistas. Os estudiosos o reconstroem de formas um pouco diferentes, e as regras verdadeiras ainda não são totalmente conhecidas — novas descobertas podem mudar o jeito de jogar."],"quiz":[["Em que dinastia o liubo foi muito popular?","Han","Ming","Qing","Song"],["Onde foram achadas mais de mil tiras de bambu sobre o liubo?","No túmulo de Liu He, marquês de Haihun","No mausoléu do Primeiro Imperador","Nas grutas de Dunhuang","Na Cidade Proibida"],["O que provavelmente se lançava para decidir as jogadas no liubo?","Varetas finas","Um dado de vinte faces","Um pião","Cartas ilustradas"]],"kf":["Muito popular na China dos Reinos Combatentes aos Han (séc. V a.C. – séc. III d.C.)","Um tabuleiro com linhas em T, L e V; lançavam-se varetas finas para mover","Decaiu depressa após a queda dos Han, e suas regras ainda não são totalmente conhecidas"],"more":[{"h":"O tabuleiro TLV","p":["O tabuleiro de liubo é quadrado, com um quadrado no centro, um T no meio de cada lado, formas de L em volta e de V nos cantos. Acredita-se que as peças avançavam sobre essas linhas e entre elas.","As mesmas linhas aparecem no verso de espelhos (“espelhos TLV”) e em relógios de sol. Alguns estudiosos leem o tabuleiro como um mapa do cosmos — céu, terra e as quatro direções —, sinal de que o liubo era mais que um passatempo."],"cap":["As linhas de um tabuleiro de liubo (padrão TLV): um quadrado central, um T em cada lado, formas de L e V perto dos cantos"]},{"h":"Como se jogava","p":["A maioria dos estudiosos acha que cada jogador tinha seis peças e lançava finas varetas de bambu para decidir o lance. O “seis” (liu) do nome viria dessas seis varetas ou seis peças.","Uma peça que avançava parece que virava uma poderosa “coruja” (xiao). Um poema de cerca do século III a.C., “Chamando a alma”, dos Cantos de Chu, diz: “virando coruja, avança e grita ‘cinco brancos!’”. Textos descrevem também um modo de jogo em que as peças pescavam “peixes” na “água” do centro."],"cap":["Duas figuras jogando liubo, feitas para um túmulo Han (Metropolitan Museum of Art)"]},{"h":"Jogos vindos dos túmulos","p":["O túmulo 3 de Mawangdui, em Changsha (Hunan), de cerca de 168 a.C., guardava um jogo completo — tabuleiro, peças e varetas — numa caixa laqueada, para que o morto pudesse jogar no além.","Relevos das paredes dos túmulos mostram muitas vezes imortais jogando liubo no alto das montanhas. O jogo estava ligado ao mundo dos imortais e à vida longa."],"cap":["O tabuleiro de liubo do museu — veja-o em 3D na sala Acervo"]}],"tl":[["Séc. V–III a.C. (Reinos Combatentes)","Tabuleiros de liubo começam a ir para os túmulos"],["c. séc. III a.C.","“Chamando a alma” descreve uma partida de liubo"],["c. 168 a.C.","Um jogo completo entra no túmulo 3 de Mawangdui"],["206 a.C. – 220 d.C. (Han)","Jogado de imperadores a gente comum; em relevos e espelhos"],["Tang (séc. VII–X)","Acredita-se que as regras já estavam esquecidas"],["1993","Surge nos túmulos Han de Yinwan um texto de adivinhação com o tabuleiro"],["Anos 2010","Tiras de bambu sobre o liubo aparecem no túmulo do marquês de Haihun, Liu He"]]},"zeno":{"title":"O lance azarado do imperador Zenão","lead":"Há mil e quinhentos anos um imperador lançou os dados — e o resultado sobrevive num poema.","s":["Os romanos adoravam a tabula, um jogo de corrida com dados num tabuleiro de 24 pontas: o ancestral do gamão. Para evitar lances trapaceados, usavam até torres de dados, por dentro das quais os dados rolavam.","Por volta de 480, o imperador romano do Oriente Zenão jogava tabula. Seus três dados deram 2, 5 e 6. Ele não teve escolha senão mover como as regras mandavam, e o tabuleiro ficou com oito peças sozinhas e desprotegidas.","A partida foi registrada por Agátias, historiador e poeta do século VI que viveu algumas décadas depois de Zenão. Seu breve poema (um epigrama) dá a posição das peças: um raro registro de uma partida antiga.","No século XIX, o estudioso francês Becq de Fouquières deduziu do poema a posição e as regras: quinze peças para cada um e três dados. Todas as peças começam fora do tabuleiro, e os dois jogadores avançam no mesmo sentido.","Em relação ao gamão atual, a tabula usava três dados, começava sem peças no tabuleiro e não tinha dado de dobra. Graças ao azar de um imperador, sabemos como era a tabula."],"quiz":[["O que Zenão tirou nos dados?","2, 5 e 6","6, 6 e 6","1, 1 e 1","3, 4 e 5"],["Quem registrou a partida num poema?","Agátias","Homero","Plínio","Cícero"],["Qual é uma diferença entre a tabula e o gamão atual?","A tabula usava três dados","Trinta peças para cada um","Um tabuleiro de 12 pontas","As peças andam para trás"]],"kf":["A tabula usava 24 pontos e três dados — um ancestral do gamão","A partida do imperador Zenão, por volta de 480, sobrevive com a posição num poema","Os romanos chegaram a construir “torres de dados” contra a trapaça"],"more":[{"h":"O tabuleiro da tabula","p":["O tabuleiro da tabula, como o do gamão atual, tem 24 pontos em duas fileiras de 12. Cada jogador tinha quinze peças, todas fora no início; conforme três dados, entravam, davam a volta e saíam.","A grande diferença do gamão é que os dois jogadores andam no mesmo sentido. Uma peça sozinha podia ser batida se o rival caísse no seu ponto e tinha de entrar de novo. As oito de Zenão eram justamente peças assim."],"cap":["Um tabuleiro de tabula: 24 pontos em duas fileiras de 12; as peças dos dois andam no mesmo sentido (seta)"]},{"h":"Um aparelho contra a trapaça","p":["Os romanos eram loucos por dados. A lei proibia o jogo a dinheiro, permitido, diz-se, só na festa de inverno das Saturnais — mas as apostas nunca pararam, nem os truques de mão com os dados.","Daí a torre de dados: os dados lançados por cima batem em tabuinhas internas e saem rolando por baixo. Uma do século IV achada numa vila na Alemanha traz vazado: “Pictos vencidos, inimigo destruído: joguem tranquilos”."],"cap":["A torre de dados de Vettweiß-Froitzheim (século IV) — veja-a em 3D na sala Acervo"]},{"h":"Imperadores e dados","p":["Zenão não foi o único. Segundo o historiador Suetônio, o imperador Cláudio, no século I, adorava dados: escreveu um livro sobre essa arte e adaptou a carruagem para o tabuleiro não escorregar enquanto jogava.","Os sítios romanos também revelam muitos tabuleiros de 36 letras em palavras de seis; cada letra fazia as vezes de casa, e alguns trazem provocações como “Levanta, não sabes jogar; dá lugar a um jogador”."],"cap":["Tábulas e dados agradavam de imperadores a soldados (lance dados cúbicos na sala Acaso)"]}],"tl":[["Século I","O imperador Cláudio escreve um livro sobre os dados"],["Século IV","Uma torre de dados é usada numa vila na Alemanha"],["c. 480","A partida azarada do imperador Zenão"],["Século VI","Agátias põe a partida em versos"],["c. século X","O poema entra na Antologia Grega"],["1869","Becq de Fouquières reconstrói a posição e as regras"],["1934","R. G. Austin reexamina em detalhe a partida de Zenão"]]},"sugoroku":{"title":"O sugoroku proibido","lead":"Os soberanos proibiam, e o povo continuava jogando. A história do sugoroku de tabuleiro no Japão, da Antiguidade ao período Edo.","s":["O tesouro do Shōsōin guarda um tabuleiro de sugoroku que, segundo a tradição, era um dos favoritos do imperador Shōmu. Não é o sugoroku de papel ilustrado, mas o ban-sugoroku, jogado movendo peças brancas e pretas num tabuleiro: um parente do gamão.","O sugoroku esteve ligado às apostas desde cedo. Segundo o Nihon Shoki, a imperatriz Jitō o proibiu em 689.","O Código Yōrō, em vigor desde 757, também proibia monges e monjas de jogar sugoroku. As proibições foram repetidas muitas vezes, sinal de que não eram cumpridas.","No período Heian o jogo continuou popular e aparece no Livro de Cabeceira e na Narrativa de Genji. O Heike Monogatari conta que o imperador retirado Shirakawa citou três coisas que não conseguia controlar: as águas do rio Kamo, os dados do sugoroku e os monges guerreiros do monte Hiei.","Gravuras do período Edo ainda mostram moças jogando ban-sugoroku dentro de casa. Mas por volta da era Meiji o jogo de tabuleiro quase desapareceu, e “sugoroku” passou a significar o jogo de papel ilustrado."],"quiz":[["O ban-sugoroku, como o tabuleiro do Shōsōin, é parente de qual jogo?","Gamão","Shogi","Go","Baralho"],["Segundo o Nihon Shoki, quem proibiu o sugoroku em 689?","A imperatriz Jitō","O imperador Shōmu","O imperador Kanmu","O imperador Meiji"],["Shirakawa não controlava o rio Kamo, os monges guerreiros e… o quê?","Os dados do sugoroku","As peças de shogi","As pedras de go","Uma bola de kemari"]],"kf":["O ban-sugoroku é parente do gamão e já era jogado no Japão no século VII","Foi proibido várias vezes por causa das apostas, primeiro pela imperatriz Jitō em 689","Na era Meiji quase não se jogava mais, e “sugoroku” passou a designar o jogo ilustrado de papel"],"more":[{"h":"O tabuleiro do Shōsōin","p":["O tabuleiro do Shōsōin é de pau-rosa com finas incrustações de marfim e madeiras tingidas. Tem 24 casas, doze de cada lado, com flores na divisória central.","O Shōsōin guarda ainda muitas peças de sugoroku de vidro e pedra. O ban-sugoroku usa quinze peças brancas e quinze pretas e dois dados — quase o mesmo do gamão. Acredita-se que veio do nard persa pela China."],"cap":["O tabuleiro de sugoroku do Shōsōin, em pau-rosa marchetado — jogue nele na sala Acervo"]},{"h":"Como se joga","p":["Cada jogador põe quinze peças numa ordem fixa e anda conforme dois dados. Brancas e pretas giram em sentidos opostos; vence quem reúne primeiro todas as peças nas seis últimas casas.","Uma peça sozinha pode ser batida e voltar ao início. Uma casa com duas ou mais fica vedada ao rival, então a arte é formar bloqueios. Na sala Acervo dá para jogar assim no tabuleiro do Shōsōin."],"cap":["Um tabuleiro de ban-sugoroku (esquema): as 24 casas e brancas e pretas em sentidos opostos"]},{"h":"Proibições e modas","p":["Depois de Jitō, o sugoroku foi proibido muitas outras vezes, porque sempre havia quem perdesse tudo nas apostas. O xogunato de Kamakura também baixou leis contra as apostas no sugoroku.","Mas era também um refinamento da nobreza. Um belo tabuleiro fazia parte do enxoval da noiva, e no período Edo fizeram-se luxuosos tabuleiros laqueados. Odiado como instrumento de aposta, amado como tesouro: o ban-sugoroku teve as duas faces."],"cap":["Ban-sugoroku numa pintura do período Edo (sala Jogos pintados)"]}],"tl":[["Século VII","O ban-sugoroku chega da China"],["689","A imperatriz Jitō proíbe o sugoroku (Nihon shoki)"],["Século VIII","O tabuleiro marchetado entra no Shōsōin"],["757","O código Yōrō o veda a monges e monjas"],["Período Heian","Aparece em O Livro de Cabeceira e na História de Genji"],["Século XII","O lamento de Shirakawa sobre “os dados do sugoroku” (Heike monogatari)"],["Período Edo","Fazem-se luxuosos tabuleiros para enxovais"],["Era Meiji","O ban-sugoroku quase deixa de ser jogado"]]},"queen":{"title":"Como a dama virou a peça mais forte do xadrez","lead":"A peça mais poderosa de hoje começou como um conselheiro que só andava uma casa na diagonal.","s":["O xadrez viajou da Índia para a Pérsia e o mundo árabe. Na epopeia persa Shahnameh, o sábio Buzurgmihr resolve o enigma do xadrez enviado da Índia. Naqueles tabuleiros, a peça ao lado do rei era o fers, o conselheiro.","O fers só andava uma casa na diagonal: uma peça muito fraca. No jogo de xadrez do século XII de Nishapur, no Irã, ele é um pequeno trono, menor que o do rei.","Ao chegar à Europa, o conselheiro virou rainha; entre as peças de Lewis, do século XII, há rainhas. Mas o novo nome não mudou o movimento: ela continuou fraca.","A grande mudança veio na Espanha, no fim do século XV. Scachs d’amor (“Xadrez de amor”), poema escrito em Valência por volta de 1475, é considerado o registro mais antigo da dama moderna, que anda qualquer distância em linhas, colunas e diagonais. Depois, os livros de Lucena (1497) e Damiano (1512) espalharam a nova regra pela Europa.","Não se sabe ao certo por que a dama ficou tão forte. Uns dizem que se queriam partidas mais rápidas; outros apontam a influência de rainhas poderosas como Isabel I. De todo modo, a mudança aproximou muito o xadrez do jogo de hoje."],"quiz":[["No xadrez persa e árabe, que peça ocupava o lugar da dama?","O fers (conselheiro)","O elefante","O carro","O cavalo"],["Como andava o fers original?","Uma casa na diagonal","Qualquer distância em linha reta","Saltava duas casas","Não podia andar"],["Onde foi escrito o poema com o registro mais antigo da dama moderna?","Em Valência, século XV","Na Índia, século VI","Em Lewis, século XII","Em Londres, século XIX"]],"kf":["A dama nasceu do “fers” persa e árabe (o conselheiro), que só andava uma casa na diagonal","A dama forte moderna aparece por escrito na Espanha por volta de 1475","Livros impressos espalharam as novas regras pela Europa em poucas décadas"],"more":[{"h":"O conselheiro fraco","p":["O fers só andava uma casa na diagonal — bem diferente da dama de hoje, que cruza o tabuleiro de ponta a ponta. O xadrez de então era lento, e uma partida podia levar horas.","O elefante (o bispo atual) só saltava duas casas na diagonal. Um peão que chegava à última fileira era promovido — mas apenas a esse fraco fers."],"cap":["Até onde vão o fers (à esquerda) e a dama moderna (à direita)"]},{"h":"“Xadrez da dama” e “xadrez raivoso”","p":["Com a nova dama, na Espanha esse jogo passou a ser chamado de “xadrez da dama”, e na Itália, por sua fúria, “scacchi alla rabbiosa” (xadrez raivoso). Na mesma época, o bispo passou a deslizar qualquer distância na diagonal.","Com peças mais fortes, o jogo ficou rápido e feroz. Surgiram livros sobre armadilhas que vencem em poucos lances e sobre sequências fixas de abertura, e o xadrez virou um jogo de estudo."],"cap":["Liberale da Verona, Os jogadores de xadrez (c. 1475), pintado justo quando nascia a nova dama"]},{"h":"Por que uma dama?","p":["Não se sabe ao certo por que o conselheiro virou dama. Ver a peça ao lado do rei como sua consorte talvez parecesse natural. Em latim, “fers” virou “fercia” e depois a peça foi chamada de “regina”, rainha.","Também se discute por que ficou forte: talvez para acelerar as partidas, talvez por ser uma época de rainhas poderosas como Isabel I de Castela. A historiadora Marilyn Yalom ligou a mudança à posição da mulher na Idade Média."],"cap":["A dama das peças de Lewis (século XII), ainda com o movimento fraco"]}],"tl":[["c. século VI","Nasce na Índia o chaturanga, ancestral do xadrez"],["Séculos VII–IX","Jogado na Pérsia e no mundo árabe, com o fers ao lado do rei"],["c. século X","O xadrez chega à Europa"],["Século XII","As peças de Lewis têm damas (ainda fracas)"],["c. 1475","O poema valenciano Scachs d’amor registra o novo movimento"],["1497","O livro de xadrez de Lucena é impresso na Espanha"],["1512","Sai na Itália o livro de Damiano e as regras se espalham"]]},"senet":{"title":"Como o senet virou uma viagem ao além","lead":"Um jogo praticado no Egito por quase três mil anos passou a representar a viagem da alma após a morte.","s":["O senet é um jogo do antigo Egito em que as peças avançam num tabuleiro de três fileiras de dez casas. Em túmulos da I Dinastia, por volta de 3100 a.C., foram achados fragmentos do que podem ser tabuleiros de senet. A realeza jogava em caixas esplêndidas; o povo, em tabuleiros riscados na pedra.","O nome significa “passagem”. A partir do Novo Império (por volta de 1550 a.C.), o senet passou a ser ligado à viagem da alma do morto através do além.","O capítulo 17 do Livro dos Mortos mostra o morto jogando senet contra um adversário invisível. Na parede do túmulo de Nefertari, esposa de Ramsés II, a rainha aparece diante de um tabuleiro de senet.","O túmulo de Tutancâmon tinha pelo menos cinco caixas de jogo. Uma delas, uma grande caixa de ébano e marfim, traz o senet em cima e outro jogo de vinte casas do outro lado.","Mas nenhum texto que explique as regras por inteiro foi encontrado. No século XX, Jéquier, Bell e Kendall (1978), entre outros, reconstruíram cada um uma forma de jogar a partir de tabuleiros, imagens e fragmentos de textos. O senet do Atlas é uma dessas formas baseadas em pesquisa."],"quiz":[["O que significa o nome “senet”?","Passagem","O jogo do rei","Trinta casas","Atravessar o rio"],["No Novo Império, o senet foi ligado a quê?","À viagem da alma pelo além","A ritos para chamar a chuva","A planos de batalha","A presságios de colheita"],["Quantas caixas de jogo, no mínimo, havia no túmulo de Tutancâmon?","Cinco","Uma","Duas","Cem"]],"kf":["Um dos jogos de tabuleiro mais antigos: peças correm num tabuleiro de 3 × 10 casas","O nome significa “passar”; no Império Novo virou a viagem da alma pelo além","Nenhuma regra sobreviveu; as formas de jogar atuais são reconstruções do século XX"],"more":[{"h":"Trinta casas e as especiais","p":["O tabuleiro de senet tem três fileiras de dez, trinta casas. Acredita-se que as peças iam da esquerda para a direita na primeira fileira, da direita para a esquerda na segunda e de novo da esquerda para a direita na terceira, desenhando um S.","As cinco últimas casas costumavam ter sinais especiais. A 26 é a “casa bela”, a 27 a “água”, e na maioria das reconstruções a peça que cai na água volta. Da 28 à 30 havia números ou deuses do além."],"cap":["Um tabuleiro de senet. As peças avançam em S; as cinco últimas casas (26–30) têm sinais especiais"]},{"h":"Andar com varetas","p":["Em vez de dados lançavam-se quatro varetas, planas de um lado e redondas do outro, ou astrágalos. Muitos estudiosos acham que se andava conforme as faces planas para cima, e que nenhuma valia cinco.","Essa contagem é exatamente a das varetas do yut, da distante Coreia. Lance-as na sala Acaso do museu e veja como alguns números saem bem mais que outros."],"cap":["Varetas de lançar egípcias (lance-as na sala Acaso)"]},{"h":"As caixas de jogo de Tutancâmon","p":["O túmulo de Tutancâmon, aberto por Howard Carter em 1922, tinha pelo menos cinco caixas de jogo. A maior é de ébano e marfim, com uma gaveta para as peças e as varetas.","Caixas com tabuleiro dos dois lados eram comuns na época: senet de um lado e, do outro, o mesmo jogo de vinte casas do Jogo Real de Ur. Queria-se que o rei pudesse jogar os dois no outro mundo."],"cap":["A caixa de senet de Tutancâmon — veja em 3D e jogue na sala Acervo"]}],"tl":[["c. 3100 a.C.","Fragmentos de um tabuleiro parecido com o senet num túmulo da I dinastia"],["c. 2600 a.C.","Pinturas de túmulos do Império Antigo mostram jogadores"],["Desde c. 1550 a.C.","Império Novo: o senet se liga à viagem ao além"],["c. 1323 a.C.","Cinco caixas de jogo no túmulo de Tutancâmon"],["c. 1250 a.C.","Nefertari é pintada diante de um tabuleiro de senet"],["1922","Carter abre o túmulo de Tutancâmon"],["1978","Kendall publica uma reconstrução das regras"]]},"lewis":{"title":"As peças de xadrez que saíram da areia","lead":"Peças medievais achadas numa ilha escocesa em 1831 — e outra, da mesma oficina, que apareceu numa gaveta 188 anos depois.","s":["Em 1831, achou-se na ilha de Lewis, a noroeste da Escócia, um conjunto de peças entalhadas sobretudo em marfim de morsa: 78 peças de xadrez, 14 discos de jogos de tabuleiro e uma fivela, 93 objetos ao todo.","Não se sabe ao certo onde nem como foram encontradas. Costuma-se citar a baía de Uig, na costa oeste, mas há outras propostas. Também não se sabe quem as enterrou ali, nem por quê.","Acredita-se que foram feitas no fim do século XII na região de Trondheim, na Noruega: reis, rainhas pensativas, bispos, cavaleiros em cavalinhos atarracados e guardas mordendo a borda do escudo — provavelmente os berserkers das sagas nórdicas.","Hoje 82 peças estão no Museu Britânico e 11 no Museu Nacional da Escócia. Há muito se diz que faltam algumas peças para completar os jogos.","Em 2019, um guarda comprado por apenas 5 libras em 1964 por um antiquário de Edimburgo, e guardado pela família numa gaveta, foi reconhecido como da oficina das peças de Lewis. Foi vendido na Sotheby’s por 735 mil libras."],"quiz":[["Em que ano as peças foram achadas em Lewis?","1831","1066","1931","1700"],["Do que são feitas principalmente as peças?","Marfim de morsa","Mármore","Ouro","Vidro"],["Em que ano o guarda vendido em 2019 foi comprado por 5 libras?","1964","1831","1990","2018"]],"kf":["93 peças e discos achados na ilha de Lewis (Escócia) em 1831","Esculpidos sobretudo em marfim de morsa, na Noruega, no fim do século XII","Hoje divididos entre o Museu Britânico e os Museus Nacionais da Escócia"],"more":[{"h":"As 78 peças de xadrez","p":["As 78 peças são 8 reis, 8 damas, 16 bispos, 15 cavaleiros, 12 guardiões e 19 peões — restos de pelo menos quatro jogos.","Os bispos usam mitra. A troca do “elefante” pelo bispo aconteceu na Europa, e as peças de Lewis estão entre os primeiros exemplos. Alguns guardiões mordem o escudo; acredita-se que sejam berserkers, guerreiros que lutavam em fúria."],"cap":["As peças de Lewis (veja-as em 3D na sala Acervo)","As 78 peças por tipo"]},{"h":"Marfim de morsa e mares do norte","p":["A maioria é de marfim de morsa, algumas de dente de baleia. O marfim de morsa era um tesouro dos mares do norte, trazido da Groenlândia e do norte da Noruega.","Lewis pertencia então às ilhas do rei da Noruega; passou à Escócia pelo Tratado de Perth em 1266. Perto da catedral de Trondheim acharam-se fragmentos esculpidos da mesma maneira — uma pista de onde foram feitas."],"cap":[]},{"h":"A lenda da descoberta e a fama de hoje","p":["Há muitas versões: uma vaca que as desenterrou da areia, ou um morador, Malcolm MacLeod. O descobridor logo as vendeu e, via Edimburgo, o Museu Britânico comprou a maior parte.","Com seus rostos emburrados e cômicos, são muito populares e réplicas vendem-se no mundo todo. O xadrez de bruxo do filme Harry Potter e a Pedra Filosofal (2001) usou peças baseadas nas de Lewis."],"cap":[]}],"tl":[["Fim do século XII","As peças são feitas na Noruega (perto de Trondheim)"],["1266","O Tratado de Perth entrega as ilhas, Lewis entre elas, à Escócia"],["1831","As 93 peças são achadas juntas em Lewis"],["1831–32","O Museu Britânico compra 82"],["1888","O museu nacional escocês adquire 11"],["2001","Aparecem no xadrez de bruxo de Harry Potter"],["2019","Um guardião comprado por £5 é vendido por £735.000"]]},"tafl":{"title":"A fuga do rei e uma tradução errada","lead":"As regras do jogo de tabuleiro dos vikings foram deduzidas de um diário de viagem pela Lapônia do século XVIII.","s":["No norte da Europa da era viking, jogavam-se jogos de tabuleiro chamados tafl. Um rei no centro e seus poucos defensores enfrentam um exército maior que os cerca: um jogo de dois lados desiguais.","Um tabuleiro de madeira do século X achado em Ballinderry (Irlanda) em 1932 tem 7×7 furos, com o centro e os quatro cantos marcados — provavelmente o lugar do rei e seus refúgios.","Mas quase nenhuma descrição medieval das regras sobreviveu. Uma pista essencial é o diário do naturalista Lineu, então com 25 anos, de sua viagem pela Lapônia (norte da Suécia) em 1732. Ali ele anotou como os sámi jogavam um jogo chamado tablut.","O diário foi publicado em tradução inglesa em 1811, mas a tradução tinha erros. A reconstrução de Murray (1913), baseada nela, tornou-se por muitos anos a regra padrão do tafl.","Depois, jogadores e pesquisadores corrigiram o erro, e hoje se jogam muitas versões das regras. O tafl do Atlas é uma delas."],"quiz":[["Que jogo Lineu anotou na Lapônia?","O tablut","O senet","O mancala","O xadrez"],["Que peça os defensores tentam levar a um canto?","O rei","A rainha","Uma bandeira","Um navio"],["Quando foi publicada a tradução inglesa com o erro?","1811","1732","1932","1066"]],"kf":["Um rei e poucos defensores no centro, cercados por um exército maior: um jogo de dois lados desiguais","Jogado no norte da Europa na era viking, em tabuleiros de 7×7 até 19×19","As regras chegaram até nós pelo diário de viagem de Lineu (1732) — e por sua tradução inglesa com erros"],"more":[{"h":"O tabuleiro de Ballinderry","p":["Encontrado numa habitação lacustre (crannog) no centro da Irlanda, o tabuleiro de Ballinderry é de teixo. Seus 49 furos, numa grade de 7×7, provavelmente prendiam peças com um pino na base.","Do contorno sai uma alça esculpida em forma de cabeça humana: era um tabuleiro para levar consigo. Fontes irlandesas citam um tafl de 7×7, o brandubh («corvo negro»), que pode ter sido jogado nele."],"cap":["O tabuleiro de Ballinderry (7×7) com a posição inicial do brandubh irlandês. Os anéis dourados marcam o centro e os quatro cantos"]},{"h":"O tablut de Lineu","p":["O tablut registrado por Lineu usa um tabuleiro de 9×9. O rei fica no trono central; seus 8 «suecos» enfrentam 16 «moscovitas».","Todas as peças andam em linha reta quantas casas quiserem, como uma torre, e são capturadas quando ficam entre duas inimigas. Os defensores vencem se o rei chegar à borda; os atacantes, se o cercarem pelos quatro lados. Lineu escreveu misturando latim e sueco, e vários pontos mudaram na tradução inglesa."],"cap":["O tablut como Lineu o registrou (9×9): o rei no trono central, 8 defensores e 16 atacantes. Os defensores vencem se o rei chegar a uma casa verde da borda"]},{"h":"Tabuleiros que crescem, um jogo que se apaga","p":["Além do 7×7, havia tabuleiros de 9×9, o galês de 11×11 e até de 19×19. O maior, o Alea Evangelii, aparece desenhado num manuscrito do século XII que diz ter vindo da corte do rei Æthelstan da Inglaterra, no século X.","Quando o xadrez se espalhou pelo norte da Europa nos séculos XII e XIII, o tafl foi caindo em desuso. Só na distante Lapônia o tablut sobreviveu — e Lineu o anotou por acaso. Hoje há torneios internacionais em tabuleiros de 11×11, e o jogo conquista novos jogadores."],"cap":["O tesouro de Lewis (século XII): junto das peças de xadrez havia 14 discos para um jogo de tabuleiro"]}],"tl":[["séc. X","O tabuleiro de Ballinderry é feito na Irlanda"],["924–939","Diz-se que se jogava Alea Evangelii na corte de Æthelstan"],["séc. XII","O Alea Evangelii é desenhado num manuscrito"],["sécs. XII–XIII","O xadrez se espalha pelo norte da Europa e o tafl desaparece"],["1732","Lineu registra o tablut na Lapônia"],["1811","Sai Lachesis Lapponica, a tradução inglesa do diário"],["1913","Murray reconstrói o tafl em A History of Chess"],["1932","O tabuleiro de Ballinderry é encontrado"]]},"goose":{"title":"O jogo do ganso, um presente para um rei","lead":"Uma corrida de dados por uma espiral de 63 casas foi dada de presente a um rei — e depois jogada em toda a Europa.","s":["O jogo do ganso é uma corrida: lançam-se os dados e avança-se por uma espiral de 63 casas até a meta, no centro. Quem cai num ganso avança de novo o mesmo número. O poço, a prisão e a morte seguram você ou o mandam de volta ao início.","Acredita-se que nasceu na Itália do século XVI. Conta-se que Francisco I de Médici, grão-duque da Toscana, deu o jogo de presente ao rei Filipe II da Espanha entre 1574 e 1587.","Na Inglaterra, o impressor londrino John Wolfe registrou em 1597 “o novo e muito agradável jogo do ganso”. Nos séculos XVII e XVIII ele foi enormemente popular em toda a Europa.","Impresso em papel, espalhou-se em versões incontáveis com novos desenhos: tabuleiros para aprender geografia, de histórias e fábulas, e até de propaganda. Acredita-se que serviu de modelo a muitos jogos de corrida posteriores.","Um tabuleiro de dupla face do Metropolitan Museum of Art traz o jogo do ganso de um lado e o xadrez do outro. Provavelmente feito no fim do século XVI por artesãos de Guzerate, na Índia, pode ser o tabuleiro de ganso mais antigo que sobreviveu."],"quiz":[["Quantas casas tem o jogo do ganso?","63","64","100","30"],["Quem teria dado o jogo ao rei da Espanha?","Francisco I de Médici","Napoleão","Elizabeth I","Luís XIV"],["O que acontece ao cair num ganso?","Avança de novo o mesmo número","Volta ao início","Perde a vez","Troca de lugar com um rival"]],"kf":["Uma corrida por uma espiral de 63 casas até a meta no centro, ao sabor dos dados","Nascido na Itália do século XVI e, segundo se conta, enviado pelos Médici ao rei da Espanha","Espalhou-se em folhas impressas, em incontáveis versões com novas imagens e temas"],"more":[{"h":"Uma espiral de 63 casas","p":["Na versão mais conhecida há, além dos gansos, algumas casas especiais. A ponte do 6 leva ao 12; na estalagem do 19 perde-se uma vez; no poço do 31 e na prisão do 52 fica-se preso até outro jogador chegar para libertar.","O labirinto do 42 manda de volta ao 30, e a morte do 58 manda para o início. É preciso cair exatamente no 63: o que sobra, volta. O último passo é o mais difícil."],"cap":["As 63 casas em espiral de fora para dentro. Verde: gansos; azul: a ponte; amarelo: esperas (estalagem, poço, prisão); vermelho: recuos (labirinto, morte); dourado: a meta"]},{"h":"O enigma do nove","p":["Os gansos estão no 5, 9, 14, 18…, alternando intervalos de 4 e 5. Todo múltiplo de 9 tem um ganso, então um 9 que cai no 9 levaria ao 18, ao 27… e direto ao 63.","Por isso as versões com dois dados têm uma regra especial: se o primeiro lance for 6 e 3, vai-se ao 26; se for 5 e 4, ao 53. O 63 é 7×9 e já foi associado aos 63 anos, tidos então como a idade mais perigosa da vida."],"cap":["Os gansos ficam a cada 4 e 5 casas, então sempre há um ganso nos múltiplos de 9. Um 9 no primeiro lance pularia de ganso em ganso até o 63"]},{"h":"A imprensa o espalha","p":["Os tabuleiros eram impressos em chapas de cobre e blocos de madeira e ficaram baratos. Na França era o jeu de l’oie; na Espanha, o juego de la oca, onde um versinho sobre ir «de ganso em ganso» ainda é dito popular.","Versões com novos desenhos não pararam de surgir: tabuleiros para aprender geografia e história, sobre a Revolução Francesa ou Napoleão, e até propaganda de produtos. Sobre a mesma pista de 63 casas, cada época desenhou suas próprias preocupações."],"cap":[]}],"tl":[["séc. XVI","Teria nascido na Itália"],["1574–87","Francisco I de Médici o teria enviado a Filipe II da Espanha"],["fim do séc. XVI","Em Gujarate (Índia), faz-se um tabuleiro de dois lados: ganso de um lado, xadrez do outro"],["1597","John Wolfe o registra para impressão em Londres"],["sécs. XVII–XVIII","Febre em toda a Europa, com cada vez mais versões temáticas"],["década de 1790","Surgem tabuleiros sobre a Revolução Francesa"],["séc. XIX","Impresso em massa em muitos países como jogo infantil"]]},"shogi":{"title":"Quando nasceram as peças “na mão” do shogi?","lead":"De toda a família do xadrez, só o shogi deixa recolocar no jogo, como suas, as peças capturadas. Quando — e por quê — essa regra surgiu?","s":["O ancestral indiano do xadrez se espalhou para leste e oeste; no Japão, virou shogi. As peças de shogi mais antigas do Japão são 16 achadas no início dos anos 1990 no antigo recinto do Kōfuku-ji, em Nara. Junto delas apareceu uma etiqueta datada de 1058 (Tenki 6), por isso se acredita que as peças sejam da mesma época.","Textos da época também o mencionam. O Shin Sarugaku-ki, de meados do século XI, cita o jogo, e o Nichūreki, que reúne registros do fim do período Heian, descreve um “shogi Heian” com reis, generais de ouro e de prata, cavalos, lanceiros e peões.","Nos períodos Kamakura e Muromachi surgiram muitas formas maiores, com mais peças. O “shogi pequeno”, base do jogo atual, acrescentou a torre e o bispo… e uma peça que não existe mais: o elefante bêbado.","Acredita-se que a regra de recolocar peças surgiu por volta do século XVI. A tradição diz que o imperador Go-Nara mandou retirar o elefante bêbado do shogi pequeno, e as peças na mão teriam começado nessa época.","Não se sabe ao certo por quê. Uma explicação: as peças dos dois lados têm a mesma cor e se distinguem só pela direção, então uma peça capturada é fácil de reutilizar. Por isso o tabuleiro não se esvazia e os empates são raros."],"quiz":[["Que data tinha a etiqueta achada com as peças do Kōfuku-ji?","1058 (Tenki 6)","701 (Taihō 1)","1582 (Tenshō 10)","1868 (Meiji 1)"],["Quando se acredita que surgiu a regra das peças na mão?","Por volta do século XVI","Por volta do século VIII","Por volta do século XIX","No século XX"],["Que motivo se dá para ser fácil reutilizar as peças?","As peças dos dois lados têm a mesma cor, distinguidas pela direção","As peças eram de ouro","O tabuleiro tinha poucas casas","As peças eram escolhidas nos dados"]],"kf":["Um parente do xadrez nascido na Índia que cresceu no Japão, jogado num tabuleiro de 9×9","As peças mais antigas vêm do antigo recinto do Kōfuku-ji, achadas com uma etiqueta datada de 1058","As «peças na mão» — usar como suas as peças capturadas — teriam surgido por volta do século XVI"],"more":[{"h":"Uma só cor, distinguidas pela direção","p":["As peças de xadrez são pintadas de branco e preto, mas as de shogi têm todas a cor da madeira: sabe-se de quem são pela direção da ponta da peça de cinco lados. É essa forma que permite virar uma peça capturada e soltá-la de novo no tabuleiro.","Cada peça traz o nome escrito e, ao entrar no campo inimigo, pode virar e «promover». O peão vira o と do verso e passa a mover-se como um general de ouro. Peças planas com letras em vez de figuras esculpidas: é algo que o shogi compartilha com seus primos do Leste Asiático, o xiangqi chinês e o janggi coreano."],"cap":["As peças de shogi têm a mesma cor para os dois lados e se distinguem pela direção da ponta. À direita, um peão virado, «promovido» (tokin)"]},{"h":"A era dos shogi gigantes","p":["Dos períodos Kamakura e Muromachi até o período Edo, criaram-se shogi cada vez maiores, com cada vez mais tipos de peças. O chū shogi de 12×12 foi muito jogado durante todo o período Edo e ainda tem fãs.","Os registros vão além: o dai shogi de 15×15, o tai shogi de 25×25 e o taikyoku shogi, com 804 peças num tabuleiro de 36×36. Mas o jogo do dia a dia era o shō shogi de 9×9, que ganhou as peças na mão e virou o shogi de hoje."],"cap":["Tamanhos de tabuleiro comparados a partir de um canto: 9×9 é o shogi atual (40 peças), 12×12 o chū shogi (92), 15×15 o dai shogi (130), 25×25 o tai shogi (354) e 36×36 o taikyoku shogi (804)"]},{"h":"O shogi em Edo","p":["No período Edo surgiram casas de shogi pagas pelo xogunato; Ōhashi Sōkei é tido como o primeiro mestre. Todo ano os melhores jogavam diante do xógum nas «partidas do castelo», depois fixadas em 17 de novembro — origem do atual Dia do Shogi.","O shogi também era diversão do povo: a gravura de Harunobu mostra um jovem casal jogando junto a um mosquiteiro. Surgiram ainda coletâneas de problemas de tsume-shogi dignas de obras de arte, como o Shōgi Zukō de Itō Kanju (1755)."],"cap":["Xilogravura colorida de Suzuki Harunobu (c. 1767–69): uma jovem e um jovem jogam shogi junto a um mosquiteiro"]}],"tl":[["1058","Peças do antigo recinto do Kōfuku-ji (achadas com uma etiqueta do ano Tengi 6)"],["meados do séc. XI","O Shinsarugakuki cita o shogi"],["início de Kamakura","O Nichūreki lista as peças do shogi Heian"],["c. séc. XVI","Teriam surgido as peças na mão"],["1612","Ōhashi Sōkei e outros recebem, diz-se, um estipêndio do xogunato"],["1716","As partidas do castelo são fixadas em 17 de novembro"],["1755","Shōgi Zukō, de Itō Kanju"],["1975","17 de novembro vira o Dia do Shogi"]]},"pachisi":{"title":"Como o pachisi virou ludo","lead":"Um jogo de tabuleiro em cruz das cortes indianas mudou de nome e chegou às salas de brinquedo do mundo inteiro.","s":["A Índia tem o chaupar e o pachisi: quatro jogadores movem peças em volta de um tabuleiro em forma de cruz. O chaupar usa dados compridos (pasa); o pachisi, búzios lançados. O nome pachisi quer dizer “vinte e cinco”, o maior resultado dos búzios.","Até os deuses jogavam. Uma pintura do fim do século XVII mostra o deus Shiva e sua esposa Parvati diante de um tabuleiro de chaupar, sobre uma pele de tigre.","Em Fatehpur Sikri, a cidade do imperador mogol Akbar (século XVI), um pátio ainda tem no chão um enorme tabuleiro em cruz. Conta-se que Akbar jogava usando como peças pessoas vestidas de cores.","No século XIX o jogo atravessou os mares. Nos Estados Unidos foi vendido como Parcheesi, marca registrada em 1874. Na Grã-Bretanha foi vendido nos anos 1890 como Ludo — em latim, “eu jogo” — e virou um clássico de família.","O ludo é mais simples: um só dado, e um 6 para tirar a peça. Há parentes com outros nomes no mundo todo, como o parchís na Espanha e o Mensch ärgere Dich nicht (“Não se irrite”) na Alemanha."],"quiz":[["O que significa o nome “pachisi”?","Vinte e cinco","O caminho do rei","Cruz","Búzio"],["Que cidade de Akbar guarda um pátio com um tabuleiro enorme?","Fatehpur Sikri","O Qutb Minar de Délhi","O Taj Mahal","Ellora"],["O que significa “ludo” em latim?","Eu jogo","Eu venço","Eu corro","Eu lanço"]],"kf":["Um jogo de corrida num tabuleiro indiano em cruz: quatro jogadores, em duas equipes, levam suas peças para dar a volta","O nome significa «25», o maior lance das conchas de búzio","No século XIX cruzou os mares e se espalhou pelo mundo como Parcheesi, ludo e outros"],"more":[{"h":"A cruz e o caminho","p":["O tabuleiro do pachisi é uma cruz com quatro braços saindo do charkoni central. Cada braço tem 3 × 8 casas, 96 no total. Os tabuleiros costumavam ser bordados em tecido, para serem enrolados e guardados.","As peças saem do centro, descem pela coluna do meio do próprio braço, dão uma volta no tabuleiro no sentido anti-horário e sobem de novo pela coluna do meio até o centro. Os jogadores sentados frente a frente são parceiros, e uma equipe vence quando os dois levam para casa suas quatro peças."],"cap":["Um tabuleiro em cruz (cada braço com 3 × 8 casas). A linha azul é o caminho de um jogador: desce pelo meio do próprio braço, dá a volta inteira no sentido anti-horário e sobe de novo pelo meio até o centro"]},{"h":"Contando os búzios","p":["No pachisi lançam-se seis conchas de búzio, e o número que cai com a abertura para cima decide o lance. De dois a seis, anda-se esse número; mas com um, andam-se 10, e com nenhum, 25.","Com chance de 1 em 64, o 25 é o lance mais raro e mais alto — e deu nome ao jogo. Um 6, 10 ou 25 dá direito a outro lance. Já o chaupar usa três dados compridos de bastão marcados com 1, 2, 5 e 6."],"cap":["De seis búzios, quantos caem com a abertura para cima (fileira de cima) e quanto se anda (fileira de baixo). A altura das barras mostra a frequência se cada concha cair de um lado ou de outro por igual"]},{"h":"Novos nomes, novos países","p":["Por meio dos britânicos na Índia, o jogo chegou à Europa e à América no século XIX. Nos EUA virou a marca Parcheesi; na Grã-Bretanha, o ludo foi patenteado em 1896, com regras mais simples e um único dado cúbico no lugar dos búzios.","A Alemanha ganhou em 1914 o Mensch ärgere dich nicht («Não se irrite»), e na Espanha joga-se parchís. Nomes e detalhes mudam de país para país, mas a estrutura é a mesma: dar a volta na cruz e voltar para casa."],"cap":[]}],"tl":[["séc. XVI","Um pátio com uma cruz gigante é traçado em Fatehpur Sikri, a cidade de Akbar"],["sécs. XVII–XVIII","Miniaturas indianas mostram com frequência pessoas em volta do chaupar"],["1694–95","Devidasa pinta Shiva e Parvati jogando chaupar"],["1874","Parcheesi vira marca registrada nos EUA"],["1896","O ludo é patenteado na Grã-Bretanha"],["1914","O Mensch ärgere dich nicht chega às lojas na Alemanha"]]},"go":{"title":"O que conta um tabuleiro de go de 1.300 anos","lead":"O tabuleiro de go do Shōsōin tem 19 linhas como os de hoje — e 17 marcas de flor, ao contrário dos de hoje.","s":["O go nasceu na China antiga. A lenda diz que o rei sábio Yao o criou para ensinar o filho. O livro de Mêncio, de antes da nossa era, cita um mestre do jogo, Yi Qiu.","Acredita-se que o tamanho do tabuleiro mudou com o tempo: em épocas antigas também se usaram tabuleiros de 17 linhas, e depois se espalhou o de 19 linhas de hoje.","Não se sabe quando o go chegou ao Japão, mas no período Nara já se jogava. As regras para monges e monjas proibiam a música e os jogos de azar, mas permitiam o go e o koto — um tratamento bem diferente do sugoroku.","O tabuleiro de marchetaria do Shōsōin foi transmitido como um tesouro ligado ao imperador Shōmu. Tem 19 linhas como hoje, mas 17 marcas de flor onde o tabuleiro atual tem 9 pontos-estrela. Suas duas gavetas são ligadas: puxar uma faz a outra sair. O Shōsōin guarda também pedras de go de marfim tingido de vermelho e azul-escuro, gravadas com pássaros.","No período Heian, a Narrativa de Genji mostra partidas de go. No período Edo, casas como a Hon’inbō serviram o xogunato, e o go virou uma arte em que jogadores profissionais mediam sua habilidade."],"quiz":[["Quantas linhas tem o tabuleiro de go do Shōsōin?","19","17","13","9"],["O que as regras permitiam a monges e monjas?","O go e o koto","O sugoroku","Jogos de azar","O kemari"],["Quantas marcas de flor o tabuleiro do Shōsōin tem no lugar dos pontos-estrela?","17","9","4","25"]],"kf":["Pedras pretas e brancas nos pontos onde as linhas se cruzam, disputando o maior território — um jogo nascido na China antiga","Depois de uma época de tabuleiros de 17 linhas vieram as 19; o Shōsōin guarda um tabuleiro de 19 linhas do século VIII","No Japão de Edo, casas de go serviam ao xogunato; no século XXI uma IA venceu o melhor jogador do mundo"],"more":[{"h":"Cercar para capturar, cercar para vencer","p":["No go, pretas e brancas colocam pedras alternadamente nos pontos onde as linhas se cruzam. Uma vez colocada, a pedra não se move. Quando todos os pontos vazios ao lado de uma pedra (ou grupo) são ocupados pelo adversário, ela é capturada e retirada do tabuleiro.","No fim, vence quem somar mais território cercado e pedras capturadas. As regras são poucas, mas o tabuleiro é amplo: calcula-se que num tabuleiro de 19 linhas caibam cerca de 10 elevado a 170 posições possíveis."],"cap":["Como se captura. Esquerda: a pedra preta tem quatro pontos vazios ao lado (vermelho). Meio: as brancas a cercam por três lados, resta um. Direita: o último é fechado e a pedra preta é capturada"]},{"h":"De 17 linhas para 19","p":["Numa tumba dos Han Orientais em Wangdu (Hebei, China) achou-se um tabuleiro de go de pedra com 17 linhas. O Clássico do go de Dunhuang, de por volta do século VI, descreve 361 pontos — um tabuleiro de 19 linhas. Parece que entre um e outro o tabuleiro cresceu.","O tabuleiro do Shōsōin tem 19 linhas, mas em vez dos nove pontos-estrela atuais traz marcas de flor em 17 lugares. Passar de 289 para 361 pontos tornou o jogo muito mais profundo."],"cap":["Os tabuleiros de 17 e 19 linhas comparados pelo número de pontos. Os nove pontos pretos do tabuleiro atual são os «pontos-estrela»"]},{"h":"O go dos imortais, o go dos mestres","p":["Um conto chinês fala de um lenhador que parou na montanha para ver imortais jogando go — e descobriu que haviam passado tantos anos que o cabo do seu machado apodrecera. O go como passatempo de imortais era tema querido de pratos e pinturas.","No Japão de Edo, casas de go como a Hon’inbō recebiam estipêndio do xogunato, e o go foi lapidado como arte. A partida de despedida de Hon’inbō Shūsai, em 1938, virou o romance de Kawabata Yasunari O mestre de go. Em 2016, a IA AlphaGo venceu o melhor jogador do mundo, Lee Sedol, por quatro a um, espantando o mundo."],"cap":["Prato de laca entalhada com imortais jogando go (dinastia Ming, período Xuande, 1425–36)"]}],"tl":[["c. séc. IV a.C.","Mêncio cita o mestre de go Yi Qiu"],["Han Orientais","Um tabuleiro de pedra de 17 linhas é posto numa tumba em Wangdu"],["c. séc. VI","O Clássico do go de Dunhuang descreve 19 linhas e 361 pontos"],["séc. VIII","O tabuleiro de sândalo marchetado do Shōsōin"],["1612","Hon’inbō Sansa e outros recebem, diz-se, estipêndio do xogunato"],["1938","Partida de despedida de Hon’inbō Shūsai, depois o romance de Kawabata"],["2016","AlphaGo vence Lee Sedol por quatro a um"]]},"draughts":{"title":"Como nasceram as damas","lead":"Um jogo de tabuleiro árabe, o tabuleiro de xadrez e a dama do xadrez: acredita-se que as damas nasceram do encontro dos três.","s":["Considera-se antepassado das damas o alquerque, jogado numa grade de 5×5 pontos ligados por linhas. Em árabe chamava-se qirq e aparece no Livro das Canções do século X. Os mouros o levaram à Espanha, e suas regras estão no Livro dos Jogos que Afonso X de Castela mandou fazer no século XIII.","Por volta do século XII, provavelmente no sul da França, passou-se a mover as peças do alquerque num tabuleiro de xadrez. Assim nasceu o fierges. As peças levaram o nome da dama do xadrez da época, a fers.","A promoção — a peça que chega ao fundo fica mais forte — já aparece numa crônica de meados do século XIII. Talvez tenha vindo do peão do xadrez que vira dama.","A grande mudança veio na França por volta de 1535: acrescentou-se a captura obrigatória — se pode comer, deve comer — e o jogo passou a se chamar jeu forcé, “jogo forçado”. As damas inglesas e as checkers americanas descendem dele.","O jogo antigo sem captura obrigatória sobreviveu como “jogo gentil das damas” e depois levou às damas internacionais de 10×10. De um mesmo ancestral brotaram muitos “jogos de damas”, de rainhas."],"quiz":[["Que jogo é considerado o ancestral das damas?","O alquerque","O senet","O liubo","O mancala"],["Quando e onde foi acrescentada a captura obrigatória?","Na França, por volta de 1535","Em Bagdá, no século X","Nos Estados Unidos, em 1900","No Japão, no século VIII"],["As peças do fierges levavam o nome de quê?","Da dama do xadrez (fers)","Do rei do xadrez","Dos dados","Do cavalo"]],"kf":["Nasceu quando as peças do jogo árabe alquerque passaram para um tabuleiro de xadrez","As peças andam na diagonal e capturam saltando; ao chegar à última fileira, viram dama","A captura obrigatória surgiu por volta de 1535, e em 2007 o jogo (8 × 8) foi resolvido"],"more":[{"h":"Dos pontos e linhas ao tabuleiro de xadrez","p":["O tabuleiro de alquerque são 25 pontos numa grade de 5 × 5 ligados por linhas. Cada lado põe 12 peças, e o jogo começa pelo único ponto vazio, no centro. As peças andam pelas linhas e capturam saltando sobre uma inimiga vizinha.","Quando as peças passaram para o tabuleiro de xadrez, passou-se a usar só as casas de uma cor. Um tabuleiro de 8 × 8 tem 32 casas escuras; preenchendo as três primeiras fileiras de cada lado, dá 12 peças para cada um — o mesmo que no alquerque."],"cap":["O tabuleiro de alquerque e sua posição inicial: 5 × 5 pontos ligados por linhas retas e diagonais, 12 peças de cada lado, só o centro vazio"]},{"h":"Saltar para capturar, virar dama","p":["As peças avançam uma casa na diagonal e capturam saltando sobre uma inimiga vizinha se a casa seguinte estiver livre. Se depois houver outra captura, continuam saltando. Nas damas de hoje, se é possível capturar, é obrigatório.","A peça que chega à última fileira vira dama — põe-se outra peça por cima — e pode também andar para trás. No jogo internacional de 10 × 10, a dama percorre qualquer distância na diagonal, o que transforma os finais."],"cap":["Captura e promoção. A peça vermelha salta duas brancas seguidas (×) e depois chega à última fileira e vira dama, com duas peças empilhadas"]},{"h":"Um jogo resolvido e uma família que se espalha","p":["No Canadá, Jonathan Schaeffer e sua equipe criaram o programa Chinook. Em 1992 ele enfrentou Marion Tinsley, que em mais de 40 anos quase não perdera partidas, e Tinsley venceu. A equipe continuou calculando e em 2007 provou que, com jogo perfeito dos dois lados, o jogo (de 8 × 8) termina empatado.","Enquanto isso, a família do mesmo ancestral segue viva no mundo todo: damas internacionais de 10 × 10, as shashki russas, a dama turca de movimentos ortogonais, as damas canadenses de 12 × 12… com torneios em cada país."],"cap":[]}],"tl":[["séc. X","O Livro das Canções cita o qirq (alquerque)"],["c. séc. XII","Nasce o fierges, provavelmente no sul da França"],["1283","O Livro dos Jogos de Afonso X descreve o alquerque"],["c. 1535","A captura obrigatória surge na França"],["1547","Torquemada publica na Espanha o primeiro livro sobre damas"],["séc. XVIII","O tabuleiro de 10 × 10 se espalha na França e nos Países Baixos"],["1992","Tinsley vence o programa Chinook"],["2007","Prova-se que o jogo (8 × 8) é empate com jogo perfeito"]]},"reversi":{"title":"Reversi e Othello: quem os inventou?","lead":"Um jogo de cercar e virar discos pretos e brancos — e dois homens na Inglaterra do século XIX que o disputaram.","s":["Na Londres dos anos 1880, dois ingleses, Lewis Waterman e John W. Mollett, diziam cada um ser o inventor do jogo e chamavam o outro de impostor.","O jogo de Mollett, Annexation, usava um tabuleiro em forma de cruz. O Reversi de Waterman usava um tabuleiro comum de 8×8, e é a sua forma que chegou até nós. A briga pelo nome chegou até os tribunais.","O reversi se espalhou pela Europa; em 1893 a firma alemã Ravensburger o lançou como um de seus primeiros produtos. No Japão foi descrito em livros da era Meiji e também chamado de genpei-go.","A moda não durou. Em 1971, Goro Hasegawa lançou o “Othello”, fixando a abertura com os quatro primeiros discos cruzados no centro, e virou febre no Japão.","Diz-se que o nome vem da peça de Shakespeare: o general negro Otelo e sua esposa branca Desdêmona ecoam os discos pretos e brancos. As regras dos torneios de hoje são as do Othello."],"quiz":[["Quando e onde viviam os dois homens que disputaram o reversi?","Inglaterra, século XIX","França, século XVIII","Japão, século XX","Itália, século XVI"],["Que forma tinha o tabuleiro do Annexation de Mollett?","De cruz","Redonda","Triangular","Quadrada de 8×8"],["Quem lançou o Othello em 1971?","Goro Hasegawa","Hon’inbō Shūsaku","Lewis Waterman","Ravensburger"]],"kf":["Prenda as peças do adversário entre as suas para virá-las; no fim, vence quem tiver mais","Na Londres da década de 1880, dois ingleses disputaram sua invenção","Virou febre no Japão nos anos 1970 como Othello e, em 2023, mostrou-se empate com jogo perfeito"],"more":[{"h":"Cercar e virar","p":["Só se pode pôr uma peça onde ela prenda uma linha de peças adversárias entre ela e outra sua. As linhas vão em oito direções — horizontal, vertical e diagonal — e um lance pode prender várias ao mesmo tempo. Todas as peças presas viram para a sua cor.","Sem lance possível, passa-se a vez; o jogo termina quando nenhum dos dois pode jogar. As peças dos cantos nunca podem ser presas, então tomar um canto é uma grande vantagem. Os bons jogadores se importam menos com quantas peças têm agora do que em limitar onde o adversário pode jogar."],"cap":["Como as peças viram. Uma preta posta na casa do círculo vermelho prende brancas em três direções — horizontal, vertical e diagonal — e as sete de borda dourada viram pretas"]},{"h":"As quatro primeiras peças","p":["No reversi antigo, os dois jogadores punham por turnos as quatro primeiras peças nas quatro casas centrais, então a abertura podia ficar lado a lado ou cruzada.","O Othello fixou o início cruzado. Desde o primeiro lance as duas cores são fáceis de prender, e a luta começa logo. Os campeonatos mundiais de hoje partem dessa posição."],"cap":["As quatro primeiras peças. Esquerda: um começo possível do reversi antigo, com as mesmas cores lado a lado. Direita: o início cruzado fixado pelo Othello"]},{"h":"Humanos e computadores","p":["O Othello foi do Japão para o mundo, e o primeiro Campeonato Mundial foi em Tóquio, em 1977. As regras são simples, então decide a profundidade do cálculo: os melhores enxergam dezenas de lances à frente.","Em 1997 o programa Logistello jogou seis partidas contra o campeão mundial Takeshi Murakami e venceu todas. Em 2023, cálculos mostraram que o Othello 8 × 8 termina empatado se os dois jogarem perfeitamente."],"cap":[]}],"tl":[["década de 1880","Waterman e Mollett disputam a invenção em Londres"],["1893","A Ravensburger lança o Reversi na Alemanha"],["era Meiji","Livros japoneses o apresentam como genpei-go"],["1973","Os jogos de Othello chegam às lojas no Japão"],["1977","Primeiro Campeonato Mundial de Othello, em Tóquio"],["1997","Logistello vence o campeão Takeshi Murakami por 6–0"],["2023","Mostra-se que o Othello 8 × 8 é empate com jogo perfeito"]]},"mancala":{"title":"Onde nasceu o mancala?","lead":"Um jogo de semear pedras de cova em cova, jogado na África e na Ásia com centenas de nomes.","s":["Mancala é o nome de uma família de jogos em que se pegam pedras ou sementes de uma cova e se semeiam uma a uma nas seguintes. Diz-se que a palavra vem do árabe naqala, “mover”.","Nomes e regras mudam de lugar para lugar — oware na África Ocidental, bao na África Oriental, mangala na Turquia, congkak no Sudeste Asiático e centenas de outros —, com duas fileiras ou quatro e qualquer número de covas.","Costuma-se dizer que é antiquíssimo, mas as provas firmes são mais recentes do que se pensa. Os tabuleiros mais antigos com data segura são, por enquanto, tabuleiros de cerâmica e pedra de cerca dos séculos VI–VII achados em sítios do antigo reino de Axum, em Matara e Yeha (Eritreia e Etiópia).","Há exemplos mais antigos propostos, mas não se sabe se aquelas fileiras de furos eram mesmo de mancala, e os estudiosos discordam. Uma hipótese forte é que o jogo se espalhou de Axum para a Arábia e o interior da África.","Descrições completas de como se jogava só aparecem por volta do século XVII. No Atlas, você pode jogar mancala com oito regras, entre elas o oware e a mangala."],"quiz":[["O que significa a palavra árabe de onde vem “mancala”?","Mover","Semente","Cova","Rei"],["Onde foram achados os tabuleiros de mancala mais antigos com data segura?","Em sítios do antigo reino de Axum (Etiópia e Eritreia)","No Coliseu de Roma","Na Grande Muralha da China","Em Stonehenge"],["Que mancala se joga na África Ocidental?","O oware","O liubo","O tafl","O pachisi"]],"kf":["Uma família de jogos de «semeadura»: tiram-se as sementes de uma cova e deixam-se uma a uma nas seguintes","Os tabuleiros mais antigos bem datados vêm do antigo reino de Axum, por volta dos séculos VI–VII","Duas fileiras ou quatro, com ou sem depósitos: tabuleiro e regras mudam de região para região"],"more":[{"h":"Semear","p":["No mancala escolhe-se uma cova do próprio lado, tiram-se todas as sementes e deixa-se uma a uma nas covas seguintes. Esse gesto, como lançar sementes no campo, chama-se semeadura.","O oware, da África Ocidental, começa com 48 sementes, quatro em cada uma de 12 covas. Se a última semente deixar duas ou três numa cova adversária, elas são capturadas. Saber onde a semeadura vai parar — contar antes — é tudo. O oware cruzou o Atlântico e também é jogado no Caribe."],"cap":["A semeadura no oware. As três sementes da cova do anel dourado vão uma a uma no sentido anti-horário; a última deixa exatamente 3 numa cova adversária, que são capturadas (anel vermelho)"]},{"h":"Duas fileiras e quatro","p":["Os tabuleiros de mancala dividem-se em geral em dois tipos: de duas e de quatro fileiras. Os de duas predominam na África Ocidental e na Ásia; os de quatro vão da África Oriental ao sul do continente. O bao da Tanzânia tem 4 fileiras de 8 covas, e o nome significa simplesmente «tabuleiro» em suaíli.","Alguns, como o congkak e o sungka do Sudeste Asiático, têm em cada ponta uma cova grande — um depósito — para as sementes capturadas. O kalah, nascido nos EUA no século XX, é um jogo de duas fileiras com depósitos, e em 2000 calculou-se que o kalah de seis covas com quatro sementes é sempre vencido pelo primeiro jogador."],"cap":["Exemplos de tabuleiros de mancala: 2 fileiras de 6 (oware e outros), 2 fileiras de 7 com um depósito em cada ponta (congkak do Sudeste Asiático e outros), 4 fileiras de 8 (bao da África Oriental e outros)"]},{"h":"Quem o registrou","p":["Costuma-se dizer que o primeiro estudioso europeu a descrever o mancala em detalhe foi o inglês Thomas Hyde. Em De Ludis Orientalibus (1694), deu seu nome árabe e explicou como se jogava.","Em 1836, Edward W. Lane, ao descrever o cotidiano do Cairo, registrou o «mankalah» jogado nos cafés. Hoje os pesquisadores reuniram jogos de toda parte, e as regras registradas somam centenas."],"cap":[]}],"tl":[["sécs. VI–VII","Os tabuleiros mais antigos bem datados, em sítios de Axum"],["1694","Thomas Hyde descreve o mancala em De Ludis Orientalibus"],["sécs. XVIII–XIX","O oware e outros cruzam o Atlântico até o Caribe"],["1836","E. W. Lane registra o mankalah do Cairo"],["meados do séc. XX","O kalah, de duas fileiras com depósitos, é vendido nos EUA"],["2000","Calcula-se que o kalah de seis covas e quatro sementes é vitória do primeiro jogador"]]},"morris":{"title":"A trilha está em toda parte","lead":"O telhado de um templo, um navio viking, o banco de pedra de uma catedral: suas linhas foram gravadas onde quer que as pessoas se sentassem juntas.","s":["Na trilha (nine men’s morris), cada jogador coloca nove peças nos 24 pontos de três quadrados encaixados; três em linha, um “moinho”, capturam uma peça adversária. O nome inglês “morris” nada tem a ver com a dança: viria do latim merellus, ficha.","Um tabuleiro gravado numa laje do telhado do templo de Kurna, no Egito, costuma ser apresentado como o mais antigo, de cerca de 1400 a.C. Mas o estudioso Friedrich Berger notou cruzes coptas entre essas mesmas gravações e concluiu que não podem ser datadas. Os exemplos seguros começam na época romana.","No navio de Gokstad, da Noruega, de cerca do ano 900, há um tabuleiro talhado numa tábua do convés. Na Inglaterra restam tabuleiros nos bancos de pedra dos claustros de catedrais como Canterbury e Salisbury.","O Livro dos Jogos de Afonso X, de 1283, mostra-o até jogado com dados. Shakespeare, em Sonho de uma Noite de Verão, conta que as chuvas encheram de lama o “nine men’s morris”: um tabuleiro cavado no gramado da aldeia.","Em 1996, o alemão Ralph Gasser examinou por computador todas as posições e provou que, com jogo perfeito dos dois lados, a partida empata. Entre duas pessoas continua sendo um ótimo jogo."],"quiz":[["De onde viria o nome “morris”?","Do latim “ficha”","De uma dança inglesa","De um nome de pessoa","Do nome de um navio"],["O que os estudiosos apontaram sobre os tabuleiros de Kurna?","Que não podem ser datados","Que são de ouro","Que vieram da China","Que eram de um imperador"],["O que um computador provou em 1996?","Com jogo perfeito, empate","Quem começa sempre vence","O segundo sempre vence","Oito peças bastam"]],"kf":["Nove peças por jogador nos 24 pontos de três quadrados encaixados; três em linha capturam uma peça adversária","Desde a época romana seu tabuleiro foi gravado onde as pessoas se reuniam: conveses de navios, bancos de catedrais","Em 1996 todas as posições foram examinadas por computador: com jogo perfeito, empate"],"more":[{"h":"Colocar, mover, voar","p":["O jogo tem três fases. Primeiro os jogadores colocam por turnos suas nove peças em pontos vazios. Quando todas estão colocadas, movem uma peça por vez ao longo de uma linha até um ponto vizinho vazio.","Três peças suas em linha formam um «moinho», e você retira uma peça do adversário. Uma regra comum deixa quem ficou com três peças «voar» para qualquer ponto vazio. Perde quem fica com duas peças ou não pode mover."],"cap":["Um tabuleiro de trilha. As brancas formaram um moinho no lado externo (dourado) e podem retirar uma peça preta (cruz vermelha)"]},{"h":"De três peças a doze","p":["A família é nomeada pelo número de peças. A trilha de três, com três peças cada, é um tabuleiro pequeno, próximo do jogo da velha. A de seis usa um tabuleiro de dois quadrados encaixados.","A de doze acrescenta linhas diagonais ao tabuleiro da de nove. Na África do Sul chama-se morabaraba; diz-se que meninos pastores o riscavam no chão, e hoje tem seus próprios torneios."],"cap":["Tabuleiros comparados. O número é quantas peças cada jogador tem: trilha de três, de seis, de nove e de doze"]},{"h":"Um campeão de xadrez e um computador","p":["O campeão mundial de xadrez Emanuel Lasker foi um dos que se apaixonaram pelo jogo. No livro Brettspiele der Völker (1931) propôs uma versão com dez peças para cada um, em que se pode mover antes de colocar todas.","Em 1996, Ralph Gasser, na Suíça, combinou tabelas completas de finais com uma busca a partir da abertura e mostrou que a trilha de nove é empate se os dois jogarem perfeitamente. O tabuleiro tem só 24 pontos, mas as posições chegam a bilhões."],"cap":[]}],"tl":[["época romana","Tabuleiros gravados em pedra por todo o império (os primeiros exemplos seguros)"],["c. 900","Um tabuleiro é gravado numa tábua do convés do navio de Gokstad (Noruega)"],["1283","O Livro dos Jogos de Afonso X ilustra a trilha"],["Idade Média","Tabuleiros gravados em bancos de claustros de catedrais inglesas"],["década de 1590","Sonho de uma Noite de Verão, de Shakespeare, cita um tabuleiro cheio de lama"],["1931","Lasker propõe uma nova versão em Brettspiele der Völker"],["1996","Gasser prova que com jogo perfeito é empate"]]},"patolli":{"title":"Patolli, a corrida de feijões asteca","lead":"Um tabuleiro em cruz e feijões como dados: um jogo de apostas tão acaloradas que os espanhóis o proibiram.","s":["O patolli era um jogo de corrida dos astecas do México. O nome significa feijões: lançavam-se cinco feijões vermelhos marcados ou furados de um lado e avançava-se conforme as marcas visíveis, num percurso em cruz pintado numa esteira ou no chão.","Diego Durán, que registrou a região no século XVI, escreveu que os jogadores queimavam incenso e rezavam aos feijões antes de lançar, e invocavam Macuilxóchitl, deus dos jogos, para vencer.","Os nobres apostavam joias, mantos e até a si mesmos; alguns que perdiam viravam escravos. Conta-se também que o imperador Montezuma assistia aos nobres jogarem.","Os frades espanhóis, contrários às apostas e às preces aos deuses antigos, proibiram o patolli, quebraram as esteiras e queimaram os feijões, e por isso restam poucos jogos. Mesmo assim, tabuleiros gravados em pisos de pedra e rochas foram achados em Teotihuacan e em sítios maias, e em 1977 entre petróglifos de Jalisco.","Um tabuleiro em cruz com peças que o percorrem lembra muito o pachisi da Índia. Em 1878 o inglês E. B. Tylor defendeu uma origem asiática; hoje a maioria acha que os dois surgiram separadamente."],"quiz":[["O que se lançava no patolli em vez de dados?","Feijões marcados","Ossos de animais","Conchas","Varetas"],["Segundo os registros, por que o patolli foi proibido?","Pelas apostas e preces aos deuses antigos","O tabuleiro era grande demais","Os feijões eram caros","O rei perdeu"],["Com que jogo o tabuleiro do patolli se parece muito?","Pachisi","Go","Damas","Mancala"]],"kf":["Um jogo de corrida asteca: lançam-se cinco feijões marcados e movem-se peças num tabuleiro em cruz","Ligado a apostas e orações aos deuses, foi proibido pelos frades espanhóis","Parece-se muitíssimo com o pachisi da Índia, mas acredita-se que os dois nasceram separadamente"],"more":[{"h":"Um caminho em cruz de 52 casas","p":["O tabuleiro de patolli é um caminho em forma de cruz pintado em pano, esteira ou piso de pedra. As reconstruções costumam dar a cada braço duas pistas de casas que, com as quatro do centro, somam 52.","Cinquenta e dois é também o número de anos do ciclo do calendário asteca, e alguns pesquisadores veem no tabuleiro uma imagem do calendário ou da passagem do tempo. Os jogadores davam uma volta completa com suas peças, e vencia o primeiro a voltar."],"cap":["Um tabuleiro de patolli como costuma ser reconstruído: quatro braços com duas pistas de seis casas, mais quatro centrais, 52 no total. As casas vermelhas nas pontas seriam especiais"]},{"h":"Cinco feijões","p":["Em vez de dados lançavam-se cinco feijões marcados numa face com um furo ou sinal, e andava-se tantas casas quantas marcas aparecessem. As cinco marcas saem só uma vez em 32.","Diz-se que antes do lance se falava com os feijões e se invocava Macuilxóchitl, deus dos jogos. O Códice Magliabechiano, do século XVI, mostra pessoas em volta de um patolli sob o olhar do deus."],"cap":["De cinco feijões, quantos caem com a face marcada para cima (0–5) e com que frequência (em 32), se cada um cair de um lado ou de outro por igual"]},{"h":"O sósia do pachisi","p":["Peças que circulam um tabuleiro em cruz e avanços conforme quantas peças lançadas caem para cima: o patolli e o pachisi ou o chaupar da Índia são espantosamente parecidos. Em 1878 o antropólogo britânico Tylor defendeu que isso não era acaso, mas sinal de que o jogo viera da Ásia.","Mas nenhuma prova de tal travessia dos oceanos foi encontrada. Hoje a maioria pensa que, em lugares diferentes, as pessoas chegaram por conta própria às mesmas ideias: um caminho que dá a volta e peças para lançar."],"cap":["Pintura do chaupar na Índia (1694–95): peças dando a volta num tabuleiro em cruz, como no patolli"]}],"tl":[["época de Teotihuacan","Tabuleiros em cruz são gravados em pisos de pedra"],["1519–21","A Espanha conquista os astecas"],["séc. XVI","O Códice Magliabechiano mostra o patolli e Macuilxóchitl"],["c. 1577","Sahagún registra o patolli no Códice Florentino"],["c. 1581","Durán descreve as orações e as apostas"],["1878","Tylor defende uma origem asiática"],["1977","Um tabuleiro é achado entre a arte rupestre de Jalisco"]]},"xiangqi":{"title":"O rio e o canhão do xiangqi","lead":"Um “rio” no meio e um canhão que salta para capturar: quando o xadrez chinês ganhou a forma atual?","s":["O xiangqi é o xadrez chinês, jogado nos pontos de uma grade de 9×10. As peças são discos com caracteres e se movem sobre as linhas, não dentro de casas como no xadrez.","Uma pista antiga é o Xuanguai lu, livro de contos estranhos do ministro Tang Niu Sengru (779–847). O sonho de um homem com um exército minúsculo cita um cavalo celeste, um general, carros e infantaria, com indícios de uma catapulta. Mas o tabuleiro e os lances não são os de hoje.","A forma atual — tabuleiro 9×10, rio e canhão — aparece em registros da dinastia Song (960–1279). Um conjunto completo de peças foi achado num túmulo Song do Norte em Luoyang.","O rio costuma trazer escrito “Rio Chu, fronteira Han”, pela linha entre o Chu de Xiang Yu e o Han de Liu Bang na guerra do século III a.C. O general não pode sair do palácio, e os dois generais nunca podem ficar frente a frente sem nada entre eles.","O canhão só captura saltando exatamente uma peça. O xiangqi é muito querido no Vietnã como cờ tướng e, na Coreia, deu origem ao primo próximo janggi. No Atlas dá para jogar os dois."],"quiz":[["Onde se movem as peças do xiangqi?","Nos pontos das linhas","Dentro de casas","Em volta de um círculo","Em hexágonos"],["Em que dinastia o xiangqi atual aparece nos registros?","Song","Han","Ming","Qing"],["Como o canhão captura?","Saltando uma peça","Um passo reto","Dois passos na diagonal","Só depois do rio"]],"kf":["O xadrez chinês: peças redondas com caracteres lutam nos pontos de uma grade de 9 × 10 linhas","Um «rio» cruza o meio e cada lado tem um «palácio» para o general; cada peça tem seu território","Ganhou a forma atual na dinastia Song e ainda é jogado por dezenas de milhões na China e no Vietnã"],"more":[{"h":"Um tabuleiro com rio e palácios","p":["Cada lado tem 16 peças: um general, 2 conselheiros, 2 elefantes, 2 cavalos, 2 carros, 2 canhões e 5 soldados. Vermelhas e pretas escrevem algumas peças de mesma função com caracteres um pouco diferentes.","O general e os conselheiros não podem sair do palácio, e os elefantes não podem cruzar o rio. Os soldados só avançam para a frente até cruzar o rio; depois, podem ir também para o lado. O cavalo não pode saltar se houver uma peça logo ao lado na direção em que quer ir. O próprio tabuleiro define o papel de cada peça."],"cap":["Posição inicial do xiangqi. Pretas em cima, vermelhas embaixo. Os caracteres 楚河 漢界 marcam o rio; as áreas 3 × 3 com diagonais são os palácios"]},{"h":"O canhão que salta","p":["O canhão normalmente anda como o carro, qualquer distância ao longo de uma linha. Mas para capturar precisa saltar exatamente uma peça no meio, de qualquer cor, chamada anteparo.","Usar peças como anteparo cria táticas que não existem em outros jogos. Levar um canhão para a coluna central logo no início, o «canhão central», continua sendo uma das aberturas mais populares."],"cap":["Como o canhão captura: o canhão vermelho salta exatamente uma peça no meio — o cavalo preto — para tomar o carro preto mais adiante"]},{"h":"Registros e mestres","p":["Na dinastia Ming publicaram-se muitos livros reunindo belas partidas e problemas. O Shiqing yaqu (1570) e o Juzhong mi (1632) são clássicos ainda estudados.","No século XX, Hu Ronghua venceu dez vezes seguidas o campeonato nacional chinês, e em 1993 foi fundada a Federação Mundial de Xiangqi, trazendo torneios internacionais. Nos parques da China e do Vietnã, rodas de curiosos ainda se formam todo dia em volta do tabuleiro."],"cap":[]}],"tl":[["séc. IX","O Xuanguai lu de Niu Sengru cita generais, carros e cavalos"],["Song (960–1279)","A forma atual, com tabuleiro de 9 × 10, rio e canhão, aparece nos registros"],["Song do Norte","Um jogo completo de peças é posto numa tumba em Luoyang"],["1570","A coletânea de partidas Shiqing yaqu"],["1632","A coletânea de partidas Juzhong mi"],["décadas de 1960–70","Hu Ronghua conquista dez títulos nacionais seguidos"],["1993","Fundação da Federação Mundial de Xiangqi"]]},"backgammon":{"title":"O gamão tem 5.000 anos?","lead":"O tabuleiro chamado “o gamão mais antigo” e os verdadeiros ancestrais do jogo: de uma corte persa aos clubes de Nova York.","s":["A “Cidade Queimada” de Shahr-e Sukhteh, no Irã, revelou um tabuleiro de uns 5.000 anos, com 60 peças e dados, muitas vezes chamado de gamão mais antigo. Mas suas casas são formadas pelas voltas de uma serpente esculpida, cerca de vinte — uma forma diferente do jogo atual.","O provável ancestral direto do gamão é o nard persa, surgido entre os séculos III e VI. Um conto em persa médio, escrito entre os séculos VII e IX, diz que o ministro Bozorgmehr, depois de resolver o enigma do xadrez enviado da Índia, inventou o nard em resposta.","Roma tinha seu próprio jogo de tabuleiro com três dados, a tabula — a partida azarada do imperador Zenão na história 3. Essa família das “tábulas” espalhou-se pela Europa e gerou muitos parentes, como o trictrac francês.","O nome inglês “backgammon” aparece na Inglaterra do século XVII, e em 1743 Edmond Hoyle publicou suas regras e estratégia.","A última grande invenção, o cubo de dobra, teria surgido em clubes de Nova York nos anos 1920. Ao permitir dobrar a aposta no meio da partida, transformou o gamão num jogo profundo de saber quando pressionar."],"quiz":[["Que forma tem o tabuleiro de Shahr-e Sukhteh?","Casas feitas pelas voltas de uma serpente","A mesma do gamão atual","Um disco redondo","Uma cruz"],["Segundo o conto, quem inventou o nard?","O ministro Bozorgmehr","O imperador Zenão","Edmond Hoyle","Afonso X"],["O que teria surgido em Nova York nos anos 1920?","O cubo de dobra","Os dois dados","Os 24 triângulos","As quinze peças"]],"kf":["Quinze peças por lado correm sobre 24 casas triangulares com dois dados; vence quem tirar todas primeiro","Seus ancestrais diretos são o nard persa e a tabula romana, da família das «tábulas»","O cubo de dobra e os computadores lhe deram nova profundidade no século XX"],"more":[{"h":"Quinze peças e 24 casas","p":["O tabuleiro tem 24 triângulos compridos, ou casas, e cada jogador tem 15 peças. Lançam-se dois dados e move-se uma peça por cada número, ou uma só pelos dois. Uma dupla permite usar o número quatro vezes.","Parar sobre uma peça adversária sozinha a «acerta» e a manda para a barra no meio; ela tem de reentrar pelo campo interno do adversário. Com as quinze peças no próprio campo interno, começa-se a tirá-las do tabuleiro, e vence quem terminar primeiro."],"cap":["Posição inicial do gamão. As brancas vão da 24 à 1 (sentido anti-horário); as casas 1–6, embaixo à direita, são seu campo interno. As pretas vão no sentido oposto"]},{"h":"Quanto mais perto, mais fácil acertar","p":["Acertar uma peça sozinha depende muito da distância. A seis casas, 17 dos 36 lances acertam; a sete, só 6.","Conhecer esses números mostra onde uma peça corre perigo. No início, cada jogador precisa de 167 pontos de dado para levar todas as peças para casa e tirá-las; os bons jogadores contam esse «pip count» para saber quem está na frente."],"cap":["Quantos dos 36 lances de dois dados podem acertar uma peça sozinha a 1–12 casas de distância (sem nada no caminho)"]},{"h":"Dos clubes aos campeonatos mundiais","p":["Em 1743 Edmond Hoyle publicou na Inglaterra um livro de regras e estratégia. Na Grã-Bretanha do século XIX o jogo era tão querido que era pintado em móveis, e nos clubes de Nova York dos anos 1920 nasceu o cubo de dobra.","Em 1964 houve um campeonato mundial nas Bahamas, e o jogo viveu um boom nos anos 1970. Em 1979 o programa de Hans Berliner venceu o campeão mundial Luigi Villa, e por volta de 1992 o TD-Gammon, que aprendia jogando contra si mesmo, chegou perto dos melhores humanos."],"cap":["Um móvel pintado com dois jogadores de gamão (Londres, 1861), uma das primeiras peças da Morris, Marshall, Faulkner & Co."]}],"tl":[["c. 3000 a.C.","Um tabuleiro de serpente enrolada, peças e dados são enterrados em Shahr-e Sukhteh"],["c. sécs. III–VI","O nard surge na Pérsia"],["1743","Hoyle publica seu livro sobre o gamão"],["década de 1920","Nasce em Nova York o cubo de dobra"],["1964","Campeonato mundial nas Bahamas"],["1979","O programa de Berliner vence o campeão mundial"],["c. 1992","Surge o TD-Gammon, que aprende jogando contra si mesmo"]]},"hex":{"title":"Hex, inventado duas vezes","lead":"Um poeta dinamarquês e um jovem gênio americano criaram o mesmo jogo, cada um sem saber do outro.","s":["No Hex, os jogadores colocam pedras alternadamente num losango de hexágonos; vence quem ligar seus dois lados opostos. É só isso.","O primeiro a pensar nele foi o matemático e poeta dinamarquês Piet Hein. Em 1942 apresentou-o no Instituto Niels Bohr, em Copenhague; em 26 de dezembro daquele ano o jornal Politiken publicou-o como “Polygon”, vendido em blocos de 50 folhas.","Em 1943 Hein teve de deixar a Dinamarca, e o jogo sumiu. Alguns anos depois, em 1948–49, John Nash, estudante de pós-graduação em Princeton, inventou o mesmo jogo de forma totalmente independente; seus colegas o chamavam de “Nash”.","Em 1952 a Parker Brothers lançou-o como “Hex”, e em 1957 Martin Gardner apresentou-o em sua coluna na Scientific American, tornando-o conhecido no mundo todo.","O Hex nunca termina empatado. E Nash provou que o primeiro jogador sempre tem uma estratégia vencedora — sem mostrar qual. Em tabuleiros grandes, esse caminho para vencer ainda é desconhecido."],"quiz":[["Como se vence no Hex?","Ligando seus dois lados","Capturando todas as pedras","Cercando o rei","Fazendo cinco em linha"],["Como se chamava o jogo de Hein no jornal dinamarquês?","Polygon","Nash","Con-tac-tix","Othello"],["O que Nash provou?","O primeiro sempre pode vencer","O segundo sempre vence","Sempre dá empate","Os lances vencedores exatos"]],"kf":["Colocam-se pedras por turnos em casas hexagonais; vence quem liga seus dois lados opostos","Inventado separadamente por Piet Hein na Dinamarca em 1942 e John Nash nos EUA em 1948–49","Não há empates e está provado que o primeiro jogador vence — mas nos tabuleiros grandes ninguém sabe como"],"more":[{"h":"Um jogo de ligar","p":["O tabuleiro é um losango de casas hexagonais; o tamanho oficial é 11 × 11. O vermelho defende os lados de cima e de baixo, o azul os laterais, e colocam uma pedra por vez. As pedras nunca se movem nem são capturadas.","Quando o tabuleiro se enche, um dos lados está sempre ligado. Hexágonos nunca se tocam só pela ponta, então não dá para escapar por entre a linha do adversário. Em 1979 o matemático David Gale mostrou que essa propriedade de «não haver empate» equivale a um célebre resultado matemático, o teorema do ponto fixo de Brouwer."],"cap":["Um tabuleiro de hex 7 × 7. O vermelho vence ligando cima e baixo; o azul, esquerda e direita. As pedras vermelhas de borda dourada já ligaram cima e baixo"]},{"h":"Pontes e escadas","p":["Uma ferramenta favorita dos bons jogadores é a ponte. Pondo uma pedra não ao lado da anterior, mas uma casa adiante, as duas passam a ter duas vizinhas vazias em comum. Se o adversário tapa uma, você pega a outra: na prática, já estão ligadas.","Junto às bordas conhecem-se muitas formas fixas, como as «escadas» de pedras que correm ao longo do lado até alcançá-lo. Como o primeiro jogador leva vantagem demais, costuma-se usar a regra da troca: após o primeiro lance, o segundo pode ficar com essa pedra."],"cap":["A «ponte». As duas pedras vermelhas podem se ligar por qualquer uma das duas casas vazias entre elas (círculos tracejados). Se o azul ocupar uma, o vermelho ocupa a outra"]},{"h":"Um jogo de matemáticos","p":["Nash provou que o primeiro jogador vence com um argumento de «roubo de estratégia»: se o segundo tivesse uma estratégia vencedora, o primeiro poderia tomá-la para si, o que é contraditório. É uma prova curiosa, que não mostra nenhum lance vencedor.","Nos anos 1950, Claude Shannon, pai da teoria da informação, construiu uma máquina que jogava hex com um circuito elétrico. Na década de 2010, computadores resolveram todos os tabuleiros até 9 × 9, mas o oficial de 11 × 11 continua sem solução."],"cap":[]}],"tl":[["1942","Hein publica «Polygon» num jornal dinamarquês"],["1948–49","Nash, em Princeton, cria o mesmo jogo"],["1952","A Parker Brothers o vende como «Hex»"],["década de 1950","Shannon constrói uma máquina elétrica que joga hex"],["1957","Gardner o apresenta em sua coluna"],["1979","Gale mostra sua ligação com o teorema do ponto fixo"],["década de 2010","Tabuleiros até 9 × 9 são resolvidos por computador"]]},"foxgeese":{"title":"A raposa, os gansos e as peças de prata do rei","lead":"Uma raposa e muitos gansos: a longa história de um “jogo de caça” em que os dois lados não são iguais.","s":["Na raposa e os gansos, uma única raposa salta sobre os gansos para comê-los, enquanto os gansos tentam encurralá-la para que não possa se mover. Cada lado tem regras diferentes, num tabuleiro em cruz de 33 pontos ligados por linhas.","Uma pista antiga é o “halatafl” da saga islandesa de Grettir, escrita por volta do século XIV. Significa “tabuleiro da cauda”, e a cauda seria a da raposa. Provavelmente era um ramo dos jogos nórdicos de tafl.","Na Inglaterra, as contas do rei Eduardo IV, do século XV, registram a compra de “duas raposas e 26 cães de prata dourada”: peças para dois jogos, chamados então, ao que parece, de “raposa e cães”.","Com os 13 gansos originais a raposa era forte demais, por isso espalharam-se formas de jogar com mais gansos. Diz-se que no século XIX a rainha Vitória gostava do jogo.","O mesmo tabuleiro em cruz serve para o resta um, jogo de um só jogador. Jogos de caça em que um tigre ou lobo persegue a presa, como o bagh-chal do Nepal, existem no mundo todo. No Atlas dá para jogar a raposa e os gansos e o resta um."],"quiz":[["O que significa “hala” em halatafl?","Cauda","Raposa","Rei","Neve"],["Que peças aparecem nas contas de Eduardo IV?","Raposas e cães de prata","Gansos de ouro","Um rei de marfim","Dados de madeira"],["Que jogo de um jogador usa o mesmo tabuleiro em cruz?","Resta um","Sudoku","Paciência (cartas)","Tangram"]],"kf":["Uma raposa contra 13 gansos (depois 17) num tabuleiro em cruz de 33 pontos","A raposa captura saltando; os gansos vencem se a encurralarem sem saída","O mesmo tabuleiro serve para o resta um, e há jogos de caça assim no mundo todo"],"more":[{"h":"Um contra treze","p":["A raposa anda um passo pelas linhas e captura saltando sobre um ganso vizinho se o ponto seguinte estiver vazio; como nas damas, pode encadear vários saltos. Os gansos não capturam e, em muitas versões, não podem recuar.","Os gansos tentam fechar fileiras sem brechas, encurralar a raposa e deixá-la sem lance. Diz-se que com treze gansos a raposa leva vantagem demais; com dezessete gansos que não recuam, jogando bem, os gansos vencem."],"cap":["Tabuleiro de raposa e gansos: 33 pontos em cruz ligados por linhas. Treze gansos em cima; a raposa (laranja) pode comer o ganso logo à frente (×) saltando para o ponto vazio de trás"]},{"h":"A família dos jogos de caça","p":["Poucas peças fortes caçando muitas fracas: há jogos de caça assim em todo o mundo. No bagh-chal do Nepal, quatro tigres caçam vinte cabras num tabuleiro de 5 × 5; em 2004 calculou-se que, com jogo perfeito, é empate.","O assalto, popular na Alemanha do século XIX, usa o mesmo tabuleiro em cruz: dois oficiais contra vinte e quatro soldados. Aqui os oficiais defendem uma fortaleza que os soldados tentam tomar."],"cap":["Jogos de caça em números: caçadores à esquerda (laranja), presas à direita (branco). De cima para baixo: raposa e gansos (1:13), a versão com mais gansos (1:17), o bagh-chal do Nepal (4:20) e o assalto (2:24)"]},{"h":"Das peças do rei ao resta um","p":["As contas de Eduardo IV da Inglaterra (reinou 1461–83) registram a compra de peças de prata dourada para um jogo de raposa e cães. Também era passatempo de reis e nobres.","O mesmo tabuleiro em cruz de 33 furos é usado no resta um, jogado sozinho. Uma gravura francesa de 1697 mostra uma dama nobre jogando-o — um dos registros mais antigos do resta um."],"cap":[]}],"tl":[["c. séc. XIV","O «hala-tafl» aparece na islandesa Saga de Grettir"],["fim do séc. XV","Eduardo IV compra peças de prata para raposa e cães"],["1697","Uma gravura francesa mostra uma dama jogando resta um"],["séc. XIX","Diz-se que a rainha Vitória gostava do jogo"],["séc. XIX","O assalto, no mesmo tabuleiro, vira moda na Alemanha"],["2004","Mostra-se que o bagh-chal do Nepal é empate com jogo perfeito"]]},"latrunculi":{"title":"O tabuleiro dos soldados romanos","lead":"Um jogo que fascinava os romanos, com nome de soldados mercenários. Nenhum livro de regras sobreviveu — só poemas, anedotas e tabuleiros saídos da terra.","s":["O ludus latrunculorum era um jogo de batalha para dois da Roma antiga. Latrunculi significava originalmente mercenários ou bandidos, e as peças representavam soldados.","As peças moviam-se numa grade, e uma peça presa entre duas inimigas era capturada. Um poema do século I, a Laus Pisonis, descreve peças que avançam e recuam, e uma peça cercada até não poder se mover.","O filósofo Sêneca conta a história de Júlio Cano, condenado à morte pelo imperador Calígula. Quando o centurião veio buscá-lo, Cano jogava latrunculi; contou as peças e disse ao adversário que não alegasse, depois de sua morte, ter vencido.","Há tabuleiros encontrados por todo o império. As grades gravadas em pedras de fortes e cidades vão de cerca de 8 × 8 a 12 × 12. Uma tumba do século I em Stanway, na Inglaterra, guardava peças de vidro ainda dispostas sobre o tabuleiro.","Nenhum livro de regras detalhado sobreviveu: as regras de hoje são reconstruções de pesquisadores. O latrunculi do Atlas baseia-se numa delas."],"quiz":[["Como se captura uma peça no latrunculi?","Prendendo-a entre duas peças","Saltando sobre ela","Por um lance de dados","Cercando o rei"],["Quem jogava latrunculi quando vieram levá-lo para a execução?","Júlio Cano","César","Nero","Cícero"],["O que ainda estava sobre o tabuleiro na tumba de Stanway?","Peças de vidro","Moedas de ouro","Peças de xadrez","Cartas de baralho"]],"kf":["Um jogo de batalha para dois da Roma antiga, com peças vistas como soldados","Uma peça presa entre duas inimigas é capturada; peças que não podem se mover também são citadas","Sem livro de regras, é reconstruído a partir de poemas, anedotas e tabuleiros escavados"],"more":[{"h":"Prender e cercar","p":["A fonte mais completa para as reconstruções é o poema do século I Laus Pisonis. Ele descreve o jogo como um campo de batalha: uma peça avança para atrair o inimigo, outra guarda suas costas, e a que fica entre duas inimigas se perde.","O poema fala também de uma peça cercada e sem movimento, por isso muitas reconstruções acrescentam uma regra para peças bloqueadas além da captura por cerco. Os jogos de tafl nórdicos usam uma captura muito parecida."],"cap":["A captura no latrunculi (reconstrução). Esquerda: avançando como mostra a seta azul, a peça branca fica entre duas pretas e é capturada (×). Direita: uma branca bloqueada nos quatro lados não pode se mover"]},{"h":"Um tabuleiro de duas faces","p":["Num poema para acompanhar um presente, o poeta Marcial (século I) descreve um tabuleiro em que, de um lado, as peças avançam pelos dados e, do outro, lutam soldados de duas cores: um jogo de sorte e um de raciocínio numa só tábua.","Acredita-se que o lado dos dados seja o jogo de corrida chamado «doze linhas», antecessor da tabula e do gamão. A torre de dados (pyrgus) do acervo do museu é outro objeto usado pelos romanos."],"cap":["O tabuleiro de duas faces de Marcial, imaginado: numa face, uma corrida de doze linhas com dados; na outra, a grade dos soldados"]},{"h":"Tabuleiros saídos da terra","p":["Os soldados romanos gravavam grades nas pedras e pisos de seus fortes para jogar. Foram achados tabuleiros gravados perto da Muralha de Adriano, na Britânia, e na Alemanha, na Espanha e no norte da África.","Na tumba de Stanway (meados do século I), o tabuleiro de madeira apodrecera, mas as peças de vidro brancas e azuis continuavam no lugar, como no meio de uma partida. O dono talvez fosse médico: instrumentos médicos foram enterrados com elas."],"cap":["Uma torre de dados (pyrgus). Os romanos lançavam os dados por torres assim para evitar trapaças"]}],"tl":[["séc. I a.C.","Varrão menciona os latrunculi"],["fim do séc. I a.C.","Ovídio alude ao jogo em sua poesia amorosa"],["séc. I","A Laus Pisonis descreve o jogo em versos"],["meados do séc. I","Um tabuleiro com as peças dispostas é enterrado em Stanway"],["séc. I","Sêneca conta a anedota de Júlio Cano"],["fim do séc. I","Marcial escreve sobre um tabuleiro de duas faces"],["1994","Schädler publica uma reconstrução das regras"]]},"amazons":{"title":"O jogo que queima o próprio tabuleiro","lead":"Nascido na Argentina em 1988, o jogo das amazonas une o movimento da dama do xadrez à contagem de território do go.","s":["O jogo das amazonas é um jogo para dois num tabuleiro de 10 × 10, com quatro «amazonas» de cada lado. Foi inventado em 1988 pelo argentino Walter Zamkauskas.","Cada lance tem duas partes. Primeiro uma amazona se move como a dama do xadrez, em linha reta na horizontal, vertical ou diagonal; depois, de onde chega, atira uma flecha do mesmo jeito. A casa atingida pela flecha nunca mais pode ser atravessada.","Cada lance ocupa mais uma casa, e perde o jogador que não consegue mais se mover. Não há empate.","No fim, as flechas dividem o tabuleiro em salas separadas. Vence então quem tem mais casas vazias só suas, por isso a posição é julgada contando território, como no go.","Há mais de 2.000 primeiros lances possíveis, o que torna o jogo difícil até para computadores. Matemáticos o estudam, e ele é modalidade em torneios de computadores."],"quiz":[["Em que país nasceu o jogo das amazonas?","Argentina","Brasil","Espanha","México"],["O que acontece com a casa atingida por uma flecha?","Ninguém pode mais atravessá-la","Some no lance seguinte","Vira peça do adversário","Vale um ponto"],["Quem perde no jogo das amazonas?","O primeiro que não consegue se mover","O primeiro que perde uma peça","O primeiro que forma território","Quem estoura o tempo"]],"kf":["Um jogo para dois num tabuleiro de 10 × 10, nascido na Argentina em 1988","A amazona se move como a dama e atira uma flecha de onde chega para queimar uma casa","Perde quem não pode se mover; no fim, conta-se o território como no go"],"more":[{"h":"Mover e atirar","p":["A amazona pode andar quantas casas quiser, desde que não passe por outra peça ou flecha. Da casa onde chega, atira então uma flecha, também com movimento de dama — até para a casa que acabou de deixar.","Nada é capturado. Em vez disso, cada lance fecha uma casa do tabuleiro e bloqueia os caminhos do adversário: ataque e defesa se decidem com a mesma flecha."],"cap":["Um lance no jogo das amazonas. A amazona branca se move como a dama (azul) e, de onde chega, atira uma flecha do mesmo jeito (vermelho). A casa da flecha fica fechada para sempre"]},{"h":"Um tabuleiro dividido em salas","p":["Com o avanço da partida, as flechas dividem o tabuleiro em salas. Se numa sala só há amazonas de um jogador, as casas vazias dela são só dele, para gastar uma por lance.","Aí a partida vira uma contagem: quem tem mais casas utilizáveis consegue se mover por mais tempo. Isso combina com a teoria dos jogos combinatórios, e Elwyn Berlekamp, entre outros, estudou a fundo os finais das amazonas."],"cap":["Posição final (ilustração). Paredes de casas queimadas dividem o tabuleiro em quatro salas: as verdes só as brancas podem usar, as azuis só as pretas. Quem tem mais casas vazias consegue se mover por mais tempo"]},{"h":"Nascido numa revista, disputado por computadores","p":["Diz-se que o jogo apareceu primeiro numa revista argentina de enigmas. As regras são curtas e basta um tabuleiro de xadrez e algumas peças, por isso ele se espalhou pelo mundo pela internet.","Com mais de 2.000 primeiros lances possíveis, a abertura pede visão do tabuleiro inteiro, como no go. Desde os anos 2000 é modalidade em torneios de computadores, onde programas se enfrentam."],"cap":[]}],"tl":[["1988","Walter Zamkauskas inventa o jogo das amazonas"],["década de 1990","Espalha-se pelo mundo pela internet"],["2000","Berlekamp publica estudos matemáticos sobre seus finais"],["década de 2000","Vira modalidade da Olimpíada de Computadores"]]},"loa":{"game":"Lines of Action","title":"Peças que andam o quanto você conta","lead":"Lines of Action surgiu num livro de Sid Sackson em 1969. Não se vence capturando: vence-se juntando todas as suas peças num só grupo.","s":["Lines of Action (LOA) é um jogo para dois num tabuleiro de 8 × 8, com doze peças de cada lado. Foi inventado por Claude Soucie e apresentado em 1969 em A Gamut of Games, livro do colecionador de jogos Sid Sackson.","Uma peça anda em linha reta, na horizontal, na vertical ou na diagonal. A distância é exatamente o número de peças — suas e do adversário — nessa linha. Cada lance muda as contagens e, com elas, as distâncias.","Você pode pular suas próprias peças, mas nunca as do adversário. Se parar sobre uma peça adversária, você a captura.","O objetivo é juntar todas as suas peças num só grupo, encostadas na horizontal, na vertical ou na diagonal. Capturar diminui o exército adversário, o que às vezes até o ajuda a se juntar — uma reviravolta curiosa.","As regras são curtas, mas é difícil calcular adiante, por isso o jogo é muito usado na pesquisa de IA para jogos. Programas da Universidade de Maastricht, na Holanda, venceram muitas vezes torneios de computadores."],"quiz":[["O que decide quantas casas uma peça anda?","O número de peças naquela linha","O resultado de um dado","O número de peças capturadas até agora","São sempre três casas"],["Como se vence no LOA?","Juntando todas as suas peças num só grupo","Capturando todas as peças adversárias","Chegando à borda oposta do tabuleiro","Capturando o rei adversário"],["Quem apresentou o LOA num livro de 1969?","Sid Sackson","Martin Gardner","Edmond Hoyle","H. J. R. Murray"]],"kf":["Jogo para dois num tabuleiro de 8 × 8, doze peças cada; inventado por Claude Soucie e apresentado num livro de Sid Sackson de 1969","A peça anda exatamente tantas casas quantas peças há na sua linha; pode pular as próprias, nunca as do adversário","Vence não quem captura mais, mas quem primeiro junta todas as suas peças num só grupo"],"more":[{"h":"Contar e andar","p":["Se, por exemplo, há três peças na fileira que passa por uma peça, ela anda exatamente três casas ao longo dela — nem mais, nem menos. Pode passar por cima das próprias peças, mas, se houver uma peça adversária no meio, não pode seguir naquela direção.","Cada peça está em quatro linhas — uma fileira, uma coluna e duas diagonais —, cada uma com sua própria contagem. Quando uma peça se move, mudam as contagens de várias linhas ao redor, então as «distâncias» do tabuleiro são reembaralhadas a cada lance. É isso que torna o LOA tão difícil de prever."],"cap":["Para onde pode ir a peça preta de onde saem as setas. Na fileira há 3 peças, então ela anda 3 (pular a própria peça é permitido); na coluna há 2, então anda 2 e captura uma peça branca. Na diagonal também há 3, mas uma peça branca bloqueia o caminho (×)"]},{"h":"Um só grupo vence","p":["As peças contam como unidas quando se tocam na horizontal, na vertical ou na diagonal. Quem fica com uma única peça também está «unido», então capturar demais pode até entregar a vitória ao adversário.","O que acontece quando um lance une os dois lados ao mesmo tempo varia conforme a edição e o torneio. A primeira edição do livro de Sackson considerava empate, uma edição posterior vitória de quem moveu, e a maioria dos torneios atuais conta como empate. No LOA deste Atlas, vence quem moveu."],"cap":["Uma posição vencedora. As peças brancas (borda dourada) se tocam, incluindo as diagonais, e formam um só grupo. As pretas ainda estão divididas em três (tracejado)"]},{"h":"Um jogo disputado por computadores","p":["Com tabuleiro pequeno, regras curtas e jogo profundo, o LOA virou campo de testes para a IA de jogos. MIA, o programa de Mark Winands na Universidade de Maastricht, venceu a Olimpíada de Computadores em 2003, 2004, 2006 e 2009, e seu trabalho foi reunido na tese de doutorado de 2004, Informed Search in Complex Games.","Em 2008, Winands resolveu o LOA num tabuleiro reduzido de 6 × 6, mostrando que, com jogo perfeito, vence o primeiro jogador (pretas). Acredita-se que o jogo completo de 8 × 8 ainda não foi resolvido. Os jogadores humanos também se enfrentam num campeonato mundial realizado todos os anos na Mind Sports Olympiad."],"cap":[]}],"tl":[["c. 1960","Atribui-se a Claude Soucie a invenção do LOA"],["1969","Apresentado em A Gamut of Games, de Sid Sackson"],["2003","O MIA de Winands vence a Olimpíada de Computadores (e de novo em 2004, 2006 e 2009)"],["2004","Tese de doutorado de Winands, Informed Search in Complex Games"],["2008","O LOA 6 × 6 é resolvido: vitória do primeiro jogador"]]},"konane":{"title":"O jogo de lava negra e coral branco","lead":"O kōnane, jogado pelo povo do Havaí, ficou registrado no relato da viagem de Cook; no século XX, matemáticos o destrincharam com a teoria dos jogos combinatórios.","s":["O kōnane é um jogo para dois dos nativos havaianos. Pedras pretas e brancas enchem o tabuleiro alternadas, sem espaços, e os jogadores capturam saltando sobre as pedras do adversário.","Antigamente as pedras pretas eram de lava e as brancas, pedaços de coral. O tabuleiro, chamado papamū, era uma grande pedra plana com covinhas picadas na superfície. Diz-se que o jogo aparece até no Kumulipo, o canto havaiano da criação.","Primeiro as pretas retiram uma de suas pedras e depois as brancas retiram uma vizinha. Os dois buracos que ficam são o ponto de partida dos saltos.","Todo lance é uma captura. Uma pedra salta na horizontal ou na vertical sobre uma pedra adversária vizinha e pousa na casa vazia logo depois. Enquanto seguir em linha reta, pode continuar saltando.","Perde quem não tem mais capturas; não há empate. Esse desenho simples mais tarde despertou o interesse dos matemáticos."],"quiz":[["De que eram feitas as antigas pedras brancas do kōnane?","De coral","De marfim","De mármore branco","De osso"],["Quem perde no kōnane?","Quem não tem mais capturas","Quem perde todas as pedras","Quem chega primeiro à borda","Quem fica com uma só pedra"],["Ao encadear saltos, o que não é permitido?","Mudar de direção no caminho","Capturar mais de uma pedra no turno","Parar no meio","Pousar ao lado de uma pedra própria"]],"kf":["Jogo para dois dos nativos havaianos, que começa com pedras pretas (lava) e brancas (coral) alternadas em todo o tabuleiro","Todo lance salta na horizontal ou vertical sobre uma pedra adversária e a captura; em linha reta, pode saltar de novo","Perde quem fica sem capturas; matemáticos o estudaram com a teoria dos jogos combinatórios"],"more":[{"h":"Saltar e capturar","p":["Os saltos são só na horizontal ou na vertical, nunca na diagonal. Se a casa atrás de uma pedra adversária vizinha estiver vazia, a pedra salta, pousa ali e a pedra saltada sai do tabuleiro.","Se de onde pousou puder saltar de novo, pode continuar na mesma direção. Não pode mudar de direção no caminho, e pode parar quando quiser. Só uma pedra se move por turno."],"cap":["Uma pedra branca salta duas vezes para a direita num turno e captura duas pedras pretas (azul 1 e 2). Não pode virar e saltar para baixo de onde pousou (×)"]},{"h":"Os dois primeiros buracos","p":["Num tabuleiro cheio de pedras ninguém consegue saltar. Por isso as pretas, que começam, retiram uma de suas pedras das quatro casas centrais ou de um canto. Depois as brancas retiram uma das suas que toque esse buraco na horizontal ou na vertical.","Os dois buracos lado a lado são os primeiros pontos de pouso. Onde eles se abrem molda toda a partida."],"cap":["As duas maneiras de começar. As pretas retiram uma de suas pedras das quatro centrais (à esquerda) ou de um canto (à direita) (1); depois as brancas retiram uma vizinha (2)"]},{"h":"Tabuleiros de pedra e 238 casas","p":["O relato da terceira viagem de James Cook (volume III, publicado em 1784) descreve um jogo de pedras visto no Havaí como «muito parecido com as nossas damas», porém mais intrincado. Quem escreveu foi o oficial James King, segundo quem o tabuleiro tinha uns dois pés de comprimento e 238 casas, catorze por fileira.","Não havia tamanho fixo: são conhecidos tabuleiros de 6 × 7, 9 × 13, 13 × 20 e outros. Hoje costuma-se jogar num tabuleiro quadrado e par, e este Atlas oferece 6 × 6, 8 × 8 e 10 × 10. No Parque Histórico Nacional Puʻuhonua o Hōnaunau, na ilha do Havaí, ainda se veem papamū entalhados na pedra."],"cap":["Tamanhos de tabuleiro comparados: o de 14 × 17 (238 casas) descrito no relato da viagem de Cook, e os de 10 × 10, 8 × 8 e 6 × 6 que se jogam neste Atlas"]},{"h":"Um jogo que os matemáticos encontraram","p":["No kōnane perde quem não consegue jogar, e no fim o tabuleiro se divide em partes independentes: encaixa perfeitamente na teoria dos jogos combinatórios de Elwyn Berlekamp e colegas. Michael Ernst escreveu com Berlekamp um breve artigo sobre o kōnane em 1993 e, num artigo de 1995, calculou os valores de muitas posições.","Vieram outros: Alice Chan e Alice Tsai estudaram o kōnane de uma só fileira (2002), e Bob Hearn mostrou que, em tabuleiros cada vez maiores, decidir quem vence se torna extremamente difícil (PSPACE-completo). Um jogo de pedras que saltam virou tema da teoria da computação."],"cap":[]}],"tl":[["1778","Os navios de Cook chegam ao Havaí"],["1784","Publica-se o relato da terceira viagem de Cook, com a descrição do jogo de pedras por King"],["1993","Ernst e Berlekamp escrevem um breve artigo sobre o kōnane"],["1995","Artigo de Ernst «Playing Konane Mathematically»"],["2002","Chan e Tsai resumem seus resultados sobre o kōnane de uma fileira"]]},"peg":{"title":"O quebra-cabeça de saltos nascido numa corte real","lead":"O Resta Um era jogado no fim do século XVII na corte francesa de Luís XIV. Um quebra-cabeça simples, de tirar pinos um a um, que fascina os matemáticos desde então.","s":["O Resta Um é um quebra-cabeça para uma pessoa só. Os pinos enchem os furos do tabuleiro, e só um furo fica vazio.","Um pino salta sobre um vizinho, na horizontal ou na vertical, até o furo vazio logo depois. O pino saltado sai do tabuleiro.","O objetivo é continuar saltando até restar um só pino. Deixá-lo bem no centro é o final perfeito.","Os primeiros registros firmes vêm da França do fim do século XVII, da corte de Luís XIV. Em 1697 a revista Mercure galant publicou o tabuleiro e as regras, e uma gravura mostra uma dama com um tabuleiro ao lado.","Parece fácil, mas é difícil. O matemático Leibniz se interessou por ele, e no século XX matemáticos explicaram, colorindo os furos, por que alguns problemas não têm solução."],"quiz":[["O que acontece com o pino que é saltado?","Sai do tabuleiro","Passa para o adversário","Desliza para o furo ao lado","Volta na próxima vez"],["Quantos furos tem o tabuleiro inglês?","33","37","45","64"],["De onde vêm os primeiros registros firmes do Resta Um?","Da corte francesa de Luís XIV, no fim do século XVII","Das termas da Roma antiga","De uma escola de templo do Japão Edo","De um saloon da América do século XIX"]],"kf":["Quebra-cabeça de saltos para uma pessoa: salta-se para tirar pinos e vence-se deixando um só","Os registros firmes começam por volta de 1697 na corte de Luís XIV; os tabuleiros clássicos têm 33 (inglês) e 37 (europeu) furos","Pintar os furos com três cores mostra de antemão quais problemas não têm solução"],"more":[{"h":"Saltar e tirar","p":["Só se salta na horizontal ou na vertical, nunca na diagonal (a não ser em tabuleiros com linhas diagonais, como o triangular). Cada salto tira um pino, então começando com 32 são precisos 31 saltos para ficar com um.","O mesmo pino pode saltar várias vezes seguidas. Contando essa sequência como um lance, o problema de centro a centro do tabuleiro inglês se resolve em 18 lances. Ernest Bergholt achou essa solução em 1912, e em 1964 John Beasley provou que não dá para fazer em menos."],"cap":["O primeiro lance no tabuleiro inglês. Com o centro vazio, o pino de cima salta sobre o de baixo até o centro (azul); o pino saltado sai (×)"]},{"h":"Um passatempo da corte","p":["A história segura do Resta Um remonta à corte de Luís XIV por volta de 1697. Em agosto daquele ano, a revista Mercure galant descreveu o tabuleiro, as regras e alguns problemas, e o gravador Claude-Auguste Berey retratou a princesa de Soubise com um tabuleiro ao lado.","Também é famosa a história de um nobre preso na Bastilha que o teria inventado para passar o tempo, mas é uma lenda que não pode ser confirmada. Diz-se que o tabuleiro de 37 furos usado na França também existe desde o século XVII, enquanto o de 33, de cantos cortados, é chamado de tabuleiro inglês."],"cap":["Os dois tabuleiros clássicos: inglês, com 33 furos (à esquerda), e europeu, com 37 (à direita). O furo vazio é o início habitual de cada um"]},{"h":"O que três cores revelam","p":["Pinte os furos com três cores de modo que as cores sigam as diagonais. Assim, três furos seguidos, na horizontal ou na vertical, são sempre de três cores diferentes. Um salto tira um pino de duas cores e acrescenta um à terceira, então as contagens das três cores mudam juntas de par para ímpar.","No tabuleiro europeu com o centro vazio, cada cor tem 12 pinos: todas pares. Cada salto só alterna entre «todas pares» e «todas ímpares», de modo que nunca se chega à posição de um último pino — uma cor com 1 e as outras duas com 0. Neste tabuleiro, o problema que começa no centro não tem solução. A mesma verificação no tabuleiro inglês reduz a apenas cinco os furos onde o último pino pode terminar, começando do centro."],"cap":["O tabuleiro europeu de 37 furos pintado com três cores ao longo das diagonais. Com o centro vazio, cada cor tem 12 pinos"]},{"h":"Um brinquedo de matemáticos","p":["Conta-se que Leibniz escreveu, numa nota de 1710, que gostava de jogá-lo ao contrário, preenchendo os furos que tinham sido saltados. Trabalhar de trás para a frente, a partir do fim, ainda é um modo básico de resolvê-lo.","Winning Ways (1982), de Berlekamp, Conway e Guy, analisou o quebra-cabeça a fundo e apresentou as «funções pagode»: dando a cada furo uma pontuação tal que nenhum salto aumente o total, é possível provar que certos objetivos são impossíveis. Diz-se que em 1999 uma busca por computador examinou todas as posições."],"cap":[]}],"tl":[["1697","Jogado na corte de Luís XIV; o Mercure galant de agosto publica o tabuleiro e as regras"],["1710","Diz-se que Leibniz escreve sobre jogá-lo ao contrário"],["1912","Bergholt acha uma solução de 18 lances no tabuleiro inglês"],["1964","Beasley prova que não há solução com menos de 18 lances"],["1982","Winning Ways reúne sua análise, com as funções pagode"]]},"fanorona":{"title":"Capturar aproximando-se, capturar afastando-se","lead":"O fanorona é o jogo nacional de Madagáscar. Diz a lenda que decidiu um trono — e no século XXI os computadores mostraram que, com jogo perfeito, termina empatado.","s":["O fanorona é um jogo para dois muito popular em Madagáscar. Usa um tabuleiro de 9 × 5 riscado com linhas horizontais, verticais e diagonais, e 22 peças de cada lado.","O tabuleiro parece dois tabuleiros de alquerque — um jogo do mundo árabe e da Europa — lado a lado. Acredita-se que o alquerque chegou à ilha e ali virou um jogo próprio.","Sua grande marca é o modo de capturar. Mover-se em direção a uma peça adversária («aproximação») ou afastar-se dela («afastamento») captura toda a fileira de peças adversárias naquela linha.","Capturar é obrigatório, e a peça que capturou pode mudar de direção e continuar capturando. Um só turno pode transformar o tabuleiro: essa é a graça do fanorona.","Querido há séculos, tem até a lenda de um príncipe que perdeu um trono por não conseguir largar uma partida. Em 2007, pesquisadores holandeses mostraram por computador que, com o melhor jogo dos dois lados, o resultado é empate."],"quiz":[["Qual é o tamanho do tabuleiro de fanorona?","9 × 5","8 × 8","7 × 7","6 × 6"],["Quais são as duas formas de capturar no fanorona?","Aproximação e afastamento","Saltar e cercar","Rodear e empurrar","Dados e sorteio"],["O que os computadores mostraram com o melhor jogo?","Empate","Vitória do primeiro jogador","Vitória do segundo jogador","Ainda não se sabe nada"]],"kf":["Jogo para dois de Madagáscar: 22 peças cada num tabuleiro de 9 × 5, só o centro vazio no início","Aproximar-se de uma peça adversária ou afastar-se dela captura a fileira inteira naquela linha","Em 2007 os computadores mostraram que, com o melhor jogo, é empate"],"more":[{"h":"Aproximação e afastamento","p":["Na aproximação, se logo depois do ponto de chegada houver uma peça adversária, capturam-se essa peça e todas as adversárias enfileiradas atrás dela sem intervalo. O afastamento é o inverso: capturam-se a peça adversária que estava logo atrás do ponto de partida e as enfileiradas atrás dela.","Como um único passo pode remover várias peças, os exércitos encolhem rápido desde o início. Quando um lance permite aproximação e afastamento ao mesmo tempo, o jogador escolhe um."],"cap":["As duas capturas. Em cima: o branco avança um passo para a direita, aproxima-se de uma peça preta e captura as três pretas em fila (aproximação). Embaixo: o branco avança para a direita, afastando-se de uma preta, e captura as duas pretas atrás (afastamento)"]},{"h":"Dois tabuleiros de alquerque lado a lado","p":["O tabuleiro tem 5 × 9 = 45 pontos; além das linhas horizontais e verticais, diagonais passam por um ponto sim, outro não. As peças andam um passo ao longo de uma linha até um ponto vizinho. No início só o centro está vazio, então o primeiro lance é sempre uma captura.","O tabuleiro são dois tabuleiros de alquerque de 5 × 5 unidos. O alquerque é um jogo antigo já citado num livro árabe do século X, e acredita-se que o fanorona surgiu dele. Não se sabe quando nem como chegou à ilha; alguns livros falam do século XVII."],"cap":["A posição inicial: 22 peças pretas e 22 brancas nos 9 × 5 pontos, só o ponto central vazio. Os quadrados tracejados marcam dois tabuleiros de alquerque de 5 × 5"]},{"h":"Cadeias de capturas","p":["Uma peça que capturou pode capturar de novo. Mas cada passo deve ir numa direção diferente, e ela não pode voltar a um ponto já visitado. Continuar ou não é escolha do jogador.","Quando a cadeia dá certo, um só turno pode levar quase metade das peças adversárias. Mas, se ela termina num lugar ruim, a peça é logo recapturada."],"cap":["Uma cadeia de capturas. O branco (1) aproxima-se para a direita e captura duas; (2) afasta-se para cima e captura duas; (3) aproxima-se para a esquerda e captura duas. Depois de (1) não pode seguir para a direita (×)"]},{"h":"Um trono e os computadores","p":["Diz a lenda que Ralambo, rei de Imerina por volta do século XVI, fingiu-se doente para que herdasse o trono o primeiro filho a voltar. O mais velho, Andriantompokoindrindra, não conseguiu largar uma difícil posição de fanorona, e o mais novo, Andrianjaka, tornou-se rei. Outra história diz que, na invasão francesa de 1895, o lado da rainha confiou numa partida ritual de fanorona; nenhum dos relatos pode ser confirmado.","Em 2007, Maarten Schadd e colegas da Universidade de Maastricht, na Holanda, calcularam todas as posições com sete peças ou menos e, com a busca por números de prova, mostraram que a posição inicial é empate (o artigo saiu em 2008). O cálculo levou mais de uma semana numa única máquina."],"cap":[]}],"tl":[["c. séc. XVI","A lenda da sucessão do rei Ralambo e o fanorona"],["c. séc. XVII","Uma opinião sobre quando o fanorona surgiu do alquerque"],["1895","A lenda de uma partida ritual de fanorona durante a invasão francesa"],["2007","Schadd e colegas mostram por computador que é empate"],["2008","O artigo «Best Play in Fanorona Leads to Draw»"]]},"janggi":{"title":"Um tabuleiro sem rio e um canhão que salta uma só vez","lead":"O janggi, muito querido na Coreia, usa o mesmo tabuleiro de 9 × 10 do xiangqi chinês — mas tirou o rio e mudou o movimento das peças.","s":["O janggi é um jogo de xadrez para dois jogado há muito tempo na Coreia. Acredita-se que venha do xiangqi chinês, e suas peças ficam nos pontos de uma grade de 9 × 10 linhas.","Ao contrário do xiangqi, o tabuleiro não tem «rio» no meio, então elefantes e soldados podem ir a qualquer parte. O general (rei) começa no centro do seu «palácio» e nunca pode sair dele.","Os lados são Cho (azul ou verde) e Han (vermelho). As peças são octogonais, e quanto mais forte a peça, maior ela é. Cho joga primeiro.","Antes da partida, cada lado escolhe uma de quatro formas de colocar cavalos e elefantes. Han arma primeiro e Cho decide depois de ver, então a disputa começa antes do primeiro lance.","Além do xeque-mate, a partida pode ser decidida por pontos. Cho, que começa, parte de 72 pontos; Han recebe um «deom» de 1,5 e parte de 73,5. Cada peça perdida diminui a pontuação."],"quiz":[["O que o tabuleiro de janggi não tem?","Um rio no meio","Palácios","Diagonais nos palácios","90 pontos"],["O que o canhão sempre precisa fazer para se mover?","Saltar exatamente uma peça","Estar ao lado de uma peça adversária","Estar dentro de um palácio","Não estar em xeque"],["Na contagem de pontos, quanto de «deom» recebe Han, o segundo jogador?","1,5","0,5","3","6,5"]],"kf":["O xadrez da Coreia, nascido do xiangqi: tabuleiro de 9 × 10, mas sem rio","O elefante anda um reto e dois na diagonal; o canhão se move e captura saltando exatamente uma peça","Cada lado escolhe uma de quatro arrumações de cavalos e elefantes; na contagem, Han recebe um deom de 1,5"],"more":[{"h":"Um tabuleiro sem rio e quatro arrumações","p":["O tabuleiro de janggi tem os mesmos 9 × 10 pontos do xiangqi, mas sem rio no meio. Cada palácio tem diagonais em X, e o general e os guardas andam um passo de cada vez lá dentro, também pelas diagonais. O general começa bem no centro do seu palácio.","Há quatro arrumações, que surgem ao trocar cavalos e elefantes de lugar. Han arma primeiro, e Cho escolhe depois de ver. Pôr os elefantes por dentro ou por fora muda as linhas de ataque da abertura."],"cap":["O tabuleiro de janggi e a posição inicial. Não há rio, e os palácios de cima e de baixo têm diagonais. Os círculos tracejados marcam onde cavalos e elefantes podem trocar de lugar; Han (em cima) e Cho (embaixo) escolheram arrumações diferentes"]},{"h":"Cavalo, elefante e pontos bloqueados","p":["O cavalo anda primeiro um ponto em linha reta e depois um na diagonal para fora. O elefante vai mais longe: um ponto reto e depois dois na diagonal. Para os dois, uma peça num ponto do caminho bloqueia essa direção.","O elefante do xiangqi não pode cruzar o rio e só anda dois pontos na diagonal, mas o do janggi tem pernas longas e percorre todo o tabuleiro. Em troca, seu caminho é facilmente bloqueado."],"cap":["O cavalo (à esquerda) anda um reto e um na diagonal; o elefante (à direita), um reto e dois na diagonal. Os pontos azuis mostram aonde podem ir. Uma peça num ponto do caminho bloqueia essa direção (×)"]},{"h":"O canhão que salta uma só vez","p":["O canhão precisa saltar exatamente uma peça no meio, tanto para se mover quanto para capturar. Sem nada no meio, não se move, então na posição inicial os canhões ficam parados.","Nem a peça saltada nem a capturada podem ser um canhão, por isso dois canhões só podem se encarar. Comparado ao canhão do xiangqi, que anda livremente quando não captura, é uma peça bem mais exigente."],"cap":["O canhão. Em cima: salta exatamente um soldado e vai a um ponto além, ou captura o carro (azul). No meio: não pode saltar se a peça do meio for um canhão. Embaixo: canhão não captura canhão (×)"]},{"h":"Generais frente a frente e pontos","p":["Quando os dois generais ficam frente a frente numa linha sem nada no meio, isso se chama «bikjang». Por uma regra, se o lado confrontado não desfizer a situação, a partida é empate. As regras tradicionais também permitem passar a vez quando não se está em xeque.","Os valores são carro 13, canhão 7, cavalo 5, elefante 3, guarda 3 e soldado 2. Cho soma 72 pontos, e Han 73,5 com o deom. Por causa do meio ponto, nunca há empate na contagem. No janggi deste Atlas, esses pontos decidem a partida quando uma posição se repete três vezes ou após 200 lances."],"cap":[]}],"tl":[["Período Goryeo","Uma opinião diz que já se jogava (a época de chegada é discutida)"],["séc. XVIII","Diz-se que há registro de uma variante maior, o gwangsanghui"],["1895","Korean Games, de Stewart Culin, traz um desenho de homens jogando janggi"],["2009","Diz-se que o primeiro torneio internacional foi em Harbin, na China"]]},"pic":{"tlvmirror":"Espelho TLV (Han Oriental, Museu de Arte de Cleveland)","kotoboard":"As quatro artes (período Edo, c. 1620-1650, Museu de Arte de Cleveland)","homerbg":"Winslow Homer, Gamão (gravura em madeira, c. 1877, Museu de Arte de Cleveland)","trictrac":"Philips de Koninck, Os jogadores de tric-trac (desenho, c. 1660, Museu de Arte de Cleveland)","gametable":"Mesa de jogo com tabuleiros de xadrez e trilha (Mainz, c. 1735, Museu de Arte de Cleveland)","kota":"O soberano de Kota adora Krishna; nos degraus, um pano de chaupar em cruz (c. 1825, Museu de Arte de Cleveland)"},"mahjong":{"game":"Mahjong","title":"O jogo de peças com nome de pardal","lead":"O mahjong nasceu na China do século XIX. Um jogo de cartas virou peças, virou febre nos Estados Unidos dos anos 1920 e, no Japão, tornou-se o riichi mahjong.","s":["O mahjong é um jogo de peças para quatro pessoas. Usa 136 peças (144 com as flores), e vence quem primeiro completa uma mão de forma determinada.","Nasceu na China do século XIX. Suas raízes são jogos de «comprar e descartar» com cartas que mostravam unidades de dinheiro, e acredita-se que por volta de meados do século as cartas de papel viraram peças.","As peças mais antigas que restam são de cerca de 1870 e foram obtidas em Ningbo, Xangai e Fuzhou. Alguns livros dizem que nasceu em Ningbo; outros, que começou como passatempo de pescadores de Fujian e Cantão.","«Máquè» quer dizer pardal, e uma teoria liga o nome a um jogo de cartas mais antigo, o madiao. A história tão repetida de que Confúcio o inventou não tem nenhum fundamento.","No século XX o mahjong cruzou os mares. Virou febre nos Estados Unidos dos anos 1920, e no Japão a regra posterior do «riichi» o transformou num jogo próprio."],"quiz":[["Sem as flores, quantas peças tem o mahjong?","136","144","108","152"],["Qual é a forma básica de uma mão vencedora?","Quatro grupos e um par","Só sete grupos","Treze peças iguais","Três grupos e dois pares"],["Em que país o mahjong virou febre nos anos 1920?","Estados Unidos","Rússia","Brasil","Egito"]],"kf":["Um jogo de peças para quatro nascido de jogos de cartas na China do século XIX","Peças numeradas de caracteres, círculos e bambus, mais ventos e dragões; vence-se com quatro grupos e um par","Febre nos EUA dos anos 1920; no Japão do pós-guerra cresceu o riichi mahjong"],"more":[{"h":"136 peças","p":["As peças numeradas formam três naipes — caracteres, círculos e bambus —, cada um de 1 a 9 com quatro cópias: 108 peças. Somando quatro de cada vento (leste, sul, oeste e norte) e de cada dragão (branco, verde e vermelho), chega-se a 136.","Muitas formas chinesas de jogar usam também oito flores: ameixeira, orquídea, crisântemo e bambu, e as quatro estações. Elas não entram na mão; quando compradas, ficam de lado e somam pontos. O mahjong japonês costuma dispensá-las."],"cap":["Os tipos de peças. Caracteres, círculos e bambus de 1 a 9, os ventos (leste, sul, oeste, norte) e os dragões (branco, verde, vermelho), quatro de cada: 136. Com as oito flores abaixo da linha pontilhada (uma de cada): 144"]},{"h":"Quatro grupos e um par","p":["A mão tem 13 peças; compra-se uma e descarta-se uma, de novo e de novo. Quando uma peça comprada, ou descartada por outro, completa quatro grupos e um par, a mão vence.","Os grupos são o chow (três números em sequência de um naipe), o pung (três peças iguais) e o kong (quatro iguais). Também dá para formá-los pegando o descarte de outro jogador, então a partida é uma longa disputa para decidir o que pegar e o que largar."],"cap":["A forma básica de uma mão vencedora: quatro grupos — chow (três em sequência do mesmo naipe), pung (três iguais) ou kong (quatro iguais) — e um par"]},{"h":"O mahjong cruza os mares","p":["Em 1920 Joseph Park Babcock publicou um livro de regras em inglês, e uma loja de Nova York passou a importar jogos da China. O mahjong virou febre nos EUA dos anos 1920, e a National Mah Jongg League, fundada em 1937, mantém viva uma forma americana de jogar.","Chegou ao Japão nos anos 1920; diz-se que em 1924 Saburo Hirayama abriu um salão e uma escola em Tóquio, e em 1929 foi fundada a Liga Japonesa de Mahjong, presidida pelo escritor Kan Kikuchi. Em 1952, no pós-guerra, diz-se que Daizō Amano publicou num jornal regras com «riichi», e daí se espalhou o riichi mahjong japonês."],"cap":["Como o mahjong se espalhou: da China para os EUA e o Japão nos anos 1920; regras do riichi no Japão em 1952 e regras oficiais chinesas em 1998"]},{"h":"Lendas e história real","p":["O mahjong tem muitas lendas de origem. A de que Confúcio o criou não tem base. A de um homem de Ningbo chamado Chen Yumen que o teria inventado provavelmente também é falsa, pois os papéis de onde ela viria nunca foram encontrados.","O que é certo é que jogos chineses do século XIX de comprar e descartar com cartas de dinheiro viraram um jogo de peças. Os primeiros jogos não tinham flores nem dragão verde, mas peças de «rei» e outras. Em 1998 a China também fixou regras oficiais nacionais."],"cap":[]}],"tl":[["meados do séc. XIX","Acredita-se que jogos de cartas viram jogo de peças"],["c. 1870","Os jogos mais antigos conservados (Ningbo, Xangai, Fuzhou)"],["1920","Babcock publica um livro de regras em inglês"],["1929","Fundada a Liga Japonesa de Mahjong"],["1952","Publicadas as «regras Hochi» com riichi"],["1998","A China fixa regras oficiais nacionais"]],"figL":{"hand":["Chow","Pung","Kong","Chow","Par"],"spread":[["c. 1870","Ningbo, Xangai","Peças mais antigas"],["1920","Estados Unidos","Regras de Babcock, febre"],["1920s","Japão","Chega; liga em 1929"],["1952","Japão","Regras do riichi"],["1998","China","Regras oficiais, 81 padrões"]]}},"gomoku":{"title":"Gomoku: quando o primeiro jogador era forte demais","lead":"O gomoku, jogado com tabuleiro e pedras de go, é querido no Japão desde o período Edo. Para conter a vantagem do primeiro jogador nasceram as regras do «renju» — e, no fim, os computadores deram a resposta.","s":["O gomoku é um jogo para dois com tabuleiro e pedras de go. Pretas e brancas colocam pedras alternadamente, e vence quem primeiro alinhar cinco das suas na horizontal, na vertical ou na diagonal.","Sua origem não é clara. Há quem a leve à China antiga ou ao Japão de Heian, mas os registros firmes são do período Edo, e diz-se que já era jogado em meados do século XVIII.","Quanto mais se jogava, mais claro ficava que as pretas, que começam, tinham vantagem. Por isso, no Japão, foram criadas aos poucos regras que impunham «lances proibidos» só às pretas.","Em 1899, Ruikō Kuroiwa, do jornal Yorozu chōhō, deu ao jogo o nome de «renju», que quer dizer «pérolas enfileiradas».","Em 1988 foi fundada em Estocolmo, na Suécia, a Federação Internacional de Renju (RIF), e há campeonatos mundiais. Enquanto isso, os computadores mostraram que o gomoku sem lances proibidos é vitória do primeiro jogador."],"quiz":[["Como se vence no gomoku?","Alinhando cinco pedras suas","Cercando e capturando pedras","Dominando mais da metade do tabuleiro","Capturando cinco pedras adversárias"],["Quem deu ao jogo o nome de «renju»?","Ruikō Kuroiwa","Honinbō Dōsaku","Natsume Sōseki","Fukuzawa Yukichi"],["No renju, que lances são proibidos só às pretas?","Duplo três, duplo quatro e linha longa","Jogar na borda do tabuleiro","Jogar ao lado de uma pedra branca","Cercar pedras adversárias"]],"kf":["Um jogo com tabuleiro e pedras de go: cinco em linha vencem; os registros firmes começam no período Edo","Como as pretas começam em vantagem, o renju lhes proíbe o duplo três, o duplo quatro e a linha longa","Em 1994 provou-se que o gomoku livre em 15 × 15 é vitória do primeiro jogador"],"more":[{"h":"Cinco em linha e o quatro-três","p":["As partidas se decidem com uma ameaça dupla que o adversário não consegue bloquear de uma vez. Um «quatro» — a uma pedra de cinco — precisa ser bloqueado na hora, senão perde. Um «três» aberto nas duas pontas, se ignorado, vira um quatro aberto impossível de deter.","Um lance que cria ao mesmo tempo um quatro e um três — um «quatro-três» — obriga as brancas a tapar o quatro, e depois o três cresce e vence. Melhorar no gomoku é enxergar essa forma cada vez mais cedo."],"cap":["À esquerda: cinco na diagonal vencem. À direita: a pedra no anel vermelho forma ao mesmo tempo um «quatro» na horizontal (jogar em 4 faz cinco) e um «três» aberto na vertical (os pontos 3): as brancas não conseguem barrar os dois (quatro-três)"]},{"h":"Lances proibidos só às pretas","p":["No renju as pretas não podem fazer duplo três, duplo quatro nem linha longa (seis ou mais em fila); fazê-lo é falta, e perdem. As brancas não têm lances proibidos, e até seis ou mais em fila lhes dão a vitória.","Para vencer, as pretas precisam construir formas como o quatro-três que não sejam proibidas. As brancas podem até empurrar as pretas de propósito para um lance proibido — um duelo de esperteza que dá profundidade ao renju."],"cap":["Lances proibidos às pretas no renju (×). Da esquerda: o «duplo três» (dois três de uma vez), o «duplo quatro» (dois quatro de uma vez) e a «linha longa» (seis ou mais)"]},{"h":"O gomoku resolvido","p":["Em 1994 o holandês Victor Allis provou por computador que, no gomoku livre num tabuleiro de 15 × 15, o primeiro jogador, as pretas, sempre pode vencer. Em 2001 Wágner e Virág mostraram que o renju sem regras de abertura também é vitória do primeiro jogador.","As pessoas continuam jogando porque as linhas vencedoras são complexas demais para decorar. Os torneios usam «regras de abertura» que definem como se jogam os primeiros lances — como Yamaguchi ou Soosõrv-8 — para que a disputa seja justa."],"cap":["A história do gomoku e do renju: do gomoku do período Edo ao nome renju, à federação internacional e às provas por computador"]},{"h":"Cinco em linha pelo mundo","p":["No século XIX o jogo chegou à Grã-Bretanha como «Go Bang». Hoje jogos parecidos são jogados no mundo todo: o omok da Coreia, o caro do Vietnã e o pente, em que se capturam pedras aos pares.","O gomoku deste Atlas é jogado num tabuleiro de 15 × 15, com três regras à escolha: renju, padrão e livre. Compare-as e veja quanto os lances proibidos do renju freiam o primeiro jogador."],"cap":[]}],"tl":[["meados do séc. XVIII","Diz-se que se joga gomoku no Japão de Edo"],["1856","O livro de gomoku mais antigo conservado, o Gomoku Jōseki"],["1899","Ruikō Kuroiwa chama o jogo de renju"],["1988","Fundada em Estocolmo a Federação Internacional de Renju"],["1994","Allis prova que o gomoku livre é vitória do primeiro jogador"],["2001","Wágner e Virág mostram que o renju sem regras de abertura é vitória do primeiro"]],"figL":{"time":[["1700s","Japão (Edo)","Joga-se gomoku"],["1899","Japão","Chamado «renju»"],["1988","Estocolmo","Nasce a RIF"],["1994","Holanda","Gomoku: o 1º vence"],["2001","Hungria","Renju: pretas vencem"]]}},"carrom":{"title":"Carrom: um peteleco até a caçapa","lead":"Na Índia e no sul da Ásia, famílias e vizinhos se reúnem para jogar carrom. As peças, impulsionadas com um dedo, vão parar nas caçapas dos quatro cantos do tabuleiro — um jogo parecido com a sinuca.","s":["O carrom é jogado num tabuleiro liso de cerca de 74 centímetros de lado. Há uma caçapa em cada canto; jogam dois frente a frente, ou quatro em duplas.","São 19 peças: 9 brancas, 9 pretas e uma «rainha» vermelha. Na sua vez, você coloca o «striker», maior e mais pesado, na linha à sua frente — a linha de base — e o impulsiona com um peteleco contra as peças.","Vence quem encaçapa todas as peças da sua cor. Mas a rainha vermelha só é sua se, depois de encaçapá-la, você encaçapar em seguida uma peça sua para «cobri-la».","Diz-se que o carrom nasceu na Índia; num palácio de Patiala, no norte do país, ainda se exibe um tabuleiro de superfície de vidro. No início do século XX já havia torneios estaduais na Índia.","Em 1988 foi fundada em Chennai, na Índia, a Federação Internacional de Carrom, e desde 1991 há campeonatos mundiais. Jogos de peteleco parecidos existem pelo mundo todo, como o crokinole do Canadá e o novuss da Letônia."],"quiz":[["Sem contar o striker, quantas peças tem o carrom?","19","16","24","32"],["Como a rainha vermelha passa a ser sua?","Encaçapando em seguida uma peça sua (cobrindo)","Encaçapando-a por último","Encaçapando-a na primeira tacada","Acertando-a duas vezes seguidas"],["Em que cidade foi fundada em 1988 a Federação Internacional de Carrom?","Chennai","Londres","Colombo","Mumbai"]],"kf":["Um tabuleiro com caçapas nos cantos: com um peteleco no striker, encaçapam-se as peças","9 brancas, 9 pretas e uma rainha vermelha; a rainha precisa ser «coberta» com uma peça sua em seguida","Diz-se que nasceu na Índia; Federação Internacional em 1988, campeonatos mundiais desde 1991"],"more":[{"h":"O tabuleiro e suas 19 peças","p":["Cada canto do tabuleiro tem uma caçapa com rede, e em cada lado há uma linha de base dupla. O striker é colocado tocando as duas linhas e impulsionado dali.","No início, a rainha vai no centro do tabuleiro e as peças brancas e pretas a rodeiam em forma de flor. A primeira tacada, que desfaz a flor, é a «saída» que abre a partida."],"cap":["O tabuleiro de carrom e a posição inicial. A rainha vermelha no centro, as peças brancas e pretas ao redor como uma flor. Caçapas nos cantos, uma linha de base dupla em cada lado; o striker (anel azul) fica na linha de base mais próxima"]},{"h":"Peteleco e tabela","p":["O striker costuma ser impulsionado com a unha; há quem use o dedo médio, o indicador ou o polegar. Se encaçapar uma peça sua, joga de novo; se não, é a vez do adversário.","As tabelas rebatem bem, então se usam as tabelas como na sinuca. Encaçapar o próprio striker é falta e tem punição."],"cap":["O striker é impulsionado (azul), bate na tabela direita e acerta uma peça branca, que entra na caçapa do canto superior direito (vermelho). Uma peça que não dá para mirar direto pode ser alcançada pela tabela"]},{"h":"Uma família de jogos de peteleco","p":["Há jogos de peteleco como o carrom no mundo todo. O crokinole do Canadá mira num buraco no centro de um tabuleiro redondo, e o pichenotte também é jogado há muito tempo no Canadá. Diz-se que o próprio carrom chegou à América do Norte no fim do século XIX com missionários que voltavam da Ásia.","Diz-se que o novuss da Letônia e da Estônia surgiu nos anos 1920; joga-se com um tacinho em vez do dedo. Virou um dos esportes mais populares da Letônia, e desde 1993 há campeonatos internacionais."],"cap":["Primos do carrom jogados com o dedo ou com um taco: o crokinole e o pichenotte do Canadá, o novuss da Letônia e da Estônia e o couronne da Escandinávia"]},{"h":"Pontos e campeonatos mundiais","p":["Pelas regras internacionais, cobrir a rainha soma 3 pontos, e vence quem chega primeiro a 25. Em família há muitas variantes locais, como valer 5 pontos a rainha.","Diz-se que no Sri Lanka houve torneios sérios desde por volta de 1935, e em 1958 a Índia e o Sri Lanka já tinham federações oficiais. A Federação Internacional de Carrom (ICF) nasceu em Chennai em 1988, e os campeonatos mundiais acontecem desde 1991."],"cap":[]}],"tl":[["início do séc. XX","Torneios estaduais na Índia"],["c. 1935","Diz-se que começam torneios sérios no Sri Lanka"],["1958","Índia e Sri Lanka têm federações oficiais"],["1988","Fundada em Chennai a Federação Internacional de Carrom"],["1991","Primeiro Campeonato Mundial de Carrom"]],"figL":{"family":[["Carrom","Índia · sul da Ásia"],["Crokinole","Canadá"],["Pichenotte","Canadá"],["Novuss","Letônia · Estônia"],["Couronne","Suécia · Dinamarca"]]}},"crokinole":{"title":"Mirando no buraco do meio","lead":"O crokinole é muito querido no interior do Canadá. Discos são lançados com um peteleco sobre um tabuleiro redondo de madeira, mirando o pequeno buraco do meio. O tabuleiro mais antigo conhecido é de 1876.","s":["O crokinole é jogado num tabuleiro redondo de madeira com cerca de 66 centímetros de diâmetro. Dois jogam frente a frente, ou quatro em duplas, lançando seus discos com um peteleco em direção ao centro.","O tabuleiro tem círculos marcados: de fora para dentro, anéis de 5, 10 e 15 pontos, e no centro um pequeno buraco de 20. Oito pinos de madeira rodeiam o anel de 15 e bloqueiam o caminho direto.","Não basta mirar o centro. Se houver um disco adversário no tabuleiro, sua tacada precisa tocar um; se errar, seu disco é retirado.","O tabuleiro mais antigo conhecido foi feito em 1876, em Ontário, no Canadá, pelo artesão Eckhardt Wettlaufer — dizem que como presente pelos cinco anos do filho. Hoje está num museu em Kitchener.","Acredita-se que o nome venha do francês croquignole, «peteleco». Desde 1999 um campeonato mundial é realizado todo mês de junho em Tavistock, onde Wettlaufer viveu."],"quiz":[["Quantos pontos vale o buraco do centro do tabuleiro de crokinole?","20","15","10","50"],["Se houver um disco adversário no tabuleiro, o que sua tacada deve fazer?","Tocar um disco adversário","Entrar no buraco central","Sair do tabuleiro","Tocar um pino"],["Quando e onde foi feito o tabuleiro de crokinole mais antigo conhecido?","Canadá, 1876","França, 1776","Estados Unidos, 1926","Inglaterra, 1676"]],"kf":["Um tabuleiro redondo de madeira: lançam-se discos aos anéis de 5, 10 e 15 e ao buraco de 20 no centro","Se houver disco adversário no tabuleiro, é preciso tocá-lo; se errar, seu disco é retirado","O tabuleiro mais antigo: Ontário (Canadá), 1876; campeonato mundial desde 1999"],"more":[{"h":"Anéis, pinos e vala","p":["Os discos são lançados do anel externo de 5, dentro do seu próprio quarto. Além da borda corre uma vala, onde vão parar os discos que caem ou são retirados.","Um disco que cai no buraco de 20 é retirado na hora e vale 20. No fim, os discos que ficam no tabuleiro valem 5, 10 ou 15 conforme o anel, e em geral só se marca a diferença entre os dois lados."],"cap":["O tabuleiro de crokinole: anéis de 5, 10 e 15 de fora para dentro e o buraco de 20 no centro. Oito pinos guardam o anel de 15, e uma vala ao redor recolhe os discos retirados"]},{"h":"Tocar, ou ser retirado","p":["Se houver ao menos um disco adversário no tabuleiro, sua tacada precisa tocar um disco adversário, direta ou indiretamente. Se errar, saem o disco lançado e os seus discos movidos nessa tacada.","Quando não há disco adversário, muitas regras exigem que o disco lançado pare dentro do anel de 15 ou tocando sua linha. Assim ninguém pode simplesmente se esconder, e o jogo vira um duelo de ataque e defesa."],"cap":["A regra da tacada. À esquerda: com um disco adversário (preto) no tabuleiro, basta tocá-lo com seu disco (vermelho) (✓). À direita: se errar, seu disco sai do tabuleiro (×)"]},{"h":"De um tabuleiro de Ontário a um campeonato mundial","p":["Diz-se que o primeiro registro canadense remonta a 1867, e nos Estados Unidos Joshua K. Ingalls patenteou um jogo parecido em 1880. Também se apontam ligações com jogos de peteleco da Grã-Bretanha e do sul da Ásia, como o carrom.","Às vezes se diz que é um jogo de menonitas ou amish, mas isso é considerado um equívoco sem fundamento. Ainda assim, conta-se que menonitas de origem russa o jogavam com o nome de Knipsbrat, «tábua de peteleco»."],"cap":["O crokinole ao longo do tempo: do primeiro registro canadense ao tabuleiro de Wettlaufer, uma patente americana e o campeonato mundial de Tavistock"]},{"h":"Campeonatos e jogo","p":["O campeonato mundial acontece desde 1999 no primeiro sábado de junho em Tavistock. Em 2009 foi fundada uma associação internacional, e há clubes por toda a América do Norte e Europa.","O crokinole deste Atlas é só em 3D, com vários visuais de tabuleiro à escolha. Experimente o peteleco, como no carrom, e o prazer de mirar anéis, como nos dardos."],"cap":[]}],"tl":[["1867","Diz-se que é o primeiro registro canadense"],["1876","Wettlaufer faz um tabuleiro para o filho"],["1880","Nos EUA, Ingalls patenteia um jogo parecido"],["1999","Começa o campeonato mundial em Tavistock"],["2009","Fundada uma associação internacional"]],"figL":{"time":[["1867","Canadá","Primeiro registro"],["1876","Ontário","O tabuleiro mais antigo"],["1880","Estados Unidos","Patente de Ingalls"],["1999","Tavistock","Começa o mundial"],["2009","Internacional","Associação internacional"]]}},"ugolki":{"title":"Pula, pula, até o canto da frente","lead":"O ugolki russo, o halma americano e as «damas chinesas» do tabuleiro em estrela são uma só família: nada é capturado, salta-se por cima das peças até os dois exércitos trocarem de canto.","s":["Ugolki quer dizer «cantos» em russo. Brancas e pretas arrumam as peças em bloco em cantos opostos de um tabuleiro de 8×8, e vence quem primeiro levar todas as suas peças para o canto do outro.","Em cada lance, avança-se um passo para uma casa vizinha vazia, ou salta-se por cima de uma peça vizinha até a casa vazia logo atrás. Pode-se saltar peças próprias ou do adversário, e continuar saltando enquanto for possível. Nada é capturado: as peças saltadas ficam no tabuleiro.","O jogo mais conhecido desse tipo é o halma americano. Diz-se que foi criado por volta de 1883–84 pelo cirurgião George Howard Monks, a partir de algumas ideias de um jogo inglês chamado Hoppity. O nome vem do grego «salto».","Em 1892 surgiu na Alemanha uma versão em tabuleiro de estrela, o «Stern-Halma» (halma estrela). Em 1928 a empresa americana Pressman vendeu-o como «Chinese checkers» (damas chinesas), e virou febre; mas o jogo não tem nada a ver com a China.","Ninguém sabe ao certo quando o ugolki nasceu. Segundo um relato, teria sido inventado na Europa no fim do século XVIII, mas nenhum registro seguro foi encontrado. Hoje é jogado por crianças e adultos na Rússia e nos países da antiga União Soviética."],"quiz":[["No ugolki, o que acontece com uma peça saltada?","Fica no tabuleiro","É retirada","Muda de cor","Volta para o seu canto"],["Quando o jogo foi vendido pela primeira vez como «damas chinesas»?","Em 1928, nos EUA","Em 1892, na China","No século XVIII, na China Qing","Nos anos 1950, no Japão"],["Quem teria inventado o halma?","Monks, um cirurgião americano","Uma fábrica de brinquedos alemã","Um matemático russo","Um imperador chinês"]],"kf":["De canto a canto num tabuleiro de 8×8: vence quem levar tudo primeiro. Nada é capturado","Um passo, ou um salto sobre uma peça vizinha — sua ou do adversário —, e pode-se continuar saltando","Halma (EUA, c. 1883–84) → Stern-Halma (Alemanha, 1892) → «damas chinesas» (1928). Nada de chinês"],"more":[{"h":"Avançar saltando","p":["Ao saltar, não importa de quem é a peça. Alinhe as suas peças como uma «escada», use também as do adversário como degraus, e um só lance pode atravessar meio tabuleiro.","Saltar nunca é obrigatório, e pode-se parar no meio. Mas não se pode misturar um passo e um salto no mesmo lance."],"cap":["Uma cadeia de saltos: a peça branca salta uma preta, uma branca, uma preta e uma branca, quatro saltos num lance (1–4). Todas as peças saltadas continuam no tabuleiro"]},{"h":"O tabuleiro e os campos do ugolki","p":["Os campos têm vários tamanhos: 3×3 (9 peças), 3×4 (12) e 4×4 (16). Nas regras clássicas as peças só andam em linha reta, por fileiras e colunas; uma variante permite também a diagonal.","Se alguém ficar parado no próprio campo, o adversário nunca consegue preenchê-lo. Por isso uma regra muito usada na Rússia diz que perde quem ainda tiver uma peça no próprio campo depois do lance 40. Se nada se decidir até o lance 80, decide o número de peças no campo adversário."],"cap":["O tabuleiro do ugolki: as brancas partem do campo de 3×4 no canto inferior esquerdo (a1–d3), as pretas do superior direito (e6–h8), e cada lado segue para o canto do outro (setas). Os campos também podem ser de 3×3 ou 4×4"]},{"h":"A família do halma","p":["O halma é jogado num tabuleiro de 16×16, com 19 peças para cada um de dois jogadores ou 13 para cada um de quatro, que andam em oito direções. Monks obteve uma patente americana em 1888. Diz-se que o matemático Thomas Hill, mais tarde reitor de Harvard, lhe deu o nome.","O tabuleiro em estrela tem 121 furos; cada jogador costuma ter 10 peças, e jogam dois, três, quatro ou seis. Na China chama-se tiaoqi, «xadrez de saltos», e no Japão um jogo parecido é o «jogo do diamante». Aqui também, um adversário que fica no canto para onde você vai pode impedi-lo de preenchê-lo."],"cap":["A família dos jogos de saltar e trocar de canto: o halma num tabuleiro de 16×16, o Stern-Halma e as «damas chinesas» na estrela, o ugolki num tabuleiro de 8×8"]},{"h":"Experimente","p":["As regras do ugolki aprendem-se num minuto. Mas construir longas escadas também com as peças do adversário, sem lhe deixar degraus, rende uma profunda batalha de cálculo.","Neste Atlas você pode jogar ugolki com campos de 3×3, 3×4 ou 4×4, ou com movimentos na diagonal. O tabuleiro 3D é de porcelana branca e azul-cobalto, como a cerâmica russa de Gjel."],"cap":[]}],"tl":[["1883","Nasce o halma (c. 1883–84, EUA)"],["1888","Monks obtém uma patente americana do halma"],["1892","Stern-Halma em tabuleiro de estrela, na Alemanha"],["1928","Vendido como «damas chinesas» nos EUA"],["1941","A Milton Bradley obtém os direitos do nome"]],"figL":{"fam":[["c. 1883–84","Halma","EUA · tabuleiro 16×16"],["1892","Stern-Halma","Alemanha · tabuleiro em estrela"],["1928","Damas chinesas","um nome novo nos EUA"],["data incerta","Ugolki","Rússia · tabuleiro 8×8"]]}},"agon":{"title":"A rainha no trono, a guarda ao seu redor","lead":"O agon era jogado na Inglaterra vitoriana num tabuleiro de casas hexagonais. Sente sua rainha no trono do centro, cerque-a com seus seis guardas, e você venceu.","s":["O agon é um jogo para dois, também chamado «A guarda da rainha». O nome é a palavra grega para «competição». O tabuleiro tem 91 casas hexagonais, e a casa do centro é o trono.","Cinco anéis cercam o trono, cada um de uma cor diferente do seguinte. Cada jogador tem uma rainha e seis guardas; vence quem senta sua rainha no trono e ocupa com seus guardas as seis casas ao redor.","As peças andam uma casa por vez, pelo mesmo anel ou para o anel interior. Nunca podem ir para fora: depois de entrar, não há volta. Só uma rainha pode entrar no trono.","O registro mais antigo conhecido é um conjunto de regras publicado em Londres em 1842. O jogo é atribuído a Anthony Peacock, de Londres, e era apreciado nos lares vitorianos.","Costuma-se dizer que é o jogo de tabuleiro mais antigo conhecido com casas hexagonais. Um relato diz que nasceu na França do século XVIII, mas os tabuleiros antigos citados são considerados acréscimos posteriores, por isso não é certo."],"quiz":[["Como se vence no agon?","Rainha no trono, cercada pelos seus seis guardas","Capturando a rainha adversária","Alinhando todas as peças na borda","Cercando o trono vazio"],["Para onde uma peça do agon nunca pode ir?","Para um anel exterior","Pelo mesmo anel","Para o anel interior","Para o trono (se for rainha)"],["Quando e onde as regras do agon foram publicadas pela primeira vez?","Londres, 1842","Paris, 1742","Berlim, 1892","Nova York, 1942"]],"kf":["91 casas hexagonais: o trono no centro e cinco anéis ao redor","Um passo pelo mesmo anel ou para dentro, nunca para fora. Só a rainha ocupa o trono","Publicado em Londres em 1842; muitas vezes chamado o jogo hexagonal mais antigo"],"more":[{"h":"Um tabuleiro de trono e anéis","p":["Na saída padrão, rainhas e guardas dos dois jogadores alternam-se no anel exterior. Nas regras de 1842, as rainhas começavam em cantos opostos e os guardas eram colocados um a um, alternadamente.","O tabuleiro parece um alvo, com anéis coloridos ao redor do trono. Vê-se de relance em que anel está cada peça, o que facilita contar quantos passos faltam até o trono."],"cap":["O tabuleiro do agon e a posição inicial. A casa verde do centro é o trono, cercado por cinco anéis alternados vermelhos e marfim. A rainha (coroa) e os seis guardas de cada lado alternam-se na borda"]},{"h":"Para dentro, sempre para dentro","p":["Em cada vez, move-se uma peça um passo para uma casa vizinha vazia, ao redor do mesmo anel ou para dentro.","Não se pode entrar numa casa entre duas peças adversárias. Assim, um muro de peças inimigas é uma barreira real no caminho para o centro."],"cap":["O movimento. O guarda branco pode andar pelo seu anel ou para o anel interior (verde), mas não voltar para fora (× vermelho)"]},{"h":"Imprensado e mandado para fora","p":["Prenda uma peça adversária em linha reta entre duas suas e ela é capturada. O dono deve gastar a vez seguinte recolocando o guarda capturado numa casa vazia do anel exterior.","Uma rainha capturada volta para qualquer casa vazia exceto o trono, e é recolocada primeiro. Todos os passos conquistados se perdem, por isso a defesa importa muito. Os detalhes das regras variam um pouco de livro para livro."],"cap":["Captura. (1) O guarda branco avança e prende em linha o guarda preto entre duas peças brancas. (2) Na vez seguinte do dono, o guarda preto capturado vai para uma casa vazia da borda"]},{"h":"Experimente","p":["Se seus seis guardas cercarem o trono enquanto ele está vazio, você perde na hora. Mandar a rainha primeiro ou abrir caminho com os guardas? Planejar a ordem dos lances decide a partida.","Neste Atlas você pode jogar agon com a saída padrão na borda ou com a saída de 1842, colocando os guardas um a um. O tabuleiro 3D é de mogno vitoriano com filetes dourados, com peças de osso e ébano."],"cap":[]}],"tl":[["fim do séc. XVIII","Um relato fala de origem francesa (sem prova firme)"],["1842","Publicadas em Londres as regras de «Agon, or the Queen’s Guards»"],["século XIX","Popular na Inglaterra vitoriana; Jaques e outros vendem tabuleiros"],["1999","Descrito na Oxford History of Board Games de Parlett"],["hoje","Incluído no Ludii, um sistema de estudo de jogos"]]},"dots":{"title":"Pontos, traços e fichas que caem: jogos resolvidos","lead":"O jogo dos pontinhos, com lápis e papel, e o Lig 4, de deixar cair fichas: dois jogos que qualquer criança joga e que matemáticos e computadores resolveram a sério.","s":["O jogo dos pontinhos é jogado numa folha com uma grade de pontos. Cada jogador, na sua vez, liga dois pontos vizinhos com um traço; quem traça o quarto lado de um quadrado fica com essa caixa e joga de novo. Vence quem tiver mais caixas.","Quem apresentou o jogo como «La Pipopipette» foi o matemático francês Édouard Lucas, em 1889 segundo a maioria das fontes. Depois da sua morte, o jogo saiu também no livro L’Arithmétique amusante (1895).","O Lig 4 (Connect Four) é jogado deixando cair fichas num quadro vertical de 7 colunas e 6 linhas. A ficha cai até o buraco vazio mais baixo, e vence quem alinhar quatro da sua cor na horizontal, vertical ou diagonal. A empresa americana Milton Bradley lançou-o em 1974.","Em outubro de 1988, o Lig 4 foi «resolvido». No dia 1 James Dow Allen e no dia 16 Victor Allis, cada um por conta própria, mostraram que o primeiro jogador sempre vence se começar pela coluna do meio.","Também no jogo dos pontinhos, o matemático Elwyn Berlekamp e outros construíram uma teoria das «cadeias longas», reunida num livro em 2000. Por trás de um jogo que qualquer um joga havia matemática profunda."],"quiz":[["No jogo dos pontinhos, o que faz quem traça o quarto lado de uma caixa?","Fica com a caixa e joga de novo","Passa a vez","Dá a caixa ao adversário","A partida acaba"],["No Lig 4, qual primeiro lance garante a vitória do primeiro jogador?","A coluna do meio","A coluna da esquerda","A coluna da direita","Qualquer coluna"],["Quem resolveu o Lig 4 separadamente em 1988?","Allen e Allis","Lucas e Berlekamp","Wexler e Strongin","Conway e Guy"]],"kf":["Pontinhos: fechou a caixa, fica com ela e joga de novo. Quem abre a primeira cadeia longa costuma perder","Lig 4: 7 colunas × 6 linhas, as fichas caem até embaixo. À venda desde 1974","Resolvido por Allen e Allis separadamente em 1988: o primeiro vence pelo centro"],"more":[{"h":"Cadeias longas e cruz dupla","p":["Abrir uma «cadeia» de caixas ligadas deixa o adversário levar todas. Por isso o final é uma luta para ver quem será obrigado a abrir primeiro as cadeias longas. Quem abre a primeira cadeia longa costuma perder.","Quem leva uma cadeia pode deixar de propósito as duas últimas caixas para o adversário (a cruz dupla). Perde duas, mas obriga o adversário a abrir a cadeia seguinte, e as grandes cadeias restantes ficam para si."],"cap":["A disputa da cadeia longa. (1) B abre uma cadeia de cinco caixas. A fica com três e, em vez das duas últimas, traça a linha da ponta (2) e as entrega. (3) B fica com as duas com um só traço, mas tem de jogar de novo — e abrir a próxima cadeia"]},{"h":"Fichas que caem, linhas pares e ímpares","p":["Não se põe a ficha onde se quer: as colunas enchem de baixo para cima. Assim, um buraco vencedor não serve enquanto o de baixo estiver vazio — e quem preencher primeiro esse buraco dá a vitória ao outro.","À medida que o quadro enche, o número desses «buracos que ninguém quer preencher» decide a partida. Segundo a análise de Allis, ameaças em linhas ímpares seriam fortes para o primeiro jogador, e em linhas pares para o segundo."],"cap":["O quadro do Lig 4. A ficha que entra por cima cai até o buraco vazio mais baixo. O vermelho ameaça na terceira linha, uma linha ímpar (tracejado vermelho). Quem preencher o buraco abaixo (×) entrega a vitória ao vermelho"]},{"h":"Cronologia dos jogos resolvidos","p":["O Lig 4 é atribuído aos americanos Howard Wexler e Ned Strongin. Um jogo parecido também é chamado «a amante do capitão», por uma história de que o capitão Cook passava horas a jogá-lo na sua cabine — mas não se encontrou prova firme disso.","Pelas análises de Allen e Allis, o primeiro jogador que começa no meio vence no máximo no 41.º lance; começar numa coluna vizinha leva ao empate, e começar numa das quatro de fora deixa o segundo vencer. A teoria dos pontinhos foi exposta a fundo em Winning Ways (1982)."],"cap":["Passos rumo aos jogos resolvidos: a pipopipette de Lucas, o lançamento do Lig 4, o ano em que foi resolvido e o livro de Berlekamp"]},{"h":"Experimente","p":["Saber a resposta é uma coisa; jogar contra uma pessoa é outra bem diferente. Contar cadeias, contar linhas pares e ímpares, estar um passo à frente do adversário: a graça continua a mesma.","Este Atlas tem o jogo dos pontinhos e o Lig 4. Trace linhas num caderno ou numa lousa, deixe cair fichas num quadro de couro ou de gelo, e espie o que os matemáticos viram."],"cap":[]}],"tl":[["1889","Lucas apresenta «La Pipopipette» (segundo a maioria das fontes)"],["1974","A Milton Bradley lança o Lig 4"],["1982","Winning Ways analisa o jogo dos pontinhos"],["1988","Allen e Allis resolvem o Lig 4 separadamente"],["2000","The Dots and Boxes Game, de Berlekamp"]],"figL":{"time":[["1889","La Pipopipette","Lucas · França"],["1974","Lig 4","Milton Bradley"],["1988","Lig 4 resolvido","Allen e Allis · o primeiro vence"],["2000","O livro dos pontinhos","Berlekamp"]]}},"hitblow":{"title":"Descubra os quatro escondidos — a família do Hit & Blow","lead":"Adivinhar quatro cores ou algarismos escondidos tendo como pistas só «acertos» e «quase acertos». O jogo passou do lápis e papel para os pinos coloridos do Senha (Mastermind) e daí para a ciência da computação.","s":["No Hit & Blow, um jogador arruma em segredo quatro cores ou algarismos. A cada palpite do outro, diz-se apenas quantos acertam cor e lugar (hits, acertos) e quantos têm a cor certa no lugar errado (blows, quase acertos).","Vem de um jogo de números com lápis e papel, Touros e Vacas: os acertos são touros e os quase acertos, vacas. Às vezes diz-se que tem um século, mas sua origem real é desconhecida.","Em 1970, Mordecai Meirowitz, chefe dos correios e especialista em telecomunicações israelense, transformou-o num jogo de tabuleiro com pinos coloridos. A Invicta Plastics, perto de Leicester, na Inglaterra, comprou os direitos e lançou-o como Mastermind em 1971–72, e ele correu o mundo.","Na mesma época, também os computadores jogavam a adivinhar números. Antes de 1970 escreveu-se uma versão chamada MOO para o computador Titan da Universidade de Cambridge, e em 1972 ela foi levada ao Multics, no MIT, nos Estados Unidos.","Em 1976–77, o cientista da computação Donald Knuth mostrou que no Mastermind de 6 cores e 4 buracos (1.296 códigos ao todo), com os palpites certos sempre se acha o código em no máximo cinco tentativas."],"quiz":[["Quando uma cor do palpite está no mesmo lugar que no código, como se chama?","Acerto (hit)","Quase acerto (blow)","Erro","Par"],["Quem inventou o Mastermind com seus pinos coloridos?","Meirowitz, em Israel","Knuth, nos EUA","os correios britânicos","estudantes de Cambridge"],["Quantas tentativas, segundo Knuth, sempre bastam no Mastermind de 6 cores e 4 buracos?","No máximo cinco","No máximo três","No máximo oito","No máximo dez"]],"kf":["Acerto: cor e lugar certos; quase acerto: cor certa no lugar errado. Nunca se diz quais","Touros e Vacas no papel → pinos coloridos de Meirowitz em 1970 → Mastermind em 1971–72","Knuth (1976–77): os 1.296 códigos de 6 cores × 4 buracos acham-se em no máximo cinco tentativas"],"more":[{"h":"Acertos e quase acertos","p":["Os pinos nunca dizem quais lugares foram acertos, só que houve «um acerto e dois quase acertos». Por isso combinam-se as respostas de palpite em palpite para cercar o código.","Repetir um palpite não ensina nada. O comum é escolher uma combinação que combine com todas as respostas, mas às vezes um palpite que não pode ser o código reúne mais informação e encurta o caminho."],"cap":["Um palpite e sua resposta. Em cima, o código escondido; embaixo, o palpite. O da esquerda acerta cor e lugar: um acerto (pino rosa). O segundo e o quarto são cores do código em outro lugar: quase acertos (pinos brancos). O terceiro não está no código (×)"]},{"h":"Cada resposta encolhe o campo","p":["O método de Knuth escolhe a cada vez o palpite que deixa menos códigos mesmo que venha a pior resposta possível. Seu primeiro lance usa duas cores duas vezes cada.","Trabalhos posteriores acharam também o método de menor média: em 1993 Koyama e Lai mostraram cerca de 4,34 palpites em média (seis no pior caso). Touros e Vacas, com quatro algarismos diferentes, resolve-se sempre em sete palpites."],"cap":["Um código achado pelo método de Knuth. Os 1.296 códigos de 6 cores × 4 buracos caem para 256 após o primeiro palpite, 41 após o segundo, 6 após o terceiro e 1 após o quarto; o quinto acerta (barras em escala logarítmica)"]},{"h":"Dos números às cores","p":["O Mastermind ganhou muitos parentes, entre eles o Super Mastermind com 8 cores e 5 buracos (1972) e o Word Mastermind, em que se adivinham letras.","No Japão, o jogo de adivinhar números é conhecido como «Hit & Blow» e já apareceu na televisão e em coletâneas de jogos para consoles."],"cap":["A família no tempo: Touros e Vacas no papel, MOO no computador de Cambridge, o Mastermind de Meirowitz e o «cinco» de Knuth"]},{"h":"Experimente","p":["O melhor momento é quando, comparando as linhas de pistas, você percebe: «esta cor só pode ir aqui». Se cada palpite cortar o campo pela metade ou mais, você joga como um mestre.","O Hit & Blow deste Atlas tem cinco modalidades — 4 de 6 cores sem repetir (360 códigos), com repetição (os 1.296 de Knuth), 3 ou 4 algarismos e uma especialista de 5 entre 8 cores — e um problema do dia."],"cap":[]}],"tl":[["1970","MOO no computador de Cambridge; Meirowitz cria o tabuleiro de pinos"],["1971","A Invicta Plastics compra os direitos e lança o Mastermind"],["1972","MOO chega ao Multics no MIT; Super Mastermind"],["1977","Knuth: «no máximo cinco» (artigo de 1976–77)"],["1993","Koyama e Lai: um método com média de cerca de 4,34"]],"figL":{"time":[["?","Touros e Vacas","números no papel"],["1970","MOO","o computador de Cambridge"],["1971","Mastermind","Meirowitz · Invicta"],["1977","Sempre em cinco","a prova de Knuth"]]}},"botao":{"title":"Futebol com os botões do casaco","lead":"O futebol de botão é o futebol de mesa em que se dá toques em botões para levar uma bolinha ao gol. Uma brincadeira de bolso das crianças virou um esporte reconhecido pelo Estado.","s":["No futebol de botão, num campo de cerca de 167 cm de comprimento, cada time põe dez botões redondos e um bloco retangular como goleiro, e dá toques nos botões para levar uma bola de feltro de 1 cm até o gol adversário.","Diz-se que começou no início do século XX, quando crianças no Brasil e na Hungria arrancavam os botões de casacos e camisas para jogar. Na Hungria ainda se chama gombfoci, «futebol de botão».","No Brasil quem organizou o jogo foi Geraldo Décourt, artista carioca. Em 1930 (1929 em algumas fontes) ele publicou o primeiro livro de regras e chamou o jogo de «Foot-Ball Celotex», por causa do revestimento da mesa.","Em 1962 surgiu a federação paulista, e em 1988 o Conselho Nacional de Desportos reconheceu o futebol de mesa como esporte oficial. O aniversário de Décourt, 14 de fevereiro, é o Dia do Botonista no estado de São Paulo.","Outros países também têm futebol de toques. Na Grã-Bretanha nasceu em Liverpool um jogo do mesmo tipo em 1929, e em 1947 surgiu um futebol de mesa em que se dão toques com o dedo em bonequinhos; o pebolim, com bonecos em varetas, já era patenteado nos anos 1920."],"quiz":[["Como é um time de futebol de botão?","Dez botões e um goleiro","Onze botões","Cinco botões e um goleiro","Onze bonequinhos"],["Quando foi reconhecido como esporte oficial no Brasil?","1988","1930","1962","2001"],["No futebol de mesa nascido na Grã-Bretanha em 1947, o que se toca com o dedo?","Bonequinhos de jogadores com peso","Botões de casaco","Tampinhas","Moedas"]],"kf":["Futebol de mesa com dez botões e um bloco de goleiro, tocados para levar uma bola de feltro","Brincadeira de criança no início do século XX → livro de regras de Décourt em 1930 → esporte oficial no Brasil em 1988","Parentes: o gombfoci húngaro, os futebóis de toques britânicos (1929 e 1947) e o pebolim de varetas"],"more":[{"h":"Tocar, avisar, chutar","p":["Dá para tocar o botão com o dedo, mas muitos botonistas apertam a borda com uma peça plana chamada palheta, para que ele deslize. O próprio botão tem de tocar a bola.","Na regra de 12 toques, é preciso anunciar o chute em voz alta e esperar o adversário posicionar o goleiro antes de chutar. Gol sem aviso não vale."],"cap":["Como se dá o toque. (1) Aperta-se a borda do botão com uma palheta e ele desliza até a bola. (2) A bola passa ao lado do goleiro (o bloco azul) e entra no gol"]},{"h":"Regras que mudam com os toques","p":["O Brasil tem regras tradicionais de várias regiões: a baiana, de um toque com disco; a carioca, de três toques com bola; e a paulista, de doze toques com bola.","Nos doze toques pode-se tocar até doze vezes por posse, e o mesmo botão até três vezes seguidas. Quanto menos toques, menos gols; o de um toque, em que a vez muda a cada toque, é tido como coisa de especialista."],"cap":["Um time são dez botões e um goleiro retangular. As três regras clássicas do Brasil diferem em quantos toques cada posse permite"]},{"h":"A família do futebol de toques","p":["O futebol de mesa britânico de 1947, em que se dão toques com o dedo em bonequinhos, teria se inspirado num jogo do mesmo tipo nascido em Liverpool em 1929. Tocam-se pequenos jogadores com peso para levar a bola.","O pebolim, em que se giram fileiras de bonecos em varetas para chutar, foi patenteado na Grã-Bretanha em 1921, e na Espanha Alejandro Finisterre patenteou seu futbolín em 1937."],"cap":["A família do futebol de mesa de toques: o gombfoci húngaro, dois jogos britânicos de toques e o pebolim de bonecos em varetas"]},{"h":"Experimente","p":["Troque passes até a frente do gol, anuncie o chute e mire no espaço ao lado do goleiro: a força e o ângulo de um só toque decidem a partida.","O futebol de botão deste Atlas é um jogo só em 3D baseado na regra de 12 toques. Dá para escolher partidas por lances, por gols ou disputa de pênaltis, e campos de grama, madeira e outros."],"cap":[]}],"tl":[["início do séc. XX","Crianças na Hungria e no Brasil jogam com botões"],["1930","Primeiro livro de regras de Décourt (1929 em algumas fontes)"],["1947","Nasce na Grã-Bretanha um futebol de mesa de bonequinhos"],["1962","Fundada a federação paulista"],["1988","Reconhecido como esporte oficial no Brasil"]],"figL":{"rules":[["1","baiana\ndisco"],["3","carioca\nbola"],["12","paulista\nbola"]],"family":[["Futebol de botão","Brasil · regras de 1930"],["Gombfoci","Hungria · botões de casaco"],["Um jogo de Liverpool","Grã-Bretanha · 1929 · do mesmo tipo"],["Futebol de bonequinhos","Grã-Bretanha · 1947 · com o dedo"],["Pebolim","bonecos em varetas · patente de 1921"]]}},"hockey":{"title":"De um tabuleiro caseiro a um rinque de ar","lead":"O hóquei de mesa tem duas formas: o hóquei de varetas, em que varetas movem os jogadores, e o hóquei de ar, em que um disco flutuando no ar é rebatido de um lado para o outro. É a história de um tabuleiro canadense feito em casa e de engenheiros americanos.","s":["O hóquei de mesa é hóquei num pequeno rinque sobre a mesa. Há dois tipos principais: o de varetas, em que varetas sob o tabuleiro movem bonequinhos de jogadores, e o de ar, em que o disco flutua num colchão de ar e é rebatido com batedores.","Diz-se que o primeiro hóquei de mesa foi feito em Toronto, no Canadá, em 1932, por Donald Munro. Sem dinheiro para o Natal durante a Depressão, ele construiu um tabuleiro para os filhos com sobras de madeira, arame e molas de relógio. Vendido numa loja de departamentos de Toronto, fez sucesso.","No hóquei de varetas, os bonequinhos ficam em fendas abertas no tabuleiro, ligados a varetas por baixo. Empurrando ou puxando a vareta, o jogador desliza pela fenda; girando-a, ele balança o taco. Depois o jogo se espalhou pelos países nórdicos e outros lugares, e tem federação internacional e campeonatos mundiais.","Em 1969, engenheiros da empresa americana Brunswick começaram a trabalhar num jogo numa superfície de pouco atrito. Bob Lemieux retomou o projeto parado, e nasceu o «hóquei de ar», com um disco fino, dois batedores e gols em fenda; ele chegou às lojas no início dos anos 1970.","Fazer objetos flutuarem numa mesa de ar era uma ideia mais antiga, usada para mover cargas pesadas e em material de física das escolas. O hóquei de ar fez sucesso: em meados dos anos 1970 já havia torneios nos Estados Unidos, e em 1978 começou um campeonato mundial."],"quiz":[["Onde se diz que foi feito o primeiro hóquei de mesa?","Toronto, 1932","Chicago, 1972","Estocolmo, 1900","Tóquio, 1950"],["Por que o disco do hóquei de ar não para de deslizar?","Flutua no ar que sai de furinhos na mesa","É feito de gelo","A mesa é inclinada","Tem rodinhas embaixo"],["Como se move um jogador no hóquei de varetas?","Empurrando, puxando e girando uma vareta sob o tabuleiro","Com um peteleco","Com um ímã","Com um barbante"]],"kf":["Hóquei de varetas: empurrar, puxar e girar varetas sob o tabuleiro para mover os jogadores nas fendas","Hóquei de ar: o ar dos furos faz o disco flutuar, rebatido com batedores","Um tabuleiro caseiro em Toronto, 1932 → pesquisa desde 1969 → hóquei de ar no início dos anos 1970"],"more":[{"h":"Jogadores em fendas","p":["Como cada um comanda vários jogadores, trocar depressa de vareta é tudo. O plano básico é passar e mirar no lado oposto ao goleiro.","Conta-se que o primeiro tabuleiro de Munro era mais alto no meio e descia para as pontas, com uma alavanca para o goleiro e batedores para os outros. As varetas giratórias de hoje se espalharam depois."],"cap":["Um tabuleiro de hóquei de varetas. Cada jogador fica numa fenda e é movido por uma vareta sob o tabuleiro: (1) empurrar ou puxar a vareta o faz deslizar pela fenda; (2) girá-la faz o taco balançar (o tracejado é a vareta sob o tabuleiro)"]},{"h":"Um disco que flutua no ar","p":["Quase sem atrito, o disco tabela nas laterais de novo e de novo. O chute de tabela, que muda o ângulo numa lateral, é um fundamento; quem defende corre para os cantos do gol, formando um triângulo.","As mesas de torneio medem 8 pés (cerca de 2,4 m). O batedor também é chamado de raquete ou rebatedor, e o disco é de plástico duro."],"cap":["Uma mesa de hóquei de ar. O ar sopra por inúmeros furinhos (setas, à esquerda) e o disco flutua um pouquinho e desliza sem parar. Batido pelo batedor vermelho, ele tabela na lateral direita e passa pelo batedor azul que guarda o meio do gol (tracejado)"]},{"h":"O hóquei de mesa no tempo","p":["Nos anos 1980, mesas de hóquei de varetas sob uma cúpula transparente fizeram sucesso em fliperamas. O pebolim, com bonecos em varetas chutando uma bola, é da mesma família «movida por varetas».","No Japão, o hóquei de ar também virou um clássico dos fliperamas por volta dos anos 1980, e há mesinhas para casa."],"cap":["O hóquei de mesa no tempo: hóquei de varetas em Toronto em 1932, pesquisa de mesas de ar desde 1969, hóquei de ar no início dos anos 1970 e um campeonato mundial desde 1978"]},{"h":"Experimente","p":["Defender, usar as laterais, passar pelo espaço ao lado do batedor rival: olhos que leem um disco rápido e mãos ágeis decidem a partida.","O hóquei de mesa deste Atlas é só em 3D, com seis mesas, entre elas um pequeno rinque de feltro e uma mesa de ar. Use o chute de borda — uma batida de raspão com a borda do batedor — para vencer o gol rival."],"cap":[]}],"tl":[["1932","Munro constrói um hóquei de mesa em Toronto"],["1969","Começa nos EUA a pesquisa de um jogo em mesa de ar"],["1972","O hóquei de ar chega às lojas (início dos anos 1970)"],["1975","Fundada nos EUA uma associação de hóquei de ar"],["1978","Começa um campeonato mundial de hóquei de ar"]],"figL":{"time":[["1932","Hóquei de varetas","Toronto · feito para os filhos"],["1969","Mesas de ar","engenheiros americanos"],["1972","Hóquei de ar","lançado pela Brunswick"],["1978","Campeonato mundial","torneios de hóquei de ar"]]}},"solitaire":{"title":"Paciência: cartas para um só","lead":"O solitário, jogo de cartas para uma pessoa, chama-se «patience» (paciência) na Grã-Bretanha — e «paciência» também em português. De um livro alemão do século XVIII à tela do computador, esta é a história das cartas jogadas a sós.","s":["Paciência ou solitário é o nome dos jogos de cartas para uma pessoa. As cartas são dispostas num arranjo fixo e movidas segundo as regras; vence-se ao montar cada naipe do Ás ao Rei. Na Grã-Bretanha diz-se «patience»; na América do Norte, «solitaire» espalhou-se no século XX.","A descrição mais antiga conhecida está na edição de 1783 de um livro alemão de jogos, com o nome «Patience». Provavelmente nasceram na Alemanha ou na Escandinávia, e há quem aponte ligação com as tiragens de cartomancia difundidas pouco antes. Em dinamarquês e norueguês chamam-se kabal.","As paciências viraram moda na França no início do século XIX e chegaram à Grã-Bretanha e à América na segunda metade. Em 1826 saiu na Rússia um livro só de paciências. Em inglês é bem conhecido o Illustrated Games of Patience, de lady Adelaide Cadogan, de cerca de 1870.","A mais famosa, a Klondike, joga-se com sete pilhas. O registro mais antigo das suas regras está num livro de 1907. Há quem diga que o nome vem da corrida do ouro canadense, mas não há prova firme.","Em 1990 a Klondike passou a vir junto com os computadores pessoais, e gente do mundo todo começou a jogar. O FreeCell, com todas as cartas viradas para cima, foi criado em 1978 por Paul Alfille, estudante de medicina, num computador da universidade."],"quiz":[["Como o solitário é chamado na Grã-Bretanha?","Patience (paciência)","Kabal","Klondike","FreeCell"],["Onde está o registro mais antigo do solitário?","Num livro alemão, edição de 1783","Num livro francês de cerca de 1650","Num livro americano de 1907","Num computador de 1990"],["Das distribuições 1 a 32.000 do FreeCell que vinha com os computadores, quantas não têm solução?","Só uma, a 11982","Exatamente a metade","Uma em cada cem","Nenhuma"]],"kf":["Arrume as cartas sozinho e monte cada naipe do Ás ao Rei para vencer. Na Grã-Bretanha, «patience»","Registro mais antigo: um livro alemão, edição de 1783. Provavelmente nasceu na Alemanha ou na Escandinávia","As regras mais antigas da Klondike estão num livro de 1907; desde 1990 os computadores a espalharam"],"more":[{"h":"O arranjo da Klondike","p":["Distribuem-se 28 cartas nas sete pilhas, e as 24 restantes formam o monte. Nas pilhas desce-se de um em um, alternando vermelho e preto. Só um Rei pode ir para uma pilha vazia.","Ainda não se sabe com que frequência se ganha a Klondike jogando bem. Mesmo conhecendo todas as cartas viradas para baixo, calcula-se que no máximo se ganha pouco mais de oito em cada dez partidas."],"cap":["O arranjo da Klondike. No alto à esquerda, o monte e as cartas viradas; no alto à direita, as quatro bases por naipe. Embaixo, sete pilhas de uma a sete cartas, só a de cima virada para cima"]},{"h":"FreeCell, quase sempre solúvel","p":["No FreeCell arrumam-se cartas todas visíveis com quatro casas livres que guardam uma carta cada. É um jogo de cálculo, não de sorte, e quase todas as distribuições têm solução.","Das distribuições 1 a 32.000 do jogo que vinha com os computadores, só a 11982 não pôde ser resolvida. Um estudo de 2018 com 8,6 bilhões de distribuições achou cerca de uma sem solução a cada 84 mil."],"cap":["O arranjo do FreeCell. No alto à esquerda, quatro casas livres; no alto à direita, quatro bases; embaixo, oito colunas todas viradas para cima. A faixa de baixo cobre as distribuições 1 a 32.000 do jogo que vinha com os computadores: só a 11982 não tem solução"]},{"h":"A paciência no tempo","p":["O FreeCell vem do «Baker’s Game», que Martin Gardner descreveu numa revista em 1968. No fim do século XIX, a inglesa Mary Whitmore Jones reuniu umas 250 paciências em seus livros.","Em outros lugares, «solitário» também pode significar jogos de tabuleiro para um, como o resta um. O historiador de jogos David Parlett prefere «patience», que se refere só às cartas."],"cap":["A paciência no tempo: um livro alemão de 1783, um livro inglês de cerca de 1870, as regras da Klondike em 1907, o FreeCell em 1978 e os computadores em 1990"]},{"h":"Experimente","p":["A paciência é um jogo para momentos calmos, que põe as ideias em ordem. Que pilha desfazer primeiro, que carta guardar? Quanto mais longe você pensa, mais vezes vence.","A paciência deste Atlas tem Klondike, Spider e FreeCell, além de uma distribuição do dia. Fiel ao nome, arrume as cartas com calma."],"cap":[]}],"tl":[["1783","«Patience» aparece num livro alemão (registro mais antigo)"],["1826","Sai na Rússia um livro só de paciências"],["c. 1870","Illustrated Games of Patience, de lady Adelaide Cadogan"],["1907","As regras da Klondike aparecem num livro"],["1990","Espalha-se pelo mundo com um jogo que vinha nos computadores"]],"figL":{"time":[["1783","Patience","registro mais antigo, livro alemão"],["c. 1870","Livro em inglês","lady Adelaide Cadogan"],["1907","Klondike","regras mais antigas"],["1978","FreeCell","num computador de universidade"],["1990","Nos computadores","jogo que vinha junto"]]}},"sudoku":{"title":"Os algarismos devem ser solteiros","lead":"O sudoku: pôr de 1 a 9 numa grade de 9×9. Nasceu numa revista americana, ganhou nome no Japão e espalhou-se pelo mundo a partir de jornais britânicos. Não pede contas — só lógica.","s":["O sudoku tem uma única regra: preencher a grade de 9×9 de modo que cada linha, cada coluna e cada quadrado de 3×3 marcado em negrito tenha uma vez cada algarismo de 1 a 9. Não é preciso somar nem subtrair. Um bom sudoku tem exatamente uma solução.","Um sudoku completo é um tipo do que os matemáticos chamam de quadrado latino. O matemático do século XVIII Leonhard Euler é conhecido por estudá-los, mas não há ligação direta com o passatempo. Em 1892 e 1895, jornais franceses publicaram quadrados mágicos para preencher com números, mas exigiam contas ou não tinham quadrados de 3×3; ainda não eram o sudoku de hoje.","O sudoku moderno apareceu pela primeira vez em 1979 numa revista americana de passatempos, com o nome «Number Place». Acredita-se que o autor tenha sido Howard Garns, arquiteto aposentado.","Em 1984 uma revista japonesa de passatempos (Nikoli) apresentou-o como «os algarismos devem ser solteiros», e em 1986 o presidente da empresa, Maki Kaji, encurtou o nome para «sudoku». No Japão o nome é marca registrada dessa empresa, e outras editoras o chamam de «nanpure» e semelhantes.","Wayne Gould, que encontrou um livro de sudoku em Tóquio em 1997, passou anos escrevendo um programa para criar problemas, e em novembro de 2004 o sudoku saiu no jornal britânico The Times. Em 2005 já era febre em jornais do mundo todo, e desde 2006 há um campeonato mundial."],"quiz":[["No sudoku, o que precisa ter de 1 a 9 uma vez?","Cada linha, cada coluna e cada quadrado de 3×3","Só as colunas","Só as diagonais","Só a borda"],["Qual é o mínimo de pistas de um sudoku com solução única?","17","9","25","30"],["Onde e quando o sudoku moderno apareceu pela primeira vez numa revista?","EUA, 1979","Japão, 1984","França, 1892","Grã-Bretanha, 2004"]],"kf":["Cada linha, coluna e quadrado de 3×3 tem de 1 a 9 uma vez. Sem contas","Mínimo de 17 pistas: uma busca exaustiva em 2012 mostrou que nenhum com 16 tem solução única","«Number Place» nos EUA, 1979 → nome dado no Japão, 1984 → o mundo a partir da Grã-Bretanha, 2004"],"more":[{"h":"Linhas, colunas e quadrados","p":["A ideia mais básica para resolver um sudoku é achar «este algarismo só pode ir aqui». Depois de colocado um algarismo, nenhuma outra casa da mesma linha, coluna ou quadrado pode ter o mesmo.","Como no desenho, quando os 5 de outros lugares fecham as linhas e colunas do quadrado de cima à esquerda, sobra uma só casa para o seu 5. Um bom sudoku se resolve até o fim só com esses passinhos, sem chutar."],"cap":["As restrições. Queremos o 5 do quadrado de cima à esquerda (moldura verde). Os outros quatro 5 bloqueiam suas linhas e colunas (faixas vermelhas), e sobra só a casa verde para o seu 5"]},{"h":"A partir de dezessete pistas","p":["Tirando pistas uma a uma, chega um ponto em que a solução deixa de ser única. Em 2012 o irlandês Gary McGuire e colegas mostraram, com uma longa busca exaustiva no computador, que nenhum sudoku de 16 pistas tem solução única: o mínimo é 17.","Em 2005 também se calculou que existem cerca de 6,67 × 10²¹ grades de sudoku completas. Mais pistas nem sempre significam mais fácil: a dificuldade depende de onde elas estão."],"cap":["Um sudoku com só 17 pistas; ainda assim tem uma única solução. Não existe sudoku de 16 pistas com solução única"]},{"h":"O sudoku no tempo","p":["O nome «sudoku» abrevia «os algarismos devem ser solteiros»: um algarismo por casa. Em português também se diz sudoku.","Há muitos parentes com regras um pouco mudadas: o «killer», em que a soma de cada gaiola é a pista; o «jigsaw», com regiões irregulares; e enormes problemas de cinco grades sobrepostas."],"cap":["O sudoku no tempo: os quadrados latinos de Euler, os passatempos dos jornais franceses, o «Number Place» americano, o nome japonês e a febre mundial que começou na Grã-Bretanha"]},{"h":"Experimente","p":["Com lápis, papel e um pouco de intuição joga-se em qualquer lugar. Se travar, escolha um algarismo e percorra a grade inteira com os olhos.","Este Atlas tem sudoku com problemas novos todo dia em três níveis, e o sudoku rápido, uma corrida numa pequena grade de 4×4."],"cap":[]}],"tl":[["1782","Euler estuda os quadrados latinos (a raiz matemática)"],["1892","Um passatempo de números num jornal francês"],["1979","«Number Place» numa revista americana"],["1984","Chega ao Japão; em 1986 recebe o nome «sudoku»"],["2004","Começa nos jornais britânicos uma febre mundial"]],"figL":{"time":[["1782","Quadrados latinos","estudo de Euler · matemática"],["1892","Jornais franceses","preencher com números"],["1979","Number Place","uma revista americana"],["1984","«Sudoku»","nome de uma revista japonesa"],["2004","Febre mundial","a partir de jornais britânicos"]]}},"shanghai":{"title":"Peças empilhadas, de duas em duas","lead":"O mahjong paciência, chamado «Shanghai» no Japão, consiste em tirar pares iguais de um monte de peças de mahjong. As peças nasceram na China do século XIX, mas este jeito de jogar nasceu em 1981 num computador universitário americano.","s":["O mahjong paciência é um jogo para um: 144 peças de mahjong são empilhadas em várias camadas, e tiram-se de duas em duas as peças de desenho igual. Só se pode tirar uma peça sem nada por cima e com o lado esquerdo ou o direito livre. Vence-se ao tirar os 72 pares.","As peças são as do mahjong, nascido na China do século XIX. Mas empilhá-las e tirá-las sozinho começou em 1981 com «Mah-Jongg», feito pelo americano Brodie Lockard no PLATO, um sistema de computador educativo usado em universidades.","Em 1986 o jogo foi vendido para computadores domésticos com o nome «Shanghai» e fez sucesso. No Japão esse nome passou a designar o próprio jeito de jogar.","No lançamento, foi anunciado como baseado em «a Tartaruga», um jogo que se jogaria na China havia séculos. Mas o próprio Lockard nunca disse isso, e não há prova firme: melhor curtir como lenda.","Por volta de 1989 chegou aos fliperamas um parente, o Shisen-sho, em que os pares se ligam por uma linha. Desde 1990 também foi muito jogado como jogo que vinha com os computadores pessoais."],"quiz":[["Que peças podem ser tiradas no mahjong paciência?","As sem nada por cima e com o lado esquerdo ou direito livre","As da camada de baixo","As cercadas por todos os lados","Só as do meio"],["Onde esse jeito de jogar foi criado?","Num computador universitário americano, em 1981","Na China do século XIX","Em Xangai nos anos 1920","No Japão em 1990"],["E a história de que vem de um velho jogo chinês, «a Tartaruga»?","Era propaganda, sem prova firme","O criador a escreveu","Está num livro chinês antigo","Veio do desenho de um casco"]],"kf":["Tire pares iguais de um monte de 144 peças; só estão livres as sem nada por cima e com um lado livre","Começou em 1981 com o «Mah-Jongg» de Lockard no PLATO","Espalhou-se como «Shanghai» em 1986; a lenda da Tartaruga era propaganda, sem prova"],"more":[{"h":"Peças livres e presas","p":["Duas condições decidem se uma peça está livre: nada por cima, e nenhuma peça à esquerda ou à direita. As flores (ameixeira, orquídea, crisântemo, bambu) e as estações (primavera, verão, outono, inverno) formam pares dentro do grupo, mesmo com desenhos diferentes.","A ordem importa muito. Tirando o primeiro par que se vê, uma peça igual pode ficar presa debaixo de outra e travar o jogo no fim."],"cap":["Peças que podem ser tiradas (✓) e que não (×). Em cima: as duas das pontas e o 發 por cima estão livres; as que têm peça por cima ou estão presas dos dois lados, não. Embaixo: o 東 do meio está preso dos dois lados"]},{"h":"A famosa Tartaruga","p":["A Tartaruga é um monte comprido com peças sobressaindo nas pontas, como cabeça e cauda. Um estudo de dez milhões de distribuições desse arranjo achou que cerca de 3 % não podem ser concluídas de jeito nenhum.","Muitos outros arranjos foram criados: pirâmides, dragões, castelos… Cada forma muda onde as peças saem fácil e onde emperram."],"cap":["O arranjo mais famoso, a Tartaruga, visto de cima: 87 peças na camada de baixo, depois 36, 16, 4 e uma no topo — cinco camadas, 144 peças (mais escuro = mais alto)"]},{"h":"O mahjong paciência no tempo","p":["No Shisen-sho, tiram-se duas peças iguais quando podem ser ligadas por uma linha de no máximo duas curvas que não toque outras peças. As peças ficam planas, sem empilhar.","O PLATO foi um sistema de computador educativo nascido na Universidade de Illinois, conhecido também pelos muitos jogos criados nele bem cedo."],"cap":["O mahjong paciência no tempo: a lenda da Tartaruga, «Mah-Jongg» no PLATO em 1981, «Shanghai» em 1986, o Shisen-sho por volta de 1989 e os computadores pessoais desde 1990"]},{"h":"Experimente","p":["Procure primeiro todos os pares possíveis e depois decida qual tirar antes. Quando aparecem três ou quatro peças iguais, é aí que a habilidade aparece.","O mahjong paciência deste Atlas é só em 3D, com a Tartaruga e muitos outros arranjos. Toda distribuição é feita para poder ser concluída."],"cap":[]}],"tl":[["1981","Lockard cria o «Mah-Jongg» no PLATO"],["1986","Vendido para computadores domésticos como «Shanghai»"],["1986","Anunciado como baseado na «Tartaruga» chinesa (sem prova)"],["1989","O Shisen-sho, que liga peças por linhas, chega aos fliperamas"],["1990","Também jogado como jogo que vinha nos computadores"]],"figL":{"time":[["?","A lenda da Tartaruga","jogo chinês antigo? (propaganda)"],["1981","Mah-Jongg","no sistema PLATO"],["1986","«Shanghai»","em computadores domésticos"],["1989","Shisen-sho","parente ligado por linhas"],["1990","Nos PCs","jogo que vinha junto"]]}},"samegame":{"title":"Mesma cor, tudo de uma vez","lead":"No SameGame, peças vizinhas da mesma cor são removidas em grupo. Nascido num computador pessoal japonês em 1985, espalhou-se pelo mundo com novos nomes como precursor dos quebra-cabeças de «limpar o tabuleiro».","s":["SameGame é um quebra-cabeça para um, num tabuleiro cheio de peças coloridas. Quando duas ou mais peças da mesma cor se tocam na horizontal ou na vertical, o grupo todo pode ser removido de uma vez. As peças de cima caem no buraco, e uma coluna vazia se fecha para a esquerda. O jogo acaba quando não sobra grupo para remover.","Começou em 1985 com «Chain Shot!», feito por Kuniaki Moribe para os computadores pessoais japoneses da época. Foi distribuído por uma revista de informática; o tabuleiro era de 20×10, com quatro cores.","Em 1992 Eiji Fukumoto levou-o para computadores Unix como «SameGame» e aumentou as cores para cinco. Daí o nome se espalhou. «Same» é a palavra inglesa para «igual».","Vieram muitas versões e adaptações, em computadores, aparelhos de bolso e consoles. Algumas, como «Clickomania!» em 1998, deixam mudar o tamanho do tabuleiro e o número de cores.","Parece simples, mas é um quebra-cabeça profundo. Um estudo de 2001 mostrou que decidir se um tabuleiro pode ser esvaziado por completo pode ser um problema «NP-completo», como dizem os cientistas da computação: um problema difícil."],"quiz":[["O que se pode remover no SameGame?","Um grupo de duas ou mais peças vizinhas da mesma cor","Uma peça sozinha","Peças que se tocam na diagonal","Só a linha de cima"],["Com a pontuação comum (n−2)², quanto vale um grupo de 10?","64","10","20","100"],["O que significa «same» em SameGame?","A palavra inglesa «igual»","Um tipo de peixe","«Frio» em japonês","O nome do autor"]],"kf":["Removem-se duas ou mais peças vizinhas da mesma cor. As de cima caem; colunas vazias se fecham à esquerda","Começou com «Chain Shot!» em 1985; o nome se espalhou com «SameGame» em 1992","Em muitas versões um grupo vale (n−2)²: faça crescer grupos grandes e remova-os de uma vez"],"more":[{"h":"Remover, cair, fechar","p":["Cada grupo removido muda a forma inteira do tabuleiro. As peças que caem podem formar novos grupos — ou separar uma cor que você estava guardando.","Uma peça sozinha não pode ser removida. Quantas peças sobrarão no fim? Dá para esvaziar tudo? É aí que aparece a habilidade."],"cap":["No tabuleiro da esquerda remove-se o grupo de cinco peças azuis marcadas de branco (tabuleiro da direita): as peças de cima caem (seta vermelha) e a coluna vazia some quando as colunas à direita se fecham para a esquerda"]},{"h":"Quanto maior, melhor","p":["Em muitas versões, um grupo de n peças vale (n−2)² pontos. Pares não pontuam, cinco valem 9 e dez valem 64: quanto maior o grupo, mais rápido os pontos crescem.","Por isso o plano básico é remover antes os grupinhos que atrapalham, juntar uma cor e depois removê-la de uma vez. Muitas versões dão ainda um grande bônus por esvaziar o tabuleiro."],"cap":["Tamanho do grupo n e pontos (n−2)²: duas peças dão 0, cinco dão 9, dez dão 64. Remover dez de uma vez vale muito mais que dois grupos de cinco"]},{"h":"O SameGame no tempo","p":["Em 1994 veio uma versão para Macintosh, e versões baseadas nela foram depois incluídas em ambientes de trabalho livres, jogadas no mundo todo.","O próprio criador, Kuniaki Moribe, fez mais tarde uma nova versão. Quebra-cabeças de limpar o tabuleiro continuam nascendo até hoje."],"cap":["O SameGame no tempo: «Chain Shot!» em 1985, «SameGame» em 1992, «Clickomania!» em 1998, a prova de dificuldade em 2001 e o «SameGame POP!» deste Atlas"]},{"h":"Experimente","p":["Tente guardar a cor mais numerosa para o fim e remover as outras antes. Sentir um grande grupo crescer é a graça do SameGame.","O «SameGame POP!» deste Atlas é um jogo original baseado nessas regras. Jogue fases com blocos especiais como gelo e prismas, ou os problemas do dia."],"cap":[]}],"tl":[["1985","Kuniaki Moribe cria «Chain Shot!» (20×10, quatro cores)"],["1992","«SameGame» para Unix de Eiji Fukumoto: cinco cores e o nome se espalha"],["1994","Uma versão para Macintosh, base de muitas outras"],["1998","«Clickomania!», com tabuleiro e cores ajustáveis"],["2001","Prova-se que decidir se dá para esvaziar é NP-completo"]],"figL":{"time":[["1985","Chain Shot!","Moribe · computadores japoneses"],["1992","SameGame","Fukumoto · Unix · 5 cores"],["1998","Clickomania!","tabuleiro e cores à vontade"],["2001","Prova de dificuldade","esvaziar é NP-completo"],["hoje","SameGame POP!","original deste Atlas"]]}},"cards":{"title":"A longa viagem de quatro sinais","lead":"Copas, ouros, paus e espadas. Os naipes das cartas que o mundo usa hoje nasceram das cartas de papel da China, passaram pelo Egito mameluco e percorreram a Europa, mudando de forma de mão em mão.","s":["Acredita-se que as cartas de papel nasceram na China. Pensa-se que já existiam por volta do século IX, na dinastia Tang, quando a impressão xilográfica se difundia, e um texto conta que uma princesa Tang jogou o «jogo das folhas» em 868 (se era mesmo um jogo de cartas é discutido). O erudito Song Ouyang Xiu escreveu que o jogo das folhas existia desde meados da Tang. Mais tarde, sob os Ming, usaram-se «cartas de dinheiro» com moedas e fieiras de moedas.","Na Ásia ocidental foram encontrados fragmentos de cartas dos séculos XII e XIII. Em 1939, o estudioso L. A. Mayer encontrou no palácio de Topkapı, em Istambul, um baralho mameluco do século XV quase completo. Tinha originalmente 52 cartas em quatro naipes — taças, moedas, espadas e tacos de polo — e cada naipe tinha três cartas de posição: o rei, o vice-rei e o segundo vice-rei.","Acredita-se que as cartas chegaram à Europa a partir desse mundo islâmico. O registro mais antigo é um dicionário de rimas catalão de 1371. Em 1377, Florença proibiu o jogo de cartas e, no mesmo ano, o monge alemão João de Rheinfelden escreveu um tratado sobre elas. A palavra espanhola naipes viria do árabe nā’ib, «delegado» — e daí também o «naipe» português.","Na Europa, os desconhecidos tacos de polo viraram bastões, formando os naipes «latinos»: copas, moedas, espadas e bastões. Nas terras de língua alemã do século XV surgiram os naipes «alemães» — corações, guizos, folhas e bolotas —, e por volta de 1480 os fabricantes franceses os simplificaram em copas, ouros, paus e espadas. Fáceis de colorir com moldes vazados, essas formas viraram depois o padrão mundial.","Comerciantes portugueses levaram as cartas ao Japão em meados do século XVI. A palavra japonesa karuta vem do português «carta». Na era Tenshō (1573–92), fizeram-se em Miike, em Chikugo, as «Tenshō karuta» de 48 cartas, imitando o baralho português. Depois da proibição do xogunato em 1633, os fabricantes mudaram os desenhos, e com o tempo surgiram o hanafuda e o uta-garuta de poemas."],"quiz":[["Que naipe tinham as cartas mamelucas?","Tacos de polo","Bolotas","Guizos","Ouros"],["De onde vem a palavra «karuta»?","Do português «carta»","Do «jogo das folhas» chinês","Do holandês kaart","De uma palavra japonesa antiga"],["Onde e quando surgiram copas, ouros, paus e espadas?","Na França, por volta de 1480","Na China Tang","No Egito mameluco","Na América do século XIX"]],"kf":["Acredita-se que as cartas de papel nasceram na China (Tang) por volta do século IX","As taças, moedas, espadas e tacos de polo mamelucos são a raiz dos naipes europeus","♥♦♣♠ nasceram na França por volta de 1480; o japonês «karuta» vem do português «carta»"],"more":[{"h":"Como os sinais mudaram","p":["Os desenhos dos naipes mudaram para se ajustar à vida de cada terra aonde chegavam. Na Europa, onde não se conhecia o polo, os tacos foram vistos como bastões. Nas terras de língua alemã, acredita-se que as taças viraram corações, as moedas guizos, as espadas folhas e os bastões bolotas.","Ainda hoje a Itália e a Espanha usam baralhos de naipes latinos, e o sul da Alemanha e a Áustria os de naipes alemães, junto com seus jogos locais. Em francês, ♣ é trèfle, «trevo», e ♠ é pique, «lança»."],"cap":["Os naipes ao longo do tempo (cada coluna corresponde aproximadamente). As taças, moedas, espadas e tacos de polo mamelucos viraram as taças, moedas, espadas e bastões latinos, os corações, guizos, folhas e bolotas alemães e depois os ♥ ♦ ♠ ♣ franceses"]},{"h":"De leste a oeste, e até o Japão","p":["A viagem das cartas foi também uma viagem do papel e da impressão. As caras cartas pintadas à mão ficaram baratas quando passaram a ser impressas em madeira e coloridas com moldes, e no fim do século XIV já se espalhavam pelas cidades da Europa. Na primeira metade do século XV há registros de cartas impressas em Ulm e Nuremberg.","Tão depressa quanto as cartas se espalhavam, surgiam decretos preocupados com o excesso de jogo. Ironicamente, essas proibições são hoje a prova mais segura de quando e onde havia cartas."],"cap":["A viagem das cartas: das cartas de papel da China às cartas mamelucas da Ásia ocidental, à Europa do século XIV, à França de cerca de 1480 e ao Japão do século XVI"]},{"h":"Cinquenta e duas cartas e um curinga","p":["Quatro naipes de treze, cinquenta e duas cartas ao todo: o mesmo número do baralho mameluco. Na Europa as cartas de posição ganharam a forma de reis, cavaleiros e criados, e o baralho francês ficou com rei, dama e valete.","Os pequenos números e sinais nos cantos — os «índices» — são conhecidos por um exemplo antigo de 1693; eles permitem segurar as cartas abertas em leque. Acredita-se que o curinga foi acrescentado nos Estados Unidos em meados do século XIX (por volta da década de 1860) como trunfo máximo do jogo de euchre."],"cap":["Cinquenta e duas cartas: quatro naipes × 13. J, Q e K formam 12 figuras (douradas). O curinga foi acrescentado nos EUA em meados do século XIX"]},{"h":"Experimente","p":["Com as mesmas cinquenta e duas cartas jogam-se jogos tão diferentes quanto a paciência arrumada sozinho, o pôquer com suas combinações e o blackjack que busca o 21. Um único baralho é uma caixa de ferramentas com centenas de jogos.","O pôquer e o blackjack deste Atlas foram feitos para aprender as regras e o raciocínio sem dinheiro nenhum. Junto com a paciência, experimente alguns dos jogos de cartas que essa longa história criou."],"cap":[]}],"tl":[["868","Registra-se uma princesa Tang jogando o «jogo das folhas»"],["séc. XII–XIII","Fragmentos de cartas da Ásia ocidental (os mais antigos preservados)"],["1377","Proibição em Florença; tratado de João de Rheinfelden"],["c. 1480","Surgem na França os naipes ♥ ♦ ♣ ♠"],["1573–92","Era Tenshō: as «Tenshō karuta» são feitas em Miike"]],"figL":{"suits":[["Mameluco","séc. XV"],["Latino","desde séc. XIV"],["Alemão","séc. XV"],["Francês","c. 1480"]],"route":[["c. séc. IX","China","folhas e dinheiro"],["séc. XII–XV","Mamelucos","taças, moedas, espadas"],["déc. 1370","Europa","à Espanha e à Itália"],["c. 1480","França","♥ ♦ ♣ ♠"],["fim séc. XVI","Japão","Tenshō karuta"]],"court":["Numeradas","Figuras","Curinga","séc. XIX, EUA"]}},"machines":{"title":"Máquinas que aprenderam a jogar","lead":"Da fraude de um autômato a calculadoras que leem lances à frente e programas que se fortalecem jogando contra si mesmos: por 250 anos, os jogos de tabuleiro têm sido o campo de provas das «máquinas que pensam».","s":["Em 1770, no palácio de Schönbrunn, em Viena, Wolfgang von Kempelen apresentou uma figura que jogava xadrez, «o Turco». Ele percorreu a Europa e a América impressionando o público, e diz-se que Napoleão jogou contra ele. Mas era uma fraude: um jogador humano escondido no móvel fazia os lances. O Turco foi destruído num incêndio na Filadélfia em 1854.","A primeira máquina que realmente jogava sozinha foi construída pelo engenheiro espanhol Leonardo Torres Quevedo. Concluído em 1912, «El Ajedrecista» («o enxadrista») jogava com circuitos elétricos um único final: rei e torre brancos contra o rei preto. Nem sempre achava o caminho mais curto, mas diz-se que dava xeque-mate todas as vezes.","Em 1950, o americano Claude Shannon mostrou, num artigo sobre como programar um computador para jogar xadrez, como dar notas às posições, olhar vários lances à frente e escolher o melhor. Na Grã-Bretanha, Alan Turing escreveu um programa de xadrez no papel antes que houvesse um computador capaz de rodá-lo e, diz-se, jogou-o calculando os lances à mão.","Nos anos 1950, Arthur Samuel fez um computador jogar damas e o pôs para jogar contra si mesmo muitas vezes, para que melhorasse aos poucos. Atribui-se a ele a popularização da expressão «aprendizado de máquina», usada no título de seu artigo de 1959. Mais tarde, o canadense Chinook conquistou em 1994 o título mundial homem-máquina e, em 2007, as damas (inglesas) foram enfim «resolvidas»: com jogo perfeito dos dois lados, dá empate.","Em 1997, o Deep Blue, da IBM, venceu o campeão mundial Garry Kasparov por 3½–2½ (no ano anterior, Kasparov tinha vencido por 4–2). Até no go, considerado difícil demais pelo enorme número de lances possíveis, o AlphaGo, da DeepMind, venceu Lee Sedol por 4–1 em 2016. Em 2017, o AlphaZero, a quem só se deram as regras, aprendeu xadrez, shogi e go jogando apenas contra si mesmo."],"quiz":[["Qual era o segredo do «Turco», apresentado em 1770?","Um jogador humano escondido fazia os lances","Só engrenagens pensavam","Funcionava a eletricidade","Recebia ordens por carta de longe"],["O que mostrou a resolução das damas em 2007?","Com jogo perfeito, é empate","O primeiro jogador sempre vence","O segundo jogador sempre vence","Ainda não se sabe nada"],["Que programa de go venceu Lee Sedol em 2016?","AlphaGo","Deep Blue","Chinook","El Ajedrecista"]],"kf":["O Turco de 1770 era uma fraude com um humano dentro; a primeira máquina que jogava de fato sozinha foi um autômato de finais de 1912","O artigo de Shannon de 1950 lançou a ideia de «dar notas e olhar à frente»; as damas foram resolvidas em 2007: empate","Máquinas venceram os melhores humanos no xadrez em 1997 e no go em 2016"],"more":[{"h":"Pessoas contra máquinas, ao longo do tempo","p":["Por muito tempo, uma máquina jogar um jogo de tabuleiro foi vista como medida da capacidade de pensar. Uma história que começou com uma figura fraudulenta passou por aparelhos elétricos, programas no papel e, por fim, computadores de verdade.","Curiosamente, cada época teve um jogo que «uma máquina nunca jogaria bem». Damas, depois xadrez, depois go: a fronteira não parou de avançar."],"cap":["Pessoas contra máquinas: o Turco de 1770 (uma fraude), a máquina de finais de 1912, o artigo de 1950, Samuel em 1959, Chinook em 1994, Deep Blue em 1997, AlphaGo em 2016 e AlphaZero em 2017"]},{"h":"Como se lê à frente","p":["Muitos programas abrem o futuro de uma posição como os galhos de uma árvore. Na sua vez, supõem o melhor lance (o máximo); na vez do adversário, o pior para eles (o mínimo), e levam as notas das folhas até a raiz. Isso se chama «minimax».","Não é preciso ler todos os galhos. Um galho que já se sabe pior que outro lance pode ser cortado sem ler mais (poda alfa-beta). Graças a essa poda, um programa lê muito mais fundo no mesmo tempo."],"cap":["Minimax e poda. ▲ é a máquina (escolhe o maior), ▼ o adversário (escolhe o menor). O galho da esquerda garante 3; assim que o galho do meio mostra um 2, sabe-se que é pior, e suas outras duas folhas (?) não precisam ser lidas (✂). A resposta na raiz é 3"]},{"h":"Jogos resolvidos e não resolvidos","p":["«Resolver» um jogo é estabelecer o que acontece quando os dois lados jogam perfeitamente. O jogo da velha é empate; em 1988 mostrou-se que no lig 4 vence o primeiro jogador, e em 2007 que as damas são empate. O reversi (Othello) foi anunciado como empate em 2023, mas esse resultado é contestado.","O número de posições possíveis fica em torno de 10 elevado a 44 no xadrez e passa de 10 elevado a 170 no go — muito mais que os átomos do universo (cerca de 10 elevado a 80, diz-se). O xadrez e o go continuam sem solução."],"cap":["Posições possíveis (potências de dez, escala logarítmica). Jogo da velha, lig 4, damas e reversi estão resolvidos (✓); xadrez e go não (?)"]},{"h":"Experimente","p":["No xadrez, nas damas, no go e no lig 4 deste Atlas você pode jogar contra o computador. Comece com um adversário fácil e vá subindo de nível.","A IA dos jogos do Atlas funciona com um motor de raciocínio comum chamado Praline. Imaginar a máquina lendo lances à frente enquanto você joga dá à partida outro tipo de graça."],"cap":[]}],"tl":[["1770","É apresentado «o Turco» (fraude com um jogador escondido)"],["1912","A máquina de finais de xadrez de Torres Quevedo"],["1950","Artigo de Shannon sobre ler à frente no xadrez"],["1997","Deep Blue vence Kasparov"],["2016","AlphaGo vence Lee Sedol por 4–1"]],"figL":{"time":[["1770","O Turco","fraude: um jogador escondido"],["1912","El Ajedrecista","joga R+T contra R sozinho"],["1950","Shannon, Turing","ler à frente no xadrez"],["1959","Samuel","aprendizado com damas"],["1994","Chinook","damas; resolvidas em 2007"],["1997","Deep Blue","vence Kasparov"],["2016","AlphaGo","vence Lee Sedol 4–1"],["2017","AlphaZero","aprende só com as regras"]],"tree":["Máquina: escolhe o maior","Adversário: o menor","Galhos não lidos"],"solved":[["Jogo da velha","empate"],["Lig 4","1.º vence, 1988"],["Damas","empate, 2007"],["Reversi","empate, 2023"],["Xadrez","sem solução"],["Go","sem solução"]]}}};
